quests[9635] = { id = 9635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schockdrosselnde Partikelextraktor!", description = "Das Sumpfgas ist wirklich erstaunlich und kann sehr nützlich sein, Mann! Aber zuerst müsst Ihr in der Lage sein, es aufzusaugen, und dazu, mein Freund, braucht Ihr einen schockdrosselnden Partikelextraktor.\n\nNun, ich könnte Euch einfach die Baupläne geben, aber erst will ich etwas dafür haben. Wie wär's mit ein paar Ersatzteilen? Als ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der kaputten Dampfpumpe im Todesmoor herum, ganz im Nordosten.\n\nIch habe gehört, dass die siechenden Riesen die Teile überall in dem ausgetrockneten See verteilt haben.", sourceObjective = "Bringt 15 Dampfpumpenteile zu Mack Dyver in Zabra'jin in den Zangarmarschen.", progress = "Habt Ihr die Teile schon? Ich bin hier mit Tauchen beschäftigt.", completion = "Schön! Wenn wir jetzt noch einen Kaugummi, eine Wäscheklammer, Schrumpfschlauch und etwas klebriges Geschenkband hätten, könnten wir wirklich etwas daraus machen!\n\nOk, ok, ich glaube, Ihr habt Euch das verdient, {name}. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9636] = { id = 9636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schockdrosselnde Partikelextraktor!", description = "Habt Ihr das Sumpfgas gesehen? Ist es nicht einfach klasse?\n\nMan braucht jedoch einen schockdrosselnden Partikelextraktor, um es aufzusaugen. Ich könnte Euch die Pläne dafür geben, aber zuerst brauche ich ganz dringend ein paar Ersatzteile, um ein paar Sachen hier zu reparieren.\n\nAls ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der Dampfpumpe im Todesmoor im Nordosten herum. Ich glaube, die siechenden Riesen haben die Pumpe kaputtgemacht.\n\nWollen wir uns gegenseitig helfen?", sourceObjective = "Bringt 15 Dampfpumpenteile zu K. Lee Kleinkram in Telredor in den Zangarmarschen.", progress = "Habt Ihr die Teile schon? Ich muss die Kompressionsspule reparieren, bevor Anachoret Ahuurn mir im Nacken sitzt!", completion = "Klasse! Und mal ehrlich, welcher Ingenieur hat je genug Ersatzteile zur Hand? Hey, vielleicht könnte ich ja ein paar von den übrigen Teilen verkaufen und mir etwas von Tigule und Forors Erdbeereiscreme holen?! Ich liebe Erdbeeren! Denkt Ihr, man bekommt die hier irgendwo?\n\nOk, ok, Ich glaube, Ihr habt Euch das verdient, {name}. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9637] = { id = 9637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalynnas Bitte", description = "Ich habe die Kirin Tor verlassen, weil ich nach Wissen strebte, das von meinem Orden verboten wurde. Es ist mehr als ironisch, dass ich nun gebeten werde, sie mit genau diesem Wissen zu unterstützen.\n\nWenn ich Euch diesen Gefallen tun soll, dann müsst Ihr erst etwas für mich tun. Beschafft mir die beiden Folianten, nach denen ich schon so lange suche.\n\nDer erste heißt Dämmerfoliant und gehört dem orcischen Hexenmeister Nethekurse. Der zweite ist als Buch der vergessenen Namen bekannt und gehört einem Arakkoa namens Dunkelwirker Syth.", sourceObjective = "Kalynna Lathred möchte, dass Ihr den Dämmerfolianten vom Großhexenmeister Nethekurse in den Zerschmetterten Hallen der Höllenfeuerzitadelle und das Buch der vergessenen Namen von Dunkelwirker Syth in den Sethekkhallen in Auchindoun besorgt.\n\nIhr müsst diese Quest auf dem Schwierigkeitsgrad 'Heroisch' abschließen.", progress = "Habt Ihr die Folianten, die ich suche, {name}?", completion = "Ausgezeichnet, {name}. Ich versuche schon seit sehr langer Zeit, an diese Bücher heranzukommen. Welch Glück, dass wir uns gegenseitig helfen konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9638] = { id = 9638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In guten Händen", description = "Hätte ich nach diesem Tagebuch suchen sollen? Das kann nicht sein... Ich erinnere mich nicht daran...\n\nAber natürlich! Ihr meint Gradav. Er war auf der Suche nach dem Buch, als ich hierher kam. Er hat es bestimmt schon gefunden, warum fragt Ihr ihn nicht einmal?\n\nIch würde Euch ja helfen... aber diese Bücher sind einfach so... interessant!", sourceObjective = "Sprecht mit Gradav in der Bibliothek des Wächters in Karazhan.", completion = "Seht Ihr nicht, dass ich hier beschäftig bin? Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[9639] = { id = 9639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamsis", description = "Tagebuch? Welches Tagebuch? Ihr meint sicher Kamsis!\n\nGeht und fragt sie danach. Ich kann mein Projekt jetzt nicht allein lassen, sonst geht meine ganze Arbeit verloren!", sourceObjective = "Sprecht mit Kamsis in der Bibliothek des Wächters in Karazhan.", completion = "Dieses Tagebuch von dem Ihr sprecht... Ich wurde hierher geschickt, um danach zu suchen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[9640] = { id = 9640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arans Schemen", description = "Lasst mich kurz nachdenken. Das Violette Auge... Medivhs Tagebuch... Oh ja, jetzt erinnere ich mich.\n\nIch glaube, ich hatte das Tagebuch, nach dem Ihr sucht, bevor ich anfing, diese Schriftrollen zu lesen...\n\nAran... genau, Aran hat mich darum gebeten. Und das auch noch so nett. Ich musste es ihm einfach geben. Schließlich ist er Medivhs Vater, wusstet Ihr das?", sourceObjective = "Beschafft Medivhs Tagebuch und kehrt zu Kamsis in der Bibliothek des Wächters in Karazhan zurück.", progress = "Wart Ihr nicht auf der Suche nach einem Tagebuch oder so?", completion = "Habt Ihr gefunden, was Ihr gesucht habt? Ihr habt doch etwas gesucht, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[9641] = { id = 9641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestrahlte Kristallsplitter", description = "Der Absturz der Exodar hat auf der Blutmythosinsel überall Stücke schädlicher Kristalle verstreut, die das Wasser und den Rest des Landes verderben.\n\nWir haben sogar schon Stücke der Kristalle im Fleisch von Tieren gefunden, die uns normalerweise als Nahrungsquelle dienen. Ich habe einen Weg gefunden, wie man die Splitter reinigen und somit in zweckmäßige Kristalle verwandeln kann. Wenn Ihr mir genug Splitter besorgt, werde ich Euch einen vollständigen Kristall im Tausch dafür geben. Bislang konnte ich die Splitter in den Körpern von Bären, Felshetzern, Faltern und Treants finden, die den verderbten Teil der Insel bewohnen.", sourceObjective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr ihm 10 bestrahlte Kristallsplitter bringt.", progress = "Konntet Ihr Kristallsplitter von den Kreaturen der Blutmythosinsel einsammeln?", completion = "Gut gemacht. Diese Splitter werden als Rohmaterial für weitere Stärkungskristalle dienen.\n\nIhr könnt Euch einen der drei Typen aussuchen, die ich herstellen kann. Ich finde sie alle recht nützlich, je nachdem auf welche Beute man es abgesehen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9642] = { id = 9642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr bestrahlte Kristallsplitter", progress = "Solltet Ihr noch über mehr bestrahlte Kristallsplitter verfügen, tausche ich sie gerne gegen einen weiteren meiner Kristalle ein.", completion = "Sehr schön, hier sind meine Kristalle, {name}. Verwendet sie weise." }
quests[9643] = { id = 9643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Würgeranken", description = "Ein guter Förster findet für jede der vorhandenen Ressourcen eine Verwendung, {class}. Auch die skurrilsten Kreaturen besitzen Eigenschaften, die wir zu unserem Vorteil nutzen können.\n\nDa die Blutwacht ständig von den Sonnenfalken angegriffen wird, suchen wir nach einer Vielzahl natürlicher Verteidigungsmechanismen, die auch als Fallen dienen können. Die dornigen Ranken der Peitscher eignen sich perfekt für den Bau von Fallen, die meiner Vorstellung entsprechen. Die Kombination von scharfen Dornen und tödlichem Gift wird unachtsame Angreifer ausschalten. Bringt mir Ranken von mutierten Würgern, damit ich mit der Arbeit beginnen kann.", sourceObjective = "Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr ihm 6 dornige Würgeranken bringt.", progress = "Habt Ihr die Würgeranken bekommen?", completion = "Das scheint mir stabil genug für meine Konstruktion. Danke für die Hilfe, {name}. Eure Unterstützung bei der Verteidigung der Blutwacht wird nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9644] = { id = 9644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken der Nacht", description = "Ihr habt Euren Teil der Abmachung eingehalten. Ich werde Eure Essenz nun an die des getöteten blauen Drachen binden.\n\nAuf der Terrasse des Meisters steht eine Urne. Solltet Ihr sie berühren, wird die freigesetzte Energie die verkohlten Überreste von Arcanagos wieder zum Leben erwecken. Besiegt die Kreatur und entzieht ihr sofort ihre Essenz! Ihr werdet sie zu Alturus bringen müssen.\n\nWenn Ihr scheitert, sagen die Sterne voraus, werdet Ihr ein großes Unheil auf die Himmel loslassen.\n\nEin Unheil namens Schrecken der Nacht!", sourceObjective = "Geht zur Terrasse des Meisters in Karazhan und berührt die geschwärzte Urne, um den Schrecken der Nacht zu rufen. Entzieht dem Körper des Schreckens die schwache arkane Essenz und bringt sie zu Erzmagier Alturus.", completion = "Das ist erstaunlich! Ihr habt nicht nur Medivhs Tagebuch zurückgebracht, sondern auch noch einen Teil seiner Essenz!\n\nSo schwach sie auch sein mag, sie wird uns wertvolle Informationen über Medivh liefern können. Wir werden Euch das nicht vergessen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9645] = { id = 9645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse des Meisters", description = "Tagebuch? Welches Tagebuch?\n\nOh, richtig. Dieses Tagebuch! Das Violette Auge hat mich deswegen hierher geschickt. Ich erinnere mich.\n\n<Kamsis zeigt auf eine Seite im Tagebuch>\n\nDies ist die Seite, an der Alturus interessiert ist. Wusstet Ihr, dass andere Leute Tagebücher benutzen, um ihre Erinnerungen aufzuzeichnen, während Medivhs Tagebuch genau seine Erinnerungen sind?\n\nProbiert es aus. Geht zur Terrasse des Meisters und lest die Seite. Ihr werdet sehen, was ich meine. Wenn Ihr schon da seid, könnt Ihr auch gleich Alturus Bericht erstatten. Ich fürchte, ich bin hier noch eine Weile beschäftigt.", sourceObjective = "Geht zur Terrasse des Meisters in Karazhan und lest Medivhs Tagebuch.", progress = "Ihr seid zurück! Was für Nachrichten bringt Ihr?", completion = "Es ist eine Schande, dass die Agenten, die wir geschickt haben, Karazhans Magie unterlegen sind. Zumindest konntet Ihr beschaffen, wonach sie suchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9646] = { id = 9646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Todespranke", description = "Auf Anweisung von Herold Mikolaas: Man wird demjenigen ein Kopfgeld auszahlen, der den Beweis für den Tod des räuberischen Bären Todespranke erbringen kann.\n\nTodespranke wird als besonders gefährlich eingestuft und ist für den Tod eines Vermessungsteams an der Küste im Nordwesten der Blutwacht verantwortlich. Reisende werden angehalten, diese Gegend zu meiden.", sourceObjective = "Bringt Todesprankes Tatze zu Herold Mikolaas bei der Blutwacht.", progress = "Wie kann ich Euch helfen, {class}?", completion = "Gut gemacht. Von dem, was ich gehört habe, war es wohl kein leichter Kampf. Ihr habt Euch Eure Belohnung mehr als verdient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9647] = { id = 9647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausmerzen der Falter", description = "Als wir den Faltern das erste Mal auf der Insel begegneten, zeigten sie nur wenige Anzeichen von Mutation. Als sich die Verderbnis immer weiter ausbreitete, wurden die Motten und andere Arten jedoch immer mehr verseucht.\n\nEs ist jetzt sogar so weit gekommen, dass sie fast alles, mit dem sie in Berührung kommen, beschädigen. Der Schaden wird von den Kristallsplittern, die beim Absturz der Exodar zerbrochen wurden, noch verstärkt. Uns bleibt keine andere Wahl, aber wir müssen die Motten, die das Land nördlich der Blutwacht behausen, ausmerzen.", sourceObjective = "Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr 10 königsblaue Falter tötet.", completion = "Es gilt jetzt, eine längerfristige Lösung zu finden, um die Arten wieder in ihren Urzustand zurückzuführen. Momentan ist das zeitweilige Ausmerzen ihres Bestandes jedoch die beste Methode. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9648] = { id = 9648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzsammlung von Maatparm", description = "Habt Ihr gewusst, dass das Sammeln von Pilzen gefährlicher als der Verzehr von Pilzen ist? Pilzsammler begeben sich ins Unbekannte - dazu kommen noch die Gefahren, die in der Wildnis lauern!\n\nWas wäre das Leben ohne ein paar Wagnisse? Ich benötige Pilze für meine Sammlung. In dieser unerforschten Natur werdet Ihr vier Arten finden: Wasserstinkmorchel, Blutpilz, ruinöser Birkensporling und Teufelszapfenfungus. Sie sind einzigartig in unterschiedlichen Gebieten der Blutmythosinsel. Bringt sie mir.", sourceObjective = "Maatparm bei der Blutwacht möchte 1 Wasserstinkmorchel, 1 Blutpilz, 1 ruinösen Birkensporling und 1 Teufelszapfenfungus.", progress = "Vergesst nicht, die von mir benötigten Pilze sind einzigartig in unterschiedlichen Gebieten der Blutmythosinsel.", completion = "Nun, ich hatte Euch gewarnt - oder etwa nicht? Ich hoffe diese kleine Bezahlung wird Euch für Eure Unannehmlichkeiten etwas entschädigen können. Kehrt zu mir zurück, sobald Ihr Euch ein wenig erholt habt, dann habe ich vielleicht noch eine Aufgabe für Euch - mit Pilzen natürlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[9649] = { id = 9649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yseras Tränen", description = "Gut, Euch wiederzusehen, {name}! Ihr wart bei meiner letzten Aufgabe sehr tüchtig. Seid Ihr vielleicht an einer weiteren interessiert?\n\nIm Nordosten liegt die Insel Drachenfels, sie beheimatet eine sehr seltene Pilzart, die unter dem Namen Yseras Träne bekannt ist - benannt nach den grünen Drachlingen, die auf dieser Insel hausen. Ich brauche nicht viele von diesen Pilzen, möchte Euch aber dennoch warnen, denn die Bewohner dieser Insel mögen keine Besucher. Gebt auf Eure Schritte Acht.", sourceObjective = "Maatparm bei der Blutwacht möchte 2 Yseras Tränen.", progress = "Schon wieder zurück?", completion = "Ich hoffe diese Aufgabe hat nicht zu viel von Euch abverlangt, {name}. Ihr habt erneut bewiesen, dass Ihr ein fähiger und aufmerksamer {race} seid. Habt meinen Dank und natürlich eine kleine Abfindung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9650] = { id = 9650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Zunahme", description = "Lasst uns meine magischen Eigenschaften verstärken. Das macht Sinn. Schließlich war ich, als ich noch am Leben war, eine Zauberin.\n\nNur weil man in einer Waffe gefangen ist, heißt das noch lange nicht, dass man ein Rüpel sein muss.\n\nIch möchte, dass Ihr ein paar Materialien sammelt.", sourceObjective = "<TXT>", sourceObjectiveStatus = "unverified-source-field" }
quests[9651] = { id = 9651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Zunahme", description = "Lasst uns meine magischen Eigenschaften verstärken. Das macht Sinn. Schließlich war ich, als ich noch am Leben war, eine Zauberin.\n\nNur weil man in einer Waffe gefangen ist, heißt das noch lange nicht, dass man ein Rüpel sein muss.\n\nIch möchte, dass Ihr ein paar Materialien sammelt.", sourceObjective = "<TXT>", sourceObjectiveStatus = "unverified-source-field" }
quests[9652] = { id = 9652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körperliche Erweiterung", description = "Ich hätte nichts dagegen... Wir können genauso gut das Beste aus dieser Lage machen... in meinem Fall die Tatsache, dass ich eine Waffe bin. Ich könnte einfach die beste Waffe werden, die ich sein kann.\n\nJa, lasst uns das versuchen. Einen schärferen Schliff, einen stärkeren Griff... das klingt doch gut.\n\nIch möchte, dass Ihr ein paar Dinge für mich sammelt." }
quests[9653] = { id = 9653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körperliche Erweiterung", description = "Ich hätte nichts dagegen... Wir können genauso gut das Beste aus dieser Lage machen... in meinem Fall die Tatsache, dass ich eine Waffe bin. Ich könnte einfach die beste Waffe werden, die ich sein kann.\n\nJa, lasst uns das versuchen. Einen schärferen Schliff, einen stärkeren Schwertgriff... das klingt doch gut.\n\nIch möchte, dass Ihr ein paar Dinge für mich sammelt." }
quests[9654] = { id = 9654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gut abgerundete Verteidigung", description = "Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.\n\nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.", sourceObjective = "Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9655] = { id = 9655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilende Verstärkung", description = "Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.\n\nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.", sourceObjective = "Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.", sourceObjectiveStatus = "unverified-source-field" }
