quests[9661] = { id = 9661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gut abgerundete Verteidigung", description = "Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.\n\nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.", sourceObjective = "Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9662] = { id = 9662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keannas Freiheit", description = "Meine Erinnerungen... ich kann mich wieder an alles erinnern! Mein Geist fühlt sich an, als würden Puzzleteile wieder zusammengefügt.\n\nIch war eine der Ersten, die nach Karazhan geschickt wurden, um hier Nachforschungen anzustellen, nachdem sich der Ort verändert hatte. Der Dämon Malchezaar hat mich entdeckt.\n\nIch habe schnell bemerkt, dass ich für ihn kein Gegner bin. Ich könnte fühlen, wie seine Magie meine Seele einfing.\n\nIm letzten Moment habe ich einen Teil meiner Selbst, meiner Erinnerungen versteckt... an dem einzigen Ort, der mir einfiel: meine Waffe. Malchezaar hat meine Seele. Ihr müsst mir helfen, sie zurück zu bekommen!", sourceObjective = "Besiegt Malchezaar in Karazhan während Ihr Keannas Wille angelegt habt. Keannas Erscheinung muss überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9663] = { id = 9663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Korsallauf", description = "Ihr kommt gerade richtig, {name}. Die Aktivitäten der Blutelfen haben sich in der letzten Woche fast verdoppelt. Unsere Agenten haben uns mitgeteilt, dass die Blutelfen, die sich selbst Sonnenfalken nennen, einen baldigen Angriff auf die Azurmythosinsel planen. Ihr müsst unseren Verbündeten und Landsmännern eine Warnung zukommen lassen.\n\nWarnt den Oberhäuptling bei der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus' Ankerplatz.\n\nDie Zeit drängt, deshalb werde ich Euch meinen Elekk zur Verfügung stellen. Beeilt Euch!", sourceObjective = "Kessel bei Kessels Wegelager möchte, dass Ihr den Oberhäuptling Tannenruh bei der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus' Ankerplatz vor der unmittelbar bevorstehenden Blutelfeninvasion warnt. Ihr habt 15 Minuten. Kehrt anschließend zu Kessel zurück. Denkt daran, dass Elekks wasserscheu sind!", completion = "Gut gemacht, {name}. Dies war ein Test Eurer Fähigkeiten, aber Ihr habt mit wehenden Fahnen bestanden. Um ein Soldat der Hand von Argus zu werden, gilt es viele dieser Tests zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9664] = { id = 9664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Befestigungen", description = "Willkommen in den Pestländern, {name}. Wie Ihr wisst, behaupten sich die Verlassenen und ihre Verbündeten entgegen all unserer Anstrengungen in den von hier aus westlich gelegenen Ländern. Die Kommandanten der Allianz haben beschlossen, dass hier im Osten neue Befestigungen errichtet werden sollen, um die Schlinge um unseren Feind noch etwas enger zu schnüren.\n\nLange seit den Tagen Lordaerons verlassene und herrenlose Türme müssen für diesen Zweck erobert und wieder aufgebaut werden. Diese Länder hier sind gefährlich, wir brauchen Eure Hilfe.", sourceObjective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den Östlichen Pestländern. Kehrt anschließend zum Abgesandten Weißbart bei der Kapelle des Hoffnungsvollen Lichts zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9665] = { id = 9665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering Our Defenses" }
quests[9666] = { id = 9666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtdemonstration", description = "Habt Ihr die Schlangenwesen gesehen? Die, die sich selbst Naga nennen?\n\n<Kessel spuckt.>\n\nSie haben es vor drei Nächten gewagt, im Schutze der Dunkelheit bis zu diesem Lager vorzudringen. Denkt nur an die Dreistigkeit dieser primitiven Biester!\n\nIhr müsst ihrem Anführer eine Botschaft überbringen, {name}. Im Nordosten liegt die Hassprankenzuflucht, der Sitz von Lord Xiz. Findet ihn, tötet ihn an Ort und Stelle und treibt diesen Banner durch seinen Körper.\n\nLasst sie vor Furcht erschaudern, wann immer sie diese Standarte sehen!", sourceObjective = "Kessel bei Kessels Wegelager auf der Blutmythosinsel möchte, dass Ihr Lord Xiz bei der Hassprankenzuflucht tötet und das Banner der Draenei durch seinen Körper stoßt.", completion = "Es tut mir leid, dass Ihr das tun musstet, {name}. Rohe Gewalt entspricht nicht der Natur der {race}, aber manchmal ist sie der einzige Weg.\n\nUnglücklicherweise gehört dies zum Leben und man versteht es oft erst dann, wenn es zu spät ist. Genau wie mit den Orcs, die unsere Brüder und Schwestern abschlachteten.\n\nEin Mitglied der Hand von Argus zu werden, ist ein Prozess der Wiedergeburt. Mit der Geburt kommt bekanntlich auch der Schmerz...", sourceObjectiveStatus = "unverified-source-field" }
quests[9667] = { id = 9667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Prinzessin der Tannenruhfeste", description = "Helft mir, {name}! Die Sichelklauen haben mich gefangen genommen und wollen mich ihren üblen Göttern opfern!\n\nDer Oberhäuptling der Sichelklauen ist in Besitz der Schlüssel für den Käfig. Damit er auftaucht, müsst Ihr die bösartigen Furbolgs der Sichelklauen töten, die in der Enklave hausen. Sie liegt zwei Lager weiter im Westen. Wenn Ihr genug von ihnen niedergestreckt habt, wird er kommen, um sich zu rächen! Tötet ihn, sobald er sich zeigt, und nehmt die Schlüssel an Euch!\n\nMein Vater wird Euch reichlich entlohnen, wenn Ihr es schafft mich zu rettet!", sourceObjective = "Befreit die Prinzessin der Tannenruhfeste aus ihrem Käfig und sprecht anschließend mit Botschafter Frasaboo der Tannenruhfeste bei der Blutwacht.\n\nIhr müsst den Oberhäuptling der Sichelklauen töten, um an den Schlüssel für den Käfig zu gelangen.", completion = "Ihr habt erneut bewiesen, dass Ihr all dem entsprecht, was in der Prophezeiung vorhergesagt wurde. Ihr habt den ewigen Dank des Oberhäuptlings, {name} - und Ihr habt die Wahl zwischen diesen Relikten der Tannenruhfeste...", sourceObjectiveStatus = "unverified-source-field" }
quests[9668] = { id = 9668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstattet Exarch Admetius Bericht", description = "Ein Soldat der Hand von Argus ist vielerlei: gehorsam, mutig, intelligent und vor allem ehrenhaft. Vielleicht verfügt Ihr schon jetzt über einige dieser Züge, {class}.\n\nErstattet Exarch Admetius bei der Blutwacht Bericht, wenn Ihr der Hand noch immer beitreten möchtet. Er und seine Untergebenen werden Euch weiter auf dem Weg zum Draeneisoldaten ausbilden.\n\nUnd vergesst dies nicht, {name}: Ehrenhafte Personen handeln nicht immer ehrenhaft. Manchmal ist es ihnen nicht möglich.\n\nIhr findet die Blutwacht ganz einfach diese Straße entlang, in Richtung Norden.", sourceObjective = "Sprecht mit Exarch Admetius bei der Blutwacht.", completion = "Ich hatte es bereits im Gefühl, dass Ihr es bis hierher schaffen würdet, {class}. Wenn Ihr noch weiter kommen möchtet, bin ich gerne bereit Euch zu unterrichten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9669] = { id = 9669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsreise in den Tod", description = "Vor etwa einer Woche war ich mit meinem Forschungsteam auf einem Erkundungstrip im Westen der Blutmythosinsel, als wir plötzlich von blutdurstigen Spinnen angegriffen wurden. Die Auswirkungen der Kristallverseuchung waren unverkennbar, da diese Spinnen extrem groß und aggressiv waren.\n\nIch schaffte es zu fliehen, aber mein Team hatte nicht so viel Glück. Wir dürfen nicht zulassen, dass andere das gleiche Schicksal ereilt. Geht nach Westen zum Goldweberpass und vernichtet die Spinnen und ihre Matriarchin Zarakh.", sourceObjective = "Tötet 8 Mythosspinner, 8 Mythosfänger und ihre Anführerin Zarakh. Kehrt anschließend zu Achelus zurück.", completion = "Unglaublich! Konntet Ihr andere Überlebende finden?\n\n<Achelus senkt seine Stimme zu einem Flüstern.>\n\nIch möchte ehrlich mit Euch sein, {name}, niemand sonst wollte diesen Auftrag annehmen. Ihr seid sehr mutig, {class}...", sourceObjectiveStatus = "unverified-source-field" }
quests[9670] = { id = 9670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie leben! Vielleicht...", description = "Es war ein blutiges Gemetzel, {name}. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.\n\nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!\n\nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?\n\nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!", sourceObjective = "Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.", completion = "Ihr habt mehr als die Hälfte des Teams befreit! Der Exarch und die anderen bei der Blutwacht werden mit Sicherheit von Eurer heldenhaften Tat erfahren. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9671] = { id = 9671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Nachricht", sourceObjective = "Seid Ihr {name}? Es wurde auch Zeit! Ich war gerade dabei, die Suche nach Euch aufzugeben!\n\nBeim Briefkasten wartet eine dringende Nachricht auf Euch. Die Person, die sie mir übergeben hatte, war ein Admiral der Menschen von der Azurmythosinsel. Admiral Odesy-irgendwas... der Name ist mir entfallen. Er sagte, Ihr würdet wissen, wer er sei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9672] = { id = 9672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Blutfluchs", description = "Getreuer Freund,\n\nmeine Hand zittert beim Schreiben dieses Briefs. Ich hoffe, dass er Euch rechtzeitig erreicht.\n\nLetzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.\n\nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich von Eurer Basis liegt, suchen?\n\nGruß,\n\nAdmiral Odesyus", sourceObjective = "Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.", completion = "Habt Ihr von dem Blutfluch gehört, Landratte? Nein, natürlich nicht. Der Blutfluch ist das, was all diese Schiffe hat sinken lassen. Der verderbte, entweihte Teil des Wassers hier wird Riff des Blutfluchs genannt - ein Teil der Welt, den Ihr niemals sehen möchtet. Ich bin hier selbst seit 20 Jahren.\n\nSkorbut, so ein Quatsch! Ich starb an diesen Wilden Ufern als Drachenfutter... Ah, das ist wieder eine andere Geschichte, für ein anderes Mal. Jetzt müssen wir den armen Seelen helfen, die hier im Riff gefangen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9673] = { id = 9673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestienausbildung", description = "Nachdem Ihr nun alles über die Zähmung eines Tieres wisst, ist es an der Zeit, sich mit den Feinheiten der Pflege und Ausbildung Eures Begleiters vertraut zu machen. Sucht dazu Halthenis den Tierausbilder von Silbermond auf, er wird Euch alles Nötige beibringen.\n\nEr respektiert meine Schüler in höchstem Maße, solange Ihr Euch ihm gegenüber genauso respektvoll verhaltet. Enttäuscht mich also nicht.", sourceObjective = "Sprecht mit Halthenis in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9674] = { id = 9674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Naga des Blutfluchs", description = "Man sagt, dass dieses Land am lautesten geschrien hat, als die Welt geteilt wurde. Hier fielen tausende von Nachtelfen und an ihrer Stelle erhoben sich fürchterliche Kreaturen des Hasses - die Naga.\n\nIhrer wahnsinnigen Königin, Azshara, gehorsam ergeben, würden sie alles und jeden zerstören, der sich durch ihre Gewässer wagt. Es würde noch für tausende von Jahren so bleiben - bis zum heutigen Tag.\n\nZuerst gilt es die Naga des Blutfluchs aus dem Riff zu entfernen.", sourceObjective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 10 Naga des Blutfluchs tötet.", completion = "Ein guter Anfang, aber es gibt noch viel mehr zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[9675] = { id = 9675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestienausbildung", description = "Oh, da wäre noch etwas! Ihr solltet mit Ganaar bei der Exodar sprechen. Er wird Euch das letzte bisschen Wissen bezüglich der Pflege und Ausbildung Eures Begleiters lehren.\n\nIhr findet ihn in der südwestlichen Ecke der Händlertreppe.", sourceObjective = "Sprecht mit Ganaar bei der Händlertreppe der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9676] = { id = 9676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Paladin", description = "Mit dem Voranschreiten in Eurer Klasse, möchtet Ihr sicherlich von der Ausbildung profitieren, die Euch der Lehrer für Eure Klasse anbieten kann. Jesthenis Sonnensturm ist der Lehrer für junge Paladine hier auf der Insel der Sonnenwanderer. Sprecht mit Jesthenis und seht, welche Ausbildung er Euch anbieten kann. Es wird Euch etwas kosten, bringt also ein wenig Geld mit Euch.\n\nEuer Lehrer - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - befindet sich im unteren Teil des Sonnenturms.", sourceObjective = "Sprecht mit Jesthenis Sonnensturm - dem Paladinlehrer - im Sonnenturm auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9677] = { id = 9677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufforderung des Ritterfürsten Heldenblut", description = "{name}, Ihr habt Euch in Eurer frühen Ausbildung bereits selbst übertroffen und von den anderen, die Blutritter werden möchten, hervorgehoben. Ihr seid reif für die nächste Ausbildungsphase und dazu kommt, dass Ritterfürst Heldenblut höchstpersönlich nach Euch verlangt hat.\n\nIch zweifle nicht daran, dass Ritterfürst Heldenblut Eure Fähigkeiten und Eure Ausbildung einer Prüfung unterziehen möchte. Ihr findet ihn beim Hauptsitz der Blutritter in Silbermond beim Platz der Weltenwanderer. Alles Gute, {name}.", sourceObjective = "Sprecht mit Ritterfürst Heldenblut beim Platz der Weltenwanderer in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9678] = { id = 9678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Prüfung", description = "Ihr habt viel über das Kämpfen und Vergießen von Blut gelernt, Initiand, doch in unserem Orden geht es um viel mehr.\n\nDie Beherrschung des Lichts erfordert einen klaren Geist und enorme Willenskraft.\n\nOhne diese Eigenschaften seid Ihr nicht mehr wert als ein räudiger Streuner.\n\nAn den nordöstlichen Ausläufern der Geisterlande gibt es eine Insel, die Insel des Martyriums, auf der wir diese Eigenschaften formen. Versteckt in einer kleinen Höhle, steht eine Kohlenpfanne. Kniet vor ihr, entzündet sie und konzentriert Euch auf das, was Ihr vor Euren Augen seht.", sourceObjective = "Reist zu der Insel, die Euch Ritterfürst Heldenblut beschrieben hat, sucht die Höhle und entzündet die Kohlenpfanne. Kehrt, nachdem Ihr die erste Prüfung bestanden habt, zu Ritterfürst Heldenblut in Silbermond zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9679] = { id = 9679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Ritterfürst Heldenblut", description = "Der Angreifer ist tot, doch seine letzten Worte lassen es so erscheinen, als wäre seine Anwesenheit hier kein Zufall. Wahrscheinlich war es ein Teil der Prüfung, von der Ritterfürst Heldenblut gesprochen hatte.\n\nJetzt, wo Ihr diese Feuerprobe bestanden habt, solltet Ihr Euch auf den Rückweg nach Silbermond machen und Ritterfürst Heldenblut Bericht erstatten.", sourceObjective = "Erstattet Ritterfürst Heldenblut in Silbermond Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9680] = { id = 9680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit aufwühlen", description = "Kamsis hatte Recht! Diese Information ist äußerst wichtig. \n\nWenn Medivh seine eigene Essenz in die Magie, die er benutzt hat, um den Drachen zu besiegen, hineingewebt hat, dann ist es ziemlich wahrscheinlich, dass wir einen schwachen Rest dieser Essenz aus den Überresten des Drachen gewinnen können. Welch großartige Erkenntnisse mögen wohl unter der Asche des Gebirgspass der Totenwinde liegen, die nur darauf warten, entdeckt zu werden.\n\nGeht zu den Bergen südlich von Karazhan und bringt mir ein Knochenfragment deutlich drachischen Ursprungs.", sourceObjective = "Erzmagier Alturus möchte, dass Ihr zu den Bergen südlich von Karazhan im Gebirgspass der Totenwinde geht und ein verkohltes Knochenfragment besorgt.", progress = "Habt Ihr das Knochenfragment, das ich brauche, {name}?", completion = "Ausgezeichnet! Auch wenn es klein ist, strotzt es nur so vor Energie, ich fühle es!", sourceObjectiveStatus = "unverified-source-field" }
quests[9681] = { id = 9681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Studie der Macht", description = "Haltet mich nicht für übermäßig grausam, {name}. Stillstreich hat sehr wohl gewusst, worauf er sich einlässt. Er verstand und akzeptierte seine Pflicht und wurde so ein leuchtendes Vorbild für alle aufstrebenden Blutritter.\n\nMeine Worte sind nicht als Grabesrede gedacht, {name}. Stillstreichs Dienste für uns gehören noch lange nicht der Vergangenheit an und Ihr werdet das Instrument seiner Wiederauferstehung sein.\n\nEure Ausbildung in der Kunst des Ordens hat gerade erst begonnen. Angesichts Kael'thas' Verrat und des Verlusts unserer Energiequelle, müsst Ihr neue Wege zur Beherrschung des Lichts erlernen. Sucht Magister Astalor Blutschwur auf.", sourceObjective = "Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9682] = { id = 9682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnungslosen...", description = "An einem Vorsprung des Riffs, noch tiefer im Wasser als die Naga des Blutfluchs, werdet Ihr die Hoffnungslosen finden: Reisende des Blutfluchs, Geister derer, die vom Blutfluch heimgesucht wurden.\n\nEs ist bedauerlich, was ich jetzt von Euch verlangen werde... aber sie müssen vernichtet und ihre Hüllen des Blutfluchs zu mir gebracht werden.\n\nIhre Seelen müssen erlöst werden. Kehrt zu mir zurück, wenn Ihr dergleichen getan habt und ich werde Euch eine letzte Aufgabe stellen.", sourceObjective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 4 Seelen des Blutfluchs zu ihm bringt.", progress = "Trauert ihrem Niedergang nicht nach, {name}.", completion = "Ihr habt den Hoffnungslosen einen großen Dienst erwiesen, {name}. Es gilt jedoch noch eine letzte Aufgabe zu erledigen: Tötet den Anführer des Blutfluchs.", sourceObjectiveStatus = "unverified-source-field" }
quests[9683] = { id = 9683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beendigung des Blutfluchs", description = "Im Süden findet Ihr die Insel des Blutfluchs. Oben auf der Insel befindet sich ein Schrein, der der von den Naga geliebten Königin, Azshara, gewidmet wurde. Zerstört die Statue - verbrennt das Abbild! Dies wird mit Sicherheit den Zorn von Anführer Atoph des Blutfluchs erwecken.\n\nTötet Atoph und kehrt zu mir zurück!", sourceObjective = "Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr die Statue der Königin Azshara zerstört und Atoph des Blutfluchs tötet.", completion = "Ihr habt es geschafft! Hunderte von Seelen sind Euch für alles, was Ihr getan habt, dankbar.\n\nGestattet mir, Euch etwas zu überreichen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9684] = { id = 9684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beherrschung des Lichts", description = "Nehmt dieses Gefäß, {name}. Durch die Erweckung seiner Verzauberung werdet Ihr in der Lage sein, die letzten Überreste des Lichts, das diese Magister umgibt, für Euch zu nutzen. Sie pflegten einst den gefangenen Naaru und tragen noch immer einen Teil von dessen Energie in sich.\n\nSorgt Euch nicht um die Magister, {name}. Ich kümmere mich um ihr Wohlergehen. Lord Solanar hat mir versichert, dass Lady Liadrin selbst jetzt auf der Suche nach einer neuen Energiequelle ist.", sourceObjective = "Wendet das schimmernde Gefäß auf die Magister der Blutelfen an, um es zu füllen und kehrt anschließend zu Ritterfürst Heldenblut zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9685] = { id = 9685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung der Toten", description = "Während Ihr das Gefäß vorbereitet habt, habe ich eine Gruppe von Initianden entsandt, um Sangrias Stillstreich zu bergen. Ihr findet ihn, zusammen mit einem Ordensdiener, auf der obersten Etage des Gasthauses von Silbermond. Begebt Euch ohne Verzögerung dorthin und entfesselt die magischen Kräfte des Gefäßes, um ihn ins Leben zurückzuholen.\n\nDie Zeit drängt, {name}. Sollte er zu lange tot sein, können ihn nicht einmal mehr die Mächte des Lichts retten. Kehrt nach Stillstreichs Wiederbelebung zu mir zurück.Ihr erlernt:", sourceObjective = "Bringt das gefüllte schimmernde Gefäß zum Gasthaus von Silbermond und verwendet seine Magie, um Sangrias Stillstreich wiederzubeleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9686] = { id = 9686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Prüfung", description = "Ihr steht kurz davor, innerhalb des Ordens den Status eines Adepten zu erhalten, {name}. Zunächst werdet Ihr jedoch beweisen müssen, dass Ihr für eine solche Ehre schon bereit seid, indem Ihr eine weitere Prüfung absolviert.\n\nDie zweite Prüfung unterscheidet sich vor allem dadurch von der Ersten, dass Euch keine unliebsamen Überraschungen mehr erwarten. Die vor Euch liegende Aufgabe ist einfach; Ihr müsst Euch gegen die vier besten Champions der Blutritter im Kampf beweisen.\n\nSobald Ihr die Herausforderung annehmt, erscheint in der Mitte des Pavillons ein Kristall. Berührt ihn, um mit Eurer Prüfung zu beginnen und entfernt Euch niemals zu weit von dem Gebäude.\n\nSeid Ihr bereit?", sourceObjective = "Besteht die zweite Prüfung und besiegt Champion Rachblut, Champion Lichtrend, Champion Schnellklinge und Champion Sonnensturm im Pavillon in der Nähe von Meister Kelerun Blutpein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9687] = { id = 9687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung der Heiligkeit", description = "Es ist noch nicht lange her, da kamen die einst so friedlichen Eulkin der Umgebung an die Ufer dieser Insel. Sie kamen einer nach dem anderen, um die Knochen der gefallenen Drachen zu stehlen. Ich weiß nicht, was die Kreaturen in diese Verzweiflung getrieben hat oder warum sie die Knochen der Dahingeschiedenen wollen. Allerdings ruhen die Geister der Brut seit dieser Schändung nicht mehr.\n\nGen Westen, über die Purpurbrandung hinweg, liegt der Rachfederkamm. Reist zu den Siedlungen der Eulkin und nehmt die gestohlenen Drachenknochen wieder an Euch.", sourceObjective = "Prinz Toreth auf der Insel Drachenfels möchte, dass Ihr 8 Drachenknochen wiedererlangt.", progress = "Die Kriege der Drachen sind seit langem vorüber. Was noch bleibt, sind die Knochen und die aufgewühlten Überbleibsel von Yseras Brut.", completion = "Ein Ritual? Die Eulkin haben seit tausenden von Jahren mit dem Land in Einklang gelebt. Derartiges ist nicht normal!\n\nWie bedauerlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[9688] = { id = 9688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Traum", description = "Die Welpen, die Ihr auf dieser Insel seht, sind die ruhelosen Geister des grünen Drachenschwarms. Sie sind wie ich an das Land gebunden, außerstande ihre letzte Ruhestätte im Traum zu erreichen.\n\nDie Wiederbeschaffung der Knochen von den Gefallenen hat sie zwar etwas beruhigt, aber Ihr müsst noch mehr unternehmen.\n\nZerstört ihre astralen Erscheinungen. Ich kann diesen Ort erst verlassen, wenn es geschehen ist. Sie müssen erlöst werden!", sourceObjective = "Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr 5 Viridianwelpen und 5 Viridianbrutlinge tötet.", completion = "Wie verwerflich Eure Aufgabe auch war, es musste einfach getan werden. Jetzt müsst Ihr in das Angesicht des Bösen sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9689] = { id = 9689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messerrachen", description = "Während der Angriffe wurden viele des schwarzen Drachenschwarms getötet. Einer von ihnen, ein Offizier von Todesschwinge selbst, sucht noch immer diesen Ort heim. Blickt Ihr in den Himmel, so könnt Ihr sein spektrales Antlitz durch die Lüfte kreisen sehen. Sein Hass ist so groß, dass er sogar den Tod übersteht.\n\nNehmt die Knochen, die Ihr bereits für mich eingesammelt habt, zu der Spitze des Berges dieser Insel und platziert sie im ewig brennenden Scheiterhaufen. Dieses Signal sollte Messerrachen herabschweben lassen. Sobald er da ist, tötet sein untotes Abbild.", sourceObjective = "Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr Messerrachen tötet.", completion = "Wie lange war es noch? Tausend Jahre? Zehntausend Jahre vielleicht? Ihr habt mir und der Erinnerung meiner Leute einen großen Dienst erwiesen, {name}. Bitte, nehmt diesen mächtigen Gegenstand als Zeichen der Anerkennung von Loreth'Aran an - für Eure ehrenvollen Taten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9690] = { id = 9690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Prüfung", description = "Initiand {name}, Ihr habt hart an Euch gearbeitet, um die Macht des Lichts zu beherrschen, über die wir Dank unserer Magister verfügen. Ihr wisst nun von der Quelle unserer Fähigkeiten und alles über die Pflichten eines Blutritters.\n\nDer Zeitpunkt ist nahe, da Ihr Euch der zweiten Prüfung unterziehen werdet und Ihr um den Rang eines Adepten der Blutritter kämpfen müsst. Die Prüfung findet unter der Aufsicht von Meister Kelerun Blutpein im nördlichen Teil von Silbermond statt. Reist durch die Ruinen von Silbermond nach Norden und nehmt den östlichen Pfad, der kurz vor der Brücke abzweigt, die zur Insel der Sonnenwanderer führt.", sourceObjective = "Meldet Euch bei Meister Kelerun Blutpein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9691] = { id = 9691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Silbermond", description = "Kehrt umgehend nach Silbermond zurück und berichtet Ritterfürst Heldenblut. Eure Ankunft sollte ihm alles Notwendige über den Ausgang der Prüfung mitteilen.\n\nEr wird Euch Eure weiteren Aufgaben auf dem Weg zum Adepten erläutern. Ihr könnt stolz auf Euch sein, {name}. Viele versuchen sich an dieser Prüfung, doch nur die Wenigsten kehren zurück, um von ihrem Erfolg zu berichten.Ihr erlernt:", sourceObjective = "Kehrt zu Ritterfürst Heldenblut nach Silbermond zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9692] = { id = 9692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Adepten", description = "Bevor ein frischgebackener Adept in die Ränge der Blutritter aufgenommen wird, muss er die Materialien beschaffen, die zum Schmieden der besonderen Waffe des Ordens benötigt werden: dem blutgehärteten Ranseur.\n\nIhr müsst Euch außerdem das Recht verdienen, das Insigne unseres Ordens zu tragen. Bei der Gründung des Ordens wurde eine begrenzte Zahl dieser Insignien geschmiedet und verteilt, jeder Adept erbt sein Insigne von einem Veteran. Euer Insigne erhaltet Ihr von einem gefallenen Ritter, der einen Angriff auf die Todesfestung anführte.\n\nIch habe Notizen vorbereitet, die Euch helfen sollen.", sourceObjective = "Bringt Ritterfürst Heldenblut in Silbermond einen verderbten Koredelstein, eine Kiste mit blutgeschmiedeten Blöcken, etwas Blut des Hasserfüllten und ein Insigne der Blutritter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9693] = { id = 9693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Argus für mich bedeutet", description = "Was bedeutet Argus für Euch, {name}? Viele Draenei erinnern sich wahrscheinlich nicht mehr an unseren Heimatplaneten oder kennen ihn überhaupt nicht. Dort trennten wir uns von den Man'ari: unseren verdorbenen dämonischen Abbildern, die von Sargeras 'bedacht' wurden. Sie selbst nennen sich die Eredar.\n\nEredar... dieses Wort hatte einst eine Bedeutung.\n\n<Admetius scheint das Wort förmlich zu schmecken.>\n\nWiderlich.\n\nLasst uns nicht noch mehr Zeit verschwenden. Sucht nach Verteidiger Boros, damit Ihr mit Eurer Ausbildung beginnen könnt.", sourceObjective = "Exarch Admetius bei der Blutwacht wies Euch an, mit Verteidiger Boros zu sprechen.", completion = "Ah, {name}... ich habe bereits von Euch gehört. Ihr seid also derjenige, der den Korsallauf in unter 15 Minuten gemacht hat. Ts, wahrscheinlich nicht.\n\nSeid Ihr bereit, etwas Blut im Namen des Lichts zu vergießen? Für Velen? Für Argus?\n\n\n\nGut, gut, ich halte mich jetzt besser zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9694] = { id = 9694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutwacht", description = "Wie Ihr wisst, ist die Blutwacht einer von zwei Vorposten, die der Hand von Argus als Operationsbasen dienen. Ihr wart bereits bei der anderen Basis, der Azurwacht; die Dinge laufen auf der Blutmythosinsel etwas anders. Als wir hier zu Beginn ankamen, war das Land genauso wunderschön und unberührt wie auf der Azurmythosinsel. Wir nannten es sogar Silberbrise, doch nun breitet sich die Seuche über das Land aus. Was noch schlimmer ist, die Blutelfen, die wir auf der Exodar bekämpften, haben den Absturz überlebt. Somit kommen wir zu Eurem ersten Auftrag: Reist nach Nordwesten zum Messerwinkel und vernichtet alle Blutelfen, die Euch über den Weg laufen.", sourceObjective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr 10 Spione der Sonnenfalken tötet.", completion = "Ihr seid zurück - in einem Stück!\n\nIch habe gute Neuigkeiten, {name}. Wir haben neue Informationen zum wahrscheinlichen Aufenthaltsort weiterer Überlebender erhalten. Eine neue Absturzstelle wurde entdeckt! Sobald ich mich eingehender damit befasst habe, werde ich mich an Euch wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9695] = { id = 9695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anweisung des Sonnenkönigs", description = "Dieses Dokument sieht wichtig aus. Leider wurde es in Thalassisch verfasst; eine Sprache, derer Ihr nicht mächtig seid.\n\nVielleicht weiß Verteidiger Boros, wie man weiter vorgehen könnte.", sourceObjective = "Bringt die Anweisung des Sonnenkönigs zu Verteidiger Boros bei der Blutwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9696] = { id = 9696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzungen...", description = "Unsere hochrangigste Vernehmungsbeauftragte Elysia spricht fließend Thalassisch. Bringt ihr dieses Dokument, mal sehen, was sie dazu zu sagen hat.", sourceObjective = "Bringt das Schreiben der Sonnenfalken zur Vernehmungsbeauftragten Elysia bei der Blutwacht.", progress = "Ich habe hier etwas viel zu tun, Agent {name}. Ich hoffe Euer Anliegen ist wichtig.", completion = "<Elysia liest das Dokument.>\n\nWenn wirklich stimmt, was hier steht, dann haben die Blutelfen ein Portal zur Scherbenwelt geöffnet! Das würde auch ihre schier endlose Zahl erklären...", sourceObjectiveStatus = "unverified-source-field" }
quests[9697] = { id = 9697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüterin Leesa'oh", description = "Es müssen wichtige Forschungen bezüglich der Ökologie der hiesigen Lebewesen betrieben werden, besonders bei den Sporlingen und den Sumpflords der Marschen. Und vertraut mir, wenn Ihr Euch einmal mit diesem Thema befasst habt, werdet Ihr die Arbeit faszinierend finden.\n\nSucht Behüterin Leesa'oh im Wachposten des Cenarius im westlichen Teil der südlichen Marschen. Folgt dem Pfad nach Westen, dann werdet Ihr sie sicher finden. Sie ist manchmal etwas... übereifrig..., aber lasst Euch davon nicht abschrecken.\n\nOh, und hütet Euch vor ihrer Katze.", sourceObjective = "Sprecht mit Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen.", completion = "Oh, gut... endlich Unterstützung! Es gibt einfach so viel zu tun, und ich muss hierbleiben, um alles zu organisieren.\n\nIch hoffe Ihr seid bereit, Euch die Hände schmutzig zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9698] = { id = 9698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz beim Propheten", description = "Ihr müsst das übersetzte Dokument Velen persönlich überbringen, {name}. Ich vertraue diesem verstörten Boten nicht.\n\nErklärt dem Propheten, dass die Blutelfen Verstärkung aus der Scherbenwelt erhalten und dass sie einen Spion unter den Draenei bei der Exodar haben. Velen hält sich in der Halle des Lichts in der Exodar auf.\n\nBeeilt Euch!", sourceObjective = "Bringt das übersetzte Schreiben der Sonnenfalken zum Propheten Velen bei der Exodar.", progress = "<Velen lächelt.>\n\nSeid gegrüßt, {name}. Ich habe Euch erwartet.", completion = "<Velen beginnt das Dokument zu lesen.>\n\nInteressant... dies erklärt in der Tat einiges.", sourceObjectiveStatus = "unverified-source-field" }
quests[9699] = { id = 9699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist wahr?", description = "Ich danke Euch für die rasche Zustellung, {name}. Ihr erweist Euch schließlich als einer der besseren Agenten der Hand.\n\nWenn wir bloß wüssten, wem sie auf der Blutmythosinsel Bericht erstattet haben und noch wichtiger, wo dieses Sonnenportal ist... Sie scheinen es streng zu bewachen - wo immer es auch sein mag.\n\nWärt Ihr an einer Erkundungsmission interessiert?\n\nWenn ja, dann bringt diese Anordnungen zu Verteidiger Boros. Er wird Euch Euren nächsten Auftrag erteilen.", sourceObjective = "Bringt Velens Anordnungen zu Verteidiger Boros bei der Blutwacht.", progress = "Ja?", completion = "Es ist ein guter Plan, aber auch ein gefährlicher. Ich bin mir jedoch sicher, dass alles gut verlaufen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[9700] = { id = 9700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht ins Dunkel bringen", description = "Velen erklärt, dass falls die Blutelfen Verbindungen zwischen der Insel und der Scherbenwelt hergestellt haben, Überreste oder Anomalien rund um die geöffneten Portale zurückgelassen wurden. Ihr müsst die Insel nach Gebieten absuchen, in denen diese Anomalien vorkommen.\n\nSeid gewarnt, {name}, manche dieser Anomalien sind Kreaturen aus der Leere selbst. Solltet Ihr auf Anomalien der Leere treffen, tötet sie! Erstattet mir Bericht, sobald Ihr neue Informationen ausfindig gemacht habt. Beginnt mit Eurer Suche im Norden, nahe der Warpgondel.", sourceObjective = "Verteidiger Boros bei der Blutwacht möchte, dass Ihr die Lage des Sonnenportals ausfindig macht und 5 Anomalien der Leere tötet.", completion = "Wie viele sagtet Ihr doch gleich, habt Ihr bei der Warpgondel gesichtet? Wie oft haben sie nur dieses Sonnenportal geöffnet? Das sind sehr schlechte Neuigkeiten...\n\nTja, Ihr habt Euch nun alles von mir angeeignet, was ich Euch lehren kann, {name}. Kuros wird nach Euch rufen lassen, wenn es an der Zeit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9701] = { id = 9701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporlinge beobachten", description = "Wir müssen alles über die Sporlinge von Sporeggar und ihre Beziehung zu den anderen Lebewesen in der Umgebung in Erfahrung bringen. Eine Möglichkeit dazu ist die, die ich anwende: passives Beobachten und ihr Verhalten notieren.\n\nIch möchte, dass Ihr für mich nach Westen in das Pilzgeflecht geht. Untersucht die gesamte Gegend dort und berichtet mir dann davon.", sourceObjective = "Untersucht das Pilzgeflecht in den Zangarmarschen und berichtet danach Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen von Euren Beobachtungen.", completion = "Was?! Die Sumpflords des Quaggkamms ESSEN die Sporenkapseln der Sporlinge? Das ist nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[9702] = { id = 9702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Fressgier", description = "Ich habe mich schon gefragt, warum die Sumpflords die Straße überqueren, um in das Pilzgeflecht zu gelangen – sie müssen aus irgendeinem Grund am Verhungern sein. Das darf nicht sein!\n\nIch meine, normalerweise würde ich mich nicht einmischen, aber wenn sie weiterhin alle Kapseln essen, werden sie die Sporlinge ausrotten!\n\nHier ist mein Plan: Ich bleibe hier und Ihr geht zum Quaggkamm im Osten und seht Euch nach nahrungstechnischen Gründen um, warum sie die Sporlinge überfallen.", sourceObjective = "Sammelt 10 Stück liegengelassene Nahrung und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", progress = "Stellt sicher, dass Ihr alle Beweise sorgfältig zusammentragt, {class}! Wir fügen hier die Teile eines riesigen Puzzles zusammen. Ein Fehler von Euch könnte zu falschen Schlussfolgerungen führen.\n\nWo stünden wir dann mit unserem Verständnis für die Zangarmarschen?", completion = "Das habt Ihr gefunden? Das ist komisch. Diese vertrockneten Pilzüberreste sind ungewöhnlich und kommen mir irgendwie bekannt vor.\n\nIch muss kurz darüber nachdenken. Geht nicht weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[9703] = { id = 9703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kryokern", description = "Wir haben noch andere, die nach Spuren suchen, die zu den Sonnenportalen führen, {name}. Ihr müsst Euch jetzt auf Euren bevorstehenden Einsatz konzentrieren.\n\nBoros erhielt Berichte über eine neue Absturzstelle. Wir haben herausgefunden, dass es sich bei dieser Absturzstelle eigentlich um den Kryokern der Exodar handelt. Eine Transportkammer, in der genau solche Kapseln untergebracht sind wie die, aus denen wir Draenei im Am'mental gekrochen sind.\n\nIn diesem Bereich werden auch Heilvorräte aufbewahrt. Geht zum Kryokern genau westlich der Blutwacht. Sucht nach Vorräten und nach Überlebenden.", sourceObjective = "Verteidiger Kuros bei der Blutwacht möchte, dass Ihr 12 Kisten mit Heilvorräten sichert.", progress = "Waren die Informationen korrekt?", completion = "Nur Blutelfen? Keine Überlebenden? Das ist beunruhigend. Ich brauche etwas Zeit zum Nachdenken, {name}. Vielleicht haben Aesom oder Boros einen Auftrag für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9704] = { id = 9704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Getriebenen getötet", description = "Es ist ein hartes Stück Arbeit, ein Kundschafter zwischen der Insel der Sonnenwanderer und dem Falkenplatz zu sein. Knappe Zeitvorgaben, lange Arbeitszeiten und noch schlimmer... die Getriebenen!\n\nDie Straße im Süden führt durch die Ruinen von Silbermond... ein Ort, an dem es nur so von Getriebenen wimmelt, die darauf warten, Euch für ein paar Manakristalle töten zu können. Ich glaube, dieses Schicksal hat unsere letzte Kundschafterin ereilt. Wir hatten sie mit einem von Eronas Päckchen entsandt.\n\nWie ich sehe, brennt Ihr bereits darauf, Euch beweisen zu können. Reist zum Dämmerweg und sucht nach Spuren unserer Kundschafterin.", sourceObjective = "Geht nach Süden zu den Ruinen von Silbermond und haltet nach der getöteten Kundschafterin beim Dämmerweg Ausschau.", completion = "Die Habseligkeiten der Kundschafterin wurden mit Ausnahme eines Pakets allesamt entwendet. Es scheint der Beschreibung zu entsprechen, die Euch Alarion von Eronas Päckchen gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9705] = { id = 9705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergung des Päckchens", description = "Ihr nehmt das Päckchen und stellt noch einmal sicher, dass es wirklich von Magistrix Erona stammt. Alarion würde es sicherlich gerne entgegennehmen.", sourceObjective = "Kehrt mit Eronas Päckchen zu Kundschafterin Alarion zurück.", progress = "Was habt Ihr gefunden, {name}?", completion = "Beim Sonnenbrunnen! Es ist der dritte Kundschafter, den wir diesen Monat verloren haben.\n\nIch weiß Euren Mut zu schätzen, den Ihr bei Eurer Reise zum Dämmerweg bewiesen habt. Die Wachen müssen diese verdammten Getriebenen besser im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9706] = { id = 9706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaens Tagebuch - Das Schicksal von Verteidiger Saruan", description = "Eure Hände zittern beim Aufheben des Buchs. Kuros muss von dieser Tragödie erfahren. Bringt ihm das Tagebuch.", sourceObjective = "Bringt Galaens Tagebuch zu Verteidiger Kuros bei der Blutwacht.", progress = "Was habt Ihr da, {name}? Ist das ein Tagebuch?", completion = "<Kuros erbleicht beim Lesen des Tagebuchs und Tränen strömen seine Wangen herab.>\n\nSaruan war mein Meister... mein Lehrer... mein Mentor... Ich nahm seinen Platz im Triumvirat erst vor Kurzem ein – nachdem wir die Suche nach ihm aufgegeben hatten.\n\n<Kuros' Gesichtsausdruck schlägt in Zorn über.>\n\nMatis...", sourceObjectiveStatus = "unverified-source-field" }
quests[9707] = { id = 9707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden der Waffe", description = "Wieder habt Ihr Euch als würdig erwiesen, ein Mitglied des Ordens zu sein. Mit großer Freude verleihe ich Euch den Rang des Adepten, {name}. Prinz Kael'thas selbst wäre stolz auf Euch.\n\nEs ist eine Ehre für uns alle, an Eurer Seite auf dem Schlachtfeld zu kämpfen. Verhaltet Euch weiterhin vorbildlich, zeigt keine Gnade oder Schwäche, verteidigt unermüdlich Euer Volk und Eure Brüder und verfeinert Eure Beherrschung des Lichts.\n\nNun holt Euch die Waffe, die Eurem neuen Rang angemessen ist.", sourceObjective = "Bringt die Kiste mit Rohmaterialien zu Bemarrin in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9708] = { id = 9708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekannter Pilz", description = "Ja, das ist es! Ich wusste doch, dass ich diesen Pilzstamm schon woanders in den Marschen gesehen habe!\n\nIm Norden gibt es einen Ort, der Prügelsumpf genannt wird. Komischer Name für einen Sumpf, wenn Ihr mich fragt, aber ich bin noch nie dort gewesen. Ich brauche Proben von diesen Pilzen um meine Theorie zu unterstützen.\n\nAber seid vorsichtig, {class}. Ich habe gehört, dass die Oger in dieser Gegend einmarschiert sind. Ihr müsst also die Proben von ihnen besorgen. Könnte das der Grund sein, warum die Sumpflords dort nicht mehr ihre Nahrung suchen?", sourceObjective = "Sammelt 15 Pilzproben und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", progress = "Habt Ihr die Proben schon?", completion = "Die Proben stimmen definitiv überein. Und die Anwesenheit der Oger und was sie dort tun erklärt alles. Jetzt verstehe ich, warum der Ort Prügelsumpf genannt wird.\n\nWir müssen etwas an dieser Situation ändern, aber was? Wir können nicht einfach alle Oger auslöschen, sie haben genauso viel Recht hier zu leben, wie alle anderen Lebewesen in den Marschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9709] = { id = 9709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pilze zurückstehlen", description = "{class}, ich habe eine Idee. Ich möchte, dass Ihr Euch wieder nach Norden aufmacht, aber dieses Mal in das Herz des Ogergebiets!\n\nNordwestlich des Prügelsumpfs gibt es einen Ort, der Festung der Ango'rosh genannt wird. Er befindet sich auf einer Insel jenseits einer großen Pilzbrücke. Dort lagern sie bestimmt die geernteten Pilze. Ihr könnt sie sicher überall finden, wahrscheinlich haben die Oger selbst sie sogar in den Taschen!\n\nBringt mir genügend davon, und ich werde versuchen, die Sumpflords mit einer neuen Nahrungsquelle zu versorgen.", sourceObjective = "Sammelt 10 Kisten Pilze und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück.", progress = "Habt Ihr schon alle Pilze, um einen neuen Garten für die Sumpflords anzulegen?", completion = "Sie sind perfekt! Oh danke, {class}!\n\nIhr wart so darauf bedacht, das natürliche Gefüge nicht aus dem Gleichgewicht zu bringen, und wir haben in so kurzer Zeit so viele Informationen sammeln können!\n\nJetzt wollen wir mal schauen, ob unser kleiner Plan, eine neue Nahrungsquelle für die Sumpflords zu schaffen, funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[9710] = { id = 9710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der blutgehärtete Ranseur", description = "Es ist alles vorbereitet, {name}. Bald werdet Ihr eine Waffe haben, die Eurem neuen Status angemessen ist.", sourceObjective = "Wartet, während Bemarrin Eure Waffe schmiedet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9711] = { id = 9711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matis der Grausame", description = "Matis wird Gerechtigkeit widerfahren, {name}. Ich möchte, dass Ihr derjenige seid, der ihn findet und ihn zum Triumvirat zurückbringt.\n\nDurchkämmt die Insel nach diesem Mörder. Solltet Ihr ihn finden, verwendet diese Leuchtpistole. Sobald mein Suchtrupp das Signal sieht, wird man herbeieilen und Euch bei der Gefangennahme von Matis helfen. Kommt anschließend zu mir zurück.", sourceObjective = "Verteidiger Kuros bei der Blutwacht möchte, dass Ihr Matis den Grausamen gefangen nehmt.", completion = "Das Triumvirat hat beschlossen, Matis sofort zu verurteilen. Ihr habt heute einen Erzverbrecher der Gerechtigkeit überführt, junger {race}.\n\nIhr habt für zwei von dreien außerordentliche Arbeit geleistet, lediglich Aesom fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9712] = { id = 9712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das thalassische Schlachtross", description = "Ihr habt Euch im Dienste des Ordens ausgezeichnet, {name}. Die Euch durch Magister Astalor und seiner Brüder gewährten Fähigkeiten, die Energien des Lichts zu beherrschen und Eurem Willen nach einzusetzen, und Euer offensichtliches Talent darin, machen Euch alle Ehre. Ihr wurdet für würdig befunden, Euer Wissen noch zu erweitern.\n\nMit dem Licht unter Eurer Kontrolle seid Ihr in der Lage, ein furchterregendes Schlachtross herbeizurufen; ein treues Reittier an Eurer Seite.\n\nDient auch weiterhin so voller Eifer und Ehre, {name}, und Ihr werdet belohnt werden.Ihr erlernt:", sourceObjective = "Sprecht mit Ritterfürst Heldenblut, um zu erfahren, wie Ihr Euer thalassisches Schlachtross beschwören könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9713] = { id = 9713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glowcap Harvesting Enabling Flag" }
quests[9714] = { id = 9714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein weiteres Gebüsch!" }
quests[9715] = { id = 9715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein Gebüsch!", description = "Wir müssen unsere Vorräte an Bluthibiskus aufstocken, die wir für viele Zwecke brauchen. Früher gab es hier dicke Büsche davon, aber seitdem der Wasserspiegel der Marschen gesunken ist, findet man ihn nur noch im Tiefensumpf und im Echsenkessel, unter dem Schlangensee.\n\nMan sagt, er sei eine Delikatesse für die Schlurfer, Sumpfriesen und die Tiefenfledermaus. Wenn Ihr uns also helfen wollt, müsst Ihr die Blumen von ihnen besorgen.", sourceObjective = "Sammelt 5 Stück Bluthibiskus und bringt sie zu Gzhun'tt in Sporeggar in den Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9716] = { id = 9716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anomalie am Umbrafennsee", description = "Wir kamen in die Scherbenwelt mit der Erwartung, hier kleine Ansammlungen von Leben zu finden. Doch was wir hier in den Zangarmarschen entdeckt haben, ist eine üppige Landschaft mit einem gedeihenden Ökosystem.\n\nUnsere ursprüngliche Einschätzung der Gegend war dennoch trügerisch. Die Wasserstände der Seen und Marschen sind seit unseren ersten Messungen stetig gesunken.\n\nDies könnte verheerende Auswirkungen auf die Flora und Fauna der Gegend haben. Geht zum Umbrafennsee südwestlich von hier und seht Euch nach möglichen Gründen für das Sinken des Wasserspiegels um.", sourceObjective = "Untersucht den Grund für die sinkenden Wasserspiegel am Umbrafennsee. Kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", completion = "Die Naga stecken dahinter! Aber warum? Euren Schilderungen zufolge sind die Dampfpumpen für das Sinken der Wasserspiegel in den Marschen verantwortlich.\n\nEgal - dies erklärt Ihre offensichtliche Feindlichkeit uns gegenüber. Lasst uns keine Zeit verschwenden, Ihr müsst eine weitere Aufgabe für uns erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9717] = { id = 9717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Los geht´s!", description = "Auch wenn wir ein friedliebendes Volk sind, befinden wir uns im Krieg mit den Fungusgiganten, ob uns das gefällt oder nicht. Und es gibt ein Sprichwort bei den Sporlingen, das besagt, dass im Krieg und im Pilz alles erlaubt ist!\n\nEiner der Anführer der Fungusgiganten, Hungarfenn, pflegt seit Jahrtausenden mit Hingabe eine sehr besondere Pflanze, bekannt als die Tiefenspore. Er würde daran zerbrechen, wenn dieser Pflanze etwas zustoßen würde.\n\nReist zum Tiefensumpf im Echsenkessel und stehlt einen Dorn von ihr. Vertraut mir, er wird es bemerken.", sourceObjective = "Besorgt einen Tiefensporendorn und bringt ihn zu T'shu in Sporeggar in den Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9718] = { id = 9718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flug der Krähe", description = "Wir müssen genau herausfinden, wie weit reichend die Aktivität der Naga wirklich ist und entsprechend reagieren.\n\nJedes Wasservorkommen in den Zangarmarschen zu untersuchen wäre ein sehr zeitaufwändiges Unterfangen. Wenn Ihr mir gestattet, werde ich meine Magie benutzen, um Euch in eine Gestalt zu verwandeln, die Euch das Erkunden der Marschen leichter machen wird.\n\nHaltet dieses Amulett über den Balkon in meiner Nähe, wenn Ihr bereit seid. Ich werde Euch zurück in die Sicherheit führen, wenn wir fertig sind.", sourceObjective = "Ysiel Windsänger möchte, dass Ihr das Sturmkrähenamulett benutzt, um die größeren Seen in den Zangarmarschen zu erkunden.", progress = "Seid gegrüßt, {name}.", completion = "Es ist so, wie ich dachte. Die Naga haben Pumpstationen an allen größeren Seen in den Zangarmarschen errichtet.\n\nWenn die Marschen weiter existieren sollen, müssen sie aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9719] = { id = 9719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Mutter", description = "Geschichtlich gesehen waren die Marschenläufer die größte Gefahr für mein Volk. Jetzt, da wir mit den Problemen mit den Fungusgiganten zu kämpfen haben, können wir uns keinen weiteren Angriff unserer alten Feinde erlauben.\n\nIhr habt Euch als fähig erwiesen, {class}. Meint Ihr, Ihr könntet zum Tiefensumpf im Echsenkessel reisen und die große Mutter der Marschenläufer, die als Schattenmutter bekannt ist, auslöschen?!\n\nBringt mir ihr Gehirn als Beweis.", sourceObjective = "Bringt das Gehirn der Schattenmutter zu Khn'nix in Sporeggar in den Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9720] = { id = 9720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht muss erhalten bleiben", description = "Ich kann nicht verstehen, warum die Naga ihren eigenen Lebensraum entwässern wollen. Ich weiß aber sicher, dass wir sie aufhalten müssen.\n\nDiese Samen tragen die Wut der Erde in sich. Bringt sie zu den Dampfpumpen, die von den Naga betrieben werden, und benutzt sie bei den Steuerungen.\n\nDie Ranken, die aus den Samen wachsen, werden so dick wie Euer Arm und so stark wie Eisen sein, {name}. Stellt das Gleichgewicht wieder her, das die Naga zerstört haben.", sourceObjective = "Ysiel Windsänger möchte, dass Ihr die Eisenrankensamenkörner benutzt, um die Dampfpumpensteuerungen am Schlangensee, Umbrafennsee, Sumpflichtsee und der Lagune zu zerstören. Kehrt danach mit den übrigen Samen zu ihr in die Zuflucht des Cenarius in den Zangarmarschen zurück.", completion = "Es ist also vollbracht. Die Marschen sind vorerst gerettet.\n\nGlaubt aber nicht, dass wir zum letzten Mal von den Naga gehört haben. Wir müssen unseren Feind im Auge behalten, während wir unsere Mission in der Scherbenwelt fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9721] = { id = 9721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufforderung von Lord Solanar", description = "Eure Aufopferung für den Orden und Euer rascher Aufstieg innerhalb seiner Ränge sind nicht unbeachtet geblieben. Tatsächlich erbittet Lord Solanar Blutzorn, Lady Liadrins rechte Hand und verdienter Held, Eure Gegenwart.\n\nDas ist eine seltene Ehre, {name}. Normalerweise überlässt Lord Solanar mir die Verwaltung des Ordens und das damit verbundene Tagesgeschäft, doch scheint er ein besonderes Interesse an Euch zu haben. Wartet nicht zu lange, {name}.", sourceObjective = "Sprecht mit Lord Solanar Blutzorn in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9722] = { id = 9722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Meisters", description = "Innerhalb meines Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem thalassischen Schlachtross zu erkennen.\n\nJeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen.\n\nIch habe beschlossen, Euch als Fürsprecher zur Seite zu stehen, sollte es Euer Wunsch sein, in die Reihen der Meister der Blutritter aufgenommen zu werden.", sourceObjective = "Sprecht nochmals mit Lord Solanar, um seine angebotene Unterstützung für Eure Aufnahme zu akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9723] = { id = 9723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geste der Hingabe", description = "Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge, {name}. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen.\n\nDiese erste Aufgabe fordert weder Eure Kampfeskunst, noch ist sie besonders ruhmreich, doch ohne solche Tätigkeiten würde der Orden auseinander fallen. Ich werde Euch eine Liste mit Gegenständen geben, die Magister Astalor Blutschwurs Männer benötigen, um uns mit Lichtenergie für unsere Magie zu versorgen.", sourceObjective = "Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lord Solanar in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9724] = { id = 9724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung an den Zirkel des Cenarius", description = "Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.\n\nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.", sourceObjective = "Sprecht mit Amythiel Nebelgänger beim Posten des Cenarius auf der Höllenfeuerhalbinsel.", completion = "Das sind schlimme Nachrichten, die Ihr mir über die Naga in den Zangarmarschen bringt. Es war sehr klug von Ysiel, uns darüber zu informieren. Sie hat nicht vergessen, dass die Expedition nicht ohne die Unterstützung des Zirkels existieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9725] = { id = 9725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Demonstration Eurer Loyalität", description = "Wir Blutritter haben geschworen, Quel'Thalas zu verteidigen, {name}. Dies ist ein zentraler Teil unserer Ausbildung. Unsere Feinde sind wild und unbeugsam. Einzig unsere Anstrengungen und die Unterstützung unserer Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von Silbermond.\n\nIch habe einige beunruhigende Berichte über die verstärkte Präsenz der Geißel, südöstlich unserer Grenze zu den Östlichen Pestländern, erhalten. Eine Kompanie Belagerungsingenieure der Geißel, mitsamt Belagerungsgerät, scheinen sich dort für einen Angriff auf die Geisterlande zu sammeln. Auf keinen Fall dürfen sie Erfolg haben.", sourceObjective = "Lord Solanar in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9726] = { id = 9726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt, da wir Freunde sind...", description = "Die Naga in der Enklave der Blutschuppen im Nordosten haben angefangen, unsere Leute umzubringen. Das können wir nicht tolerieren, {class}!\n\nWir schlagen vor, dass Ihr ihnen als Beweis für unsere Freundschaft eine Lektion erteilt.", sourceObjective = "Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun'tt in Sporeggar in den Zangarmarschen zurück.", completion = "<Gzun'tt nickt Euch zu.>\n\nWir sind sehr erfreut, dass Ihr unsere Freundschaft bestätigt habt, {name}. Vielleicht denken die heidnischen Naga in Zukunft zweimal darüber nach, bevor sie uns belästigen, wenn wir so einen starken Verbündeten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9727] = { id = 9727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt, da wir immer noch Freunde sind...", description = "Berichten zufolge töten die Naga bei der Enklave der Blutschuppen im Nordosten immer noch unsere Leute. Ich dachte, Ihr hättet Euch darum gekümmert, {class}!\n\nIch schlage vor, dass Ihr ihnen als Beweis für unsere andauernde Freundschaft eine Lektion erteilt.", sourceObjective = "Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun'tt in Sporeggar in den Zangarmarschen zurück.", completion = "<Gzun'tt nickt Euch zu.>\n\nWir sind sehr erfreut, dass Ihr unsere Freundschaft erneut bestätigt habt, {name}. Sicherlich werden die sinnlosen Angriffe auf unser Volk jetzt, da Ihr unseren Standpunkt mehrfach klar gemacht habt, aufhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[9728] = { id = 9728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein herzliches Willkommen", description = "Während die Druiden der Expedition damit beschäftigt waren die Pflanzen und Seen hier zu untersuchen, habe ich es zu meiner Aufgabe gemacht, mich mit den Feinden in dieser Umgebung auseinanderzusetzen.\n\nVom ersten Moment an, als wir die Zangarmarschen betreten haben, haben die Naga uns ohne Vorwarnung angegriffen. Wir haben unser Bestes getan, um sie fern zu halten, aber unsere Mittel sind begrenzt.\n\nIch möchte, dass Ihr zu den verschiedenen Lagern der Naga in den Zangarmarschen geht und ihnen zeigt, dass man sich besser nicht mit uns anlegt. Bringt mir ihre Klauen als Beweis Eurer Siege.", sourceObjective = "Bringt 30 Nagaklauen zu Aufseher Hamuht in der Zuflucht des Cenarius.", progress = "Schön, Euch wiederzusehen, {name}. Wie läuft die Jagd nach den Naga?", completion = "Gut gemacht, {name}. Beruhigt Eurer schlechtes Gewissen, falls Ihr eines haben solltet. Diese Naga sind böse Kreaturen - noch viel böser als die in Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[9729] = { id = 9729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fhwoor zerschmettern!", description = "Kleine Naga machen Fhwoor wütend! Sporlinge gute Freunde von Fhwoor, darum Fhwoor holt Lade von Naga.\n\nWir gehen in nahes Nagadorf. Du helfen?", sourceObjective = "Begleitet Fwoohr in das Gebiet bei der Dampfpumpe am Sumpflichtsee, um die Lade von Ssslith zu holen. Bringt Fhwoor und die Lade sicher zurück und meldet Euch bei Gzhun'tt in Sporeggar in den Zangarmarschen.", completion = "Fhwoor ist ein guter Riese. Wir haben ihn vor einer Weile vor den Naga gerettet und seitdem ist er hier und hilft uns.\n\nWir können nur hoffen, dass die Naga den Hinweis verstehen. Wenn wir in der Lage sind, uns in ihr Dorf einzuschleichen und ihren wertvollsten Besitz zu rauben, können wir noch viel Schlimmeres tun. Vielleicht gehen sie jetzt zurück in ihren Kessel und lassen uns in Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9730] = { id = 9730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Dunkelkämme", description = "Hiermit wird von der Expedition des Cenarius ein Kopfgeld auf Rajah Haghazed, Anführer der Dunkelkämme, ausgesetzt. Haghazed wurde zuletzt von den Spähern des Cenarius südlich der Lagune gesichtet, mitten im Süden der Zangarmarschen.\n\nDie Dunkelkämme werden mit einer Reihe von Angriffen auf die Expedition des Cenarius in Verbindung gebracht, und ihr Anführer gilt als sehr gefährlich.\n\nDas Kopfgeld kann bei Aufseher Hamuht eingefordert werden.", sourceObjective = "Tötet Rajah Haghazed bei der Lagune und kehrt danach zu Aufseher Hamuht bei der Expedition des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten.", completion = "Ich mochte schon die Naga in Azeroth nicht, aber die hier mag ich noch viel weniger. Es ist eine Schande, dass unsere Mission nicht friedvoll verlaufen konnte, aber Ihr werdet mich niemals auch nur eine Träne für einen Naga vergießen sehen.\n\nHier ist Eure Belohnung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9731] = { id = 9731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanalisationspläne", description = "Die Pläne, die Ihr bekommen habt, zeigen ein unterirdisches System von Rohren und Pumpen, die die Seen in der Umgebung mit dem Schlangensee verbinden.\n\nWenn die Pläne korrekt sind, muss es einen riesigen Ablauf am Grund des Schlangensees geben. Bestätigt dies und bringt die Neuigkeiten zur Zuflucht des Cenarius.", sourceObjective = "Durchsucht den Grund des Schlangensees nach einem Ablauf. Kehrt mit Neuigkeiten über Eure Entdeckung zu Ysiel Windsänger in der Zuflucht des Cenarius zurück.", progress = "Welche Neuigkeiten bringt Ihr, {name}?", completion = "Die Naga haben den Schlangensee in einen riesigen Wasserablauf für den Rest der Zangarmarschen verwandelt. Was haben sie wohl vor?\n\nEs war eine kluge Entscheidung, uns diese Neuigkeiten mitzuteilen, {name}. Wir werden eine Gruppe losschicken, um den Ablauf, den Ihr gefunden habt, zu untersuchen. Bis dahin habe ich eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9732] = { id = 9732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Marschen", description = "Kehrt zu Ysiel zurück und gebt ihr Bescheid, dass sie so bald wie möglich weitere Hilfe erhalten wird.\n\nUnsere Mitglieder waren bis jetzt mit Angelegenheiten in der Mondlichtung und in Silithus beschäftigt, aber wir werden unser bestes tun, um die notwendigen Mittel zur Zuflucht des Cenarius zu schicken.", sourceObjective = "Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", completion = "Euer Anblick ist mir sehr willkommen, {name}. Die Lage in der Zuflucht des Cenarius hat sich verschlechtert, seit Ihr fortgegangen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9733] = { id = 9733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung an den Zirkel des Cenarius", description = "Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.\n\nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.", sourceObjective = "Sprecht mit Mahuram Starkhuf in Thrallmar auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9734] = { id = 9734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Marschen", description = "Kehrt zu Ysiel zurück und gebt ihr Bescheid, dass sie so bald wie möglich weitere Hilfe erhalten wird.\n\nUnsere Mitglieder waren bis jetzt mit Angelegenheiten in der Mondlichtung und in Silithus beschäftigt, aber wir werden unser bestes tun, um die notwendigen Mittel zur Zuflucht des Cenarius zu schicken.", sourceObjective = "Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9735] = { id = 9735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Meister des Lichts", description = "Ein Meister der Blutritter besitzt unglaubliche Fähigkeiten das Licht auf eine Art zu nutzen und zu formen, wie es die sogenannten anderen 'Paladine' nie verstehen werden. Das hält sie jedoch nicht davon ab, uns dafür zu ächten, wie wir das wahre Potenzial des Lichts entfesseln.\n\nWir müssen ihnen klar machen, dass man mit unseresgleichen keine Spielchen spielt. Was ich mir vorgestellt habe, ist keine schnelle Angelegenheit und auch nicht einfach, doch wenn Ihr Euch dieser Aufgabe verpflichtet, wird es Euer erstes Ziel sein, den Bibliotheksflügel der Abtei von Tyrs Hand zu infiltrieren und eine Phiole heiligen Wassers von Tyrs Hand an Euch zu bringen.", sourceObjective = "Bringt Lord Solanar in Silbermond eine Phiole heiligen Wassers von Tyrs Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[9736] = { id = 9736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Meister des Lichts", description = "Jetzt, da wir das Wasser haben, benötigen wir eine Reihe von Zutaten in genau abgestimmten Mengen. Einige dieser Substanzen sind äußerst selten und wertvoll, {name}, doch ich habe Quellen für zwei von ihnen ausfindig gemacht.\n\nIhr solltet einige arkane Katalysatoren bei Zalle, dem Reagenzienverkäufer in einem der Geschäfte auf dem Platz nahe der Todesschneise, bekommen. Darlia, die Giftlieferantin nahe den Schurkenausbildern in der Mördergasse, sollte über einen Vorrat an krepuskularem Pulver verfügen.\n\nUm meine Mixtur zu vervollständigen, benötige ich außerdem noch einen azerothischen Diamanten und einen makellosen schwarzen Diamanten.", sourceObjective = "Bringt Lord Solanar in Silbermond 1 arkanen Katalysator, 1 Einheit krepuskulares Pulver, 1 azerothischen Diamanten und 1 makellosen schwarzen Diamanten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9737] = { id = 9737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Meister des Lichts", description = "Der einzig wahre Weg, das Licht zu nutzen, ist der unsrige, {name}. Um denen, die sich schändlicherweise 'Paladine' nennen, die Torheit ihrer Tradition zu verdeutlichen, habe ich vor, ihnen eine unmissverständliche Nachricht zukommen zu lassen.\n\nDie Alonsuskapelle, der Ort, an dem der Orden der Silbernen Hand seinen Anfang nahm, scheint gegen die Zerstörung in Stratholme immun zu sein. Die ewige Flamme der Kapelle gewährt ihr den Schutz des Lichts, doch wenn Ihr sie mit der Löschmischung erstickt, ist es aus mit dem Schutz. Die Kapelle wird brennen und die Welt wird unsere Vorherrschaft über das Licht anerkennen müssen.Ihr erlernt:", sourceObjective = "Verwendet die Löschmischung in der Nähe der ewigen Flamme in der Alonsuskapelle, um den Schutz des Lichts zu brechen. Seid bereit, jeden zu töten, der versucht, die Kapelle zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9738] = { id = 9738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei der Arbeit verschollen", description = "Ihr müsst mir helfen! Wir wurden von Ysiel hierher geschickt, um das Geheimnis der Dampfpumpen zu erkunden und herauszufinden, warum mit ihrer Hilfe das Wasser aus den Marschen gepumpt wird. Aber meine Freunde haben sich von mir getrennt und sind einfach ohne mich weitergegangen.\n\nDie vier können manchmal solche Dummköpfe sein! Aber ich mag sie trotzdem.\n\nDeshalb müsst Ihr mir helfen herauszufinden, was aus ihnen geworden ist, denn ich befürchte das Schlimmste. Sucht sie in den Sklavenunterkünften und im Tiefensumpf.\n\nVielen Dank, {class}.", sourceObjective = "Findet heraus, was mit Erdbinder Rayge, Naturalist Biss, Jäter Gründaum und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang im Echsenkessel in den Zangarmarschen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9739] = { id = 9739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Misere der Sporlinge", description = "Ihr da! Ihr müsst uns helfen!\n\nDie Sumpflords fressen all unsere Sporenbeutel! Ihr müsst etwas tun, sonst verlieren wir unsere Jungen!\n\nDie Sporenbeutel sind zu Anfang ganz groß und werden dann kleiner, wenn die Luft darin verbraucht ist. Haltet nach den kleinen, reifen Sporenbeuteln Ausschau und rettet so viele Ihr nur könnt!", sourceObjective = "Fahssn im Pilzgeflecht möchte, dass Ihr 10 reife Sporenbeutel sammelt.", progress = "Die Sporenbeutel! Habt Ihr sie?", completion = "Ihr habt es geschafft! Ihr habt den Dank meines Volkes.\n\nIch hoffe Ihr versteht... daraus entstehen unsere Jungen. Wir können diese Biester sie nicht einfach fressen lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9740] = { id = 9740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sonnentor", description = "Dank Euch und Eurer Bemühungen konnten meine Späher das Sonnentor ausfindig machen. Die Elfen sorgen dafür, dass der Standort des Portals stets mobil bleibt und jederzeit verändert werden kann. Deshalb war die Stelle, die Ihr untersucht habt, auch verlassen.\n\nDie Stärke eines solchen Systems ist ebenfalls seine größte Schwäche. Das Sonnentor wird von Portalaufsehern aufrechterhalten. Wenn es uns gelingt, die Aufseher auszuschalten, werden wir das Portal zerstören können. Der momentane Standort des Sonnentors liegt westlich von hier, südlich der Vektorspule. Findet und zerstört es!", sourceObjective = "Verteidiger Aesom bei der Blutwacht möchte, dass Ihr das Sonnentor zerstört.", completion = "Fabelhaft! Wir haben ihre Versorgungszufuhr durchtrennt. Jetzt müssen wir sie nur noch kaltmachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9741] = { id = 9741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschöpfe aus der Leere", description = "Aesom hat meine Truppe vor ein paar Tagen auf eine Erkundungsmission geschickt, um nach dem Sonnentor zu suchen. Natürlich haben wir es gefunden...\n\n<Loryi zeigt auf Jorli.>\n\nWas auch immer die Elfen durch dieses Portal transportieren, es sorgt dafür, dass Energien der Leere freigesetzt werden. Die Gegend füllt sich mit Geschöpfen der Leere. \n\nWir müssen sie vernichten, bevor sie sich in Anomalien der Leere verwandeln. Ihr findet die Geschöpfe südwestlich von hier, nahe des Sonnentors. Tötet sie und erstattet Aesom Bericht, sobald Eure Arbeit getan ist.", sourceObjective = "Tötet 12 Geschöpfe der Leere und erstattet Verteidiger Aesom bei der Blutwacht Bericht.", completion = "Dort herrscht ein ganz schönes Durcheinander, was? Gute Arbeit, {name}. Ich werde ein paar Anachoreten entsenden, die Loryi und Jorli helfen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9742] = { id = 9742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein paar Sporensäcke", progress = "Habt Ihr noch mehr Sporensäcke gerettet, {race}?", completion = "Ja! Ihr habt noch mehr Sporensäcke gerettet.\n\nIhr seid anders als die anderen von außerhalb. Ich werde meinem Volk von Euren Taten erzählen!\n\n<Diese Quest kann wiederholt werden, bis Ihr einen freundlichen Ruf erlangt habt.>" }
quests[9743] = { id = 9743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Feinde", description = "Wir Sporlinge kamen noch nie gut mit den Sumpflords aus. In der Vergangenheit haben wir sie mit Speeren und Steinen erfolgreich fernhalten können. Aber in der letzten Zeit scheinen sie aggressiver geworden zu sein... oder verzweifelter. Sie haben keine Angst vor uns oder unseren Waffen.\n\nIhr seid viel Furcht einflößender und besser bewaffnet als wir. Wenn Ihr die Sumpflords für uns bekämpfen könntet, stünden wir für immer in Eurer Schuld! Bringt mir ihre Ranken, damit ich weiß, wie viele Ihr getötet habt.", sourceObjective = "Bringt 6 Sumpflordranken zu Fahssn im Pilzgeflecht in den Zangarmarschen.", progress = "Wie geht es mit dem Töten der Sumpflords voran? Zeigt diesen Wüstlingen, dass sie besser nicht in Sporlingsgebiet kommen sollen!", completion = "Ihr seid heil zurück! Ich werde den anderen Sporlingen von Euch erzählen! {name}, der Riesentöter!", sourceObjectiveStatus = "unverified-source-field" }
quests[9744] = { id = 9744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Ranken!", progress = "Ihr habt viele Riesen getötet, aber es sind immer noch viele übrig. Und sie greifen immer noch unsere Sporenbeutel an!", completion = "Unglaublich! Es würde hunderte von Sporlingen brauchen, um so viele Riesen zu töten wie Ihr. Ich werde ganz bestimmt allen von Euren Heldentaten erzählen!\n\n<Diese Quest kann wiederholt werden, bis Ihr einen freundlichen Ruf erlangt habt.>" }
quests[9746] = { id = 9746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenze der Erschöpfung", description = "Der Sieg ist zum Greifen nah, {name}. Jetzt, da wir das Sonnentor entdeckt haben, wird es nicht lange dauern, bis ihre Versorgungszufuhr total unterbrochen ist. Es ist an der Zeit ihre Zahl auszudünnen.\n\nIm Westen könnt Ihr zahlreiche Lager der Sonnenfalken finden. Die Pyromanten und Verteidiger der Sonnenfalken belagern den größten Teil der Gegend. Findet sie, tötet sie und kehrt zu mir zurück.", sourceObjective = "Verteidiger Aesom bei der Blutwacht möchte, dass Ihr 10 Pyromanten der Sonnenfalken und 10 Verteidiger der Sonnenfalken tötet.", completion = "Dies wird ihre Verteidigung ganz sicher geschwächt haben. Ab sofort werden sie es sich zweimal überlegen, bevor sie uns kopflos überfallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9747] = { id = 9747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Umbrafennstamm", description = "Die Naga sind furchtbar, ja. Aber noch schlimmer sind die verräterischen Stämme der Zerschlagenen und der Verirrten, die ihnen geholfen haben!\n\nDie schlimmsten von allen sind die Verirrten des Umbrafennstamms. Sie benutzen dunkle Magie, um andere zu fangen und zu versklaven. Sie sind besonders grausam zu entflohenen Sklaven und würden mir die Kehle durchschneiden, wenn ich die Zuflucht auch nur für einen Tag verlassen würde.\n\nReist nach Umbrafenn im Süden und tötet sie und ihren Anführer, Kataru. Bis dahin werde ich jeden Tag um mein Leben bangen.", sourceObjective = "Ikeyen in der Zuflucht des Cenarius möchte, dass Ihr nach Umbrafenn reist und Kataru, 8 Seher von Umbrafenn, 6 Hexendoktoren von Umbrafenn und 6 Orakel von Umbrafenn tötet.", completion = "Danke, {name}. Endlich werde ich nachts ruhig schlafen können. Wäre ich nicht so alt und schwach, würde ich mich selbst mit meinen Feinden auseinandersetzen.\n\nNehmt dieses Gold. Es ist nicht viel, aber Eure Freundlichkeit darf nicht unbelohnt bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9748] = { id = 9748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkt nicht das Wasser", description = "Unser Schamane bekundet, dass die Wasserelemente durch die Verschmutzung der Wasserquelle sehr stark aus dem Gleichgewicht geraten sind. Wir wissen, dass der Kraftkern der Exodar im westlich gelegenen Berg liegt. Offenbar entweicht von dort eine flüchtige Substanz in die Wasserzufuhr! Ihr müsst für mich mehr Informationen sammeln.\n\n<Aesom deutet auf einen Behälter und nickt.>\n\nNehmt diesen Behälter und folgt dem Strand Richtung Norden bis Ihr auf den Punkt trefft, an dem die Flüsse der Blutmythosinsel in das Meer fließen. Entnehmt an dieser Stelle eine Probe und kehrt zu mir zurück.", sourceObjective = "Verteidiger Aesom bei der Blutwacht möchte, dass Ihr den Wasserprobenbehälter verwendet, um eine Wasserprobe der Blutmythosinsel zu entnehmen.", progress = "Trinkt nicht das Wasser, {name}!", completion = "Wie ich vermutet habe, ist das Wasser von der Verseuchung durch die austretende Kernflüssigkeit rot geworden.\n\nIch hoffe, dass Ihr nicht in dem verseuchten Wasser geschwommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9749] = { id = 9749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie leben! Vielleicht...", description = "Es war ein blutiges Gemetzel, {name}. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.\n\nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!\n\nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?\n\nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!", sourceObjective = "Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[9750] = { id = 9750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Nachricht" }
quests[9751] = { id = 9751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Blutfluchs", description = "Letzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.\n\nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich der Blutwacht liegt, suchen?", sourceObjective = "Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.", completion = "Habt Ihr von dem Blutfluch gehört, Landratte? Nein, natürlich nicht. Der Blutfluch ist das, was all diese Schiffe hat sinken lassen. Der verderbte, entweihte Teil des Wassers hier wird Riff des Blutfluchs genannt - ein Teil der Welt, den Ihr niemals sehen möchtet. Ich bin hier selbst seit 20 Jahren.\n\nSkorbut, so ein Quatsch! Ich starb an diesen Wilden Ufern als Drachenfutter... Ah, das ist wieder eine andere Geschichte, für ein anderes Mal. Jetzt müssen wir den armen Seelen helfen, die hier im Riff gefangen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9752] = { id = 9752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Umbrafenn", description = "Ihr müsst mir helfen hier rauszukommen!\n\nIch habe in der Nähe Kräuter gesammelt, als ein paar dieser Wilden mich entführten. Ich habe versucht mich loszureißen, aber es waren zu viele.\n\nHelft mir zurück zur Zuflucht des Cenarius und weg von diesen grausamen Schuften und ihrer bösen Magie zu gelangen!", sourceObjective = "Begleitet Kayra Langmähne zur Zuflucht des Cenarius in den Zangarmarschen. Gebt Ysiel Windsänger Bescheid, sobald Ihr diese Aufgabe erledigt habt.", completion = "Ihr habt einen meiner Druiden gerettet. Das könnten wir Euch niemals zurückzahlen, {name}.\n\nIhr habt meinen Dank sowie den Dank der Expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[9753] = { id = 9753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir wissen...", description = "Wir haben in den vergangenen Tagen viel über unsere Feinde gelernt. Die Blutelfen werden von einer gewissen Sironas angeführt und haben vor, uns zu zerstören. Letztendlich wollen sie noch O'ros versklaven und wieder die Kontrolle über die Exodar gewinnen.\n\nDem Licht sei Dank, konnten wir ihre Versorgungszufuhr abschneiden, indem wir das Sonnentor zerstörten. Sie verwenden jedoch die Verunreinigung der Vektorspule, um das Land zu vergiften, und nutzen somit dessen mutagene Eigenschaften zu ihrem Vorteil.\n\nAdmetius hat auf Grund dieser Informationen einen Plan ausgeklügelt. Geht zu ihm.", sourceObjective = "Sprecht mit Exarch Admetius bei der Blutwacht.", completion = "Ich brauche Eure Hilfe, {name}. Es ist mein Plan, die gesamte Armee der Sonnenfalken zu stürzen. Zuvor gilt es jedoch ein paar grundlegende Informationen zu sammeln.\n\nWir müssen die Schwäche ihrer Verteidigung ausmachen. Unglücklicherweise ist es uns bis jetzt noch nicht gelungen, nahe genug an die Vektorspule heranzukommen und ihre Verteidigung auszukundschaften. Wenn wir den Gefangenen zum Sprechen bringen könnten, würden wir womöglich die Informationen bekommen, die wir brauchen, um durch ihre Verteidigung zu brechen und die Vektorspule zu zerstören.\n\nIhr habt richtig gehört, ich will das verdammte Ding in die Luft jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9756] = { id = 9756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir nicht wissen...", description = "Unsere Vernehmungsversuche sind kläglich gescheitert, {name}. Folter kommt - natürlich - nicht in Frage. Was wir brauchen, ist <ein/eine:r> {race}, <der/die:r> an ihn herankommen kann.\n\nIch kann einen Zauber auf Euch wirken, der Euch wie <einen Blutelfen/eine Blutelfe> aussehen lässt und Eure Sprache anpasst. Mit dieser List werden wir vielleicht die benötigten Informationen von dem gefangenen Agenten bekommen.\n\nIch möchte, dass Ihr Euch mithilfe dieser Verkleidung das Wissen des Gefangenen erschleicht.\n\nUnd {name}, verlasst die Blutwacht nicht, solange Ihr verkleidet seid, da sonst der Zauber aufgehoben wird.", sourceObjective = "Sprecht mit einem gefangenen Agenten der Sonnenfalken bei der Blutwacht und eignet Euch Informationen der Sonnenfalken an. Kehrt zu Admetius zurück, sobald Ihr Eure Aufgabe erfüllt habt.", completion = "A-ha! Gut gemacht, {name}. Wirklich sehr gut gemacht. Seid Ihr bereit der Blutelfenbedrohung unserer Insel nun endlich ein Ende zu bereiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9757] = { id = 9757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Jägerin Kella Nachtbogen auf", description = "Jägerin Kella Nachtbogen hat um eine Audienz mit allen qualifizierten Jägern gebeten. Sie lehrt das Zähmen von wilden Tieren, etwas, das Ihr vor allem anderen zum jetzigen Zeitpunkt Eurer Ausbildung lernen solltet.\n\nIhr findet Kella in der Nähe von Valaars Steg, den Docks westlich der Exodar.", sourceObjective = "Sprecht mit Jägerin Kella Nachtbogen nahe Valaars Steg.", sourceObjectiveStatus = "unverified-source-field" }
quests[9758] = { id = 9758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Arkanist Vandril", description = "Nun, <mein Freund/meine Freundin>, wenn Ihr so nett wärt, zu Arkanist Vandril zurückzukehren? Ich weiß, er ist begierig, Euch auf Eure erste Mission hier in den Geisterlanden zu senden.\n\nWir zählen auf Euch, {name}. Enttäuscht uns nicht.", sourceObjective = "Kehrt zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", completion = "Ah, gut, da seid Ihr ja. Und gerade zur rechten Zeit, es gibt viel zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[9759] = { id = 9759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Welt enden lassen", description = "Nehmt diesen Auftrag nicht an, wenn Euch etwas an Eurem Leben liegt. Seht Ihr den gigantischen Kraftkern, der aus der Seite des Bergs dort drüben hervorragt? Wer auch immer diese Last auf sich nehmen möchte, muss sich seinen Weg durch den Berg kämpfen und eine Armee der Sonnenfalken abwehren, um mich zu beschützen, während ich die Zerstörung des Kerns vorbereite. Sironas der Eredar ist auch irgendwo dort oben.\n\nIch werde Euch nicht weniger schätzen, wenn Ihr jetzt einfach geht, {name}.\n\nVielleicht seid Ihr aber genau die Person, die die Vektorspule zerstören und Sironas zu Fall bringen kann. Seid Ihr es?", sourceObjective = "Folgt und beschützt Demolierer Legoso, während er versucht, die Vektorspule zu zerstören und tötet Sironas. Kehrt zu Exarch Admetius bei der Blutwacht zurück, sobald Ihr Eure Aufgabe erfüllt habt.", completion = "Ihr habt die ganze Blutmythosinsel und Azurmythosinsel gerettet, das Leben der {race} in Azeroth gesichert, {name}! Dafür wird man Euch niemals genug danken können, keine Belohnung, nichts ist groß genug, um Euch unsere Anerkennung zu zeigen.\n\nLeider blieben noch so viele auf Draenor zurück, die dieses historische Ereignis nicht miterleben können. Ihr müsst Euren Weg zurückfinden. Findet Euren Weg zur Scherbenwelt, Held von Argus. Bringt Eure Leute nach Hause. Nach Hause in das Land, das Ihr gerettet habt. Nach Azeroth...", sourceObjectiveStatus = "unverified-source-field" }
quests[9760] = { id = 9760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigers Ruh'", description = "Ich würde Euch nicht bitten, die Vektorspule und Sironas im Alleingang zu vernichten, {name}, dennoch glaube ich, dass Ihr uns helfen könnt, den Weg für andere abzusichern, die solch einen gefährlichen Auftrag auf sich nehmen werden.\n\nNehmt die Straße, die nördlich aus der Blutwacht führt, und folgt dem Verlauf bis Ihr auf die Weggabelung stoßt. Biegt auf die linke Straße ab und geht solange weiter bis Ihr zu Verteidigers Ruh' kommt - es liegt leicht westlich von der Straße selbst. Corin wird dort auf Euch warten.", sourceObjective = "Sprecht mit Verteidigerin Corin bei Verteidigers Ruh' auf der Blutmythosinsel.", completion = "Vielleicht verhelft Ihr unserem Volk ja zu einem neuen Zeitalter des Wohlstands und des Friedens.", sourceObjectiveStatus = "unverified-source-field" }
quests[9761] = { id = 9761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Nur die wirklich Kampferprobten, Edelmütigen und Furchtlosen werden sich Legosos Auftrag stellen. Der Exarch wird keinen Agenten der Hand damit beauftragen, die Vektorspule zu zerstören und Sironas zu stürzen. Er lehnt es ab, Draenei in ihren Tod zu schicken - genau darum geht es bei diesem Auftrag: Selbstmord...\n\n<Corin seufzt.>\n\nIch bin dafür verantwortlich, die Verteidigung der Sonnenfalken zu schwächen. Eure Aufgabe besteht darin, Sonnenfalken nahe der Vektorspule zu töten und somit den Weg für unseren Helden frei zu machen - wer immer es auch sein mag.", sourceObjective = "Verteidigerin Corin bei Verteidigers Ruh' möchte, dass Ihr 8 Saboteure der Sonnenfalken und 8 Agenten der Sonnenfalken tötet.", completion = "Hoffentlich meldet sich bald ein Held, bevor sie Verstärkung anfordern können, um die gerade von Euch abgesicherte Gegend zu bewachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9762] = { id = 9762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ungeschriebene Prophezeiung", sourceObjective = "Diese Inseln werden für Tausende ein Zuhause sein. Die meisten werden ihr gesamtes Leben hier verbringen. Ihr könntet das auch, aber es ist nicht, was Ihr wollt, oder {name}?\n\n\n\nIhr werdet in Eurem Leben noch viele großartige Taten vollbringen. Ihr müsst Euer Schicksal umarmen und es willkommen heißen!\n\nBevor Ihr geht, möchte ich Euch noch zwei Geschenke überreichen: Dieser Wappenrock wird nur von denen getragen, die den höchsten Respekt der Hand von Argus genießen; und nur die Weisesten besitzen diesen Siegelring. Tragt beides mit Stolz, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9763] = { id = 9763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteck des Kriegsherren", description = "Es hat Vorteile, sich heimlich am Eingang zum Versteck des Feindes zu verstecken.\n\nVor ein paar Stunden sah ich eine Gruppe von Naga durch den steinernen Torbogen am zweiten Tunnel von links gehen. Ich bin in ihrer Sprache nicht sehr bewandert, aber ein Wort habe ich sehr deutlich verstanden: Kalithresh.\n\nDas muss der Eingang zu den Dampfkammern sein, von denen aus Kriegsherr Kalithresh seine Truppen befehligt. Ihr müsst ihn finden und aufhalten! Ich bin leider zu schwach, um Euch dabei helfen zu können.", sourceObjective = "Behüterin Jhang möchte, dass Ihr Kriegsherr Kalithresh im Echsenkessel findet und tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9764] = { id = 9764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Lady Vashj", description = "Dieser Brief enthält genaue Anweisungen für die Naga des Echsenkessels, die die Dampfpumpen bedienen. Er enthält eine Warnung vor der Ankunft von Druiden des Cenarius in dem Gebiet und die Anweisung, sie unverzüglich zu töten. Die Geschwindigkeit, mit der das Wasser aus den Seen in den Echsenkessel abgepumpt wird, soll verdoppelt werden. Die Befehle tragen das Siegel der berüchtigten Lady Vashj.\n\nDieser Brief dürfte die Druiden der Expedition des Cenarius sehr interessieren. Bringt ihn zur Leiterin der Expedition, Ysiel Windsänger.", sourceObjective = "Bringt die Befehle von Lady Vashj zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9765] = { id = 9765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitungen", description = "Die Expedition des Cenarius fing einst als friedliches Projekt an, doch nun stehen wir am Rande eines ausgewachsenen Kriegs gegen die Naga.\n\nUnter uns sind einige, die zwar gerne kämpfen würden, aber nur sehr schlecht ausgerüstet sind. Bringt mir die Waffen der Naga, damit wir sie zu Gleven und Pfeilspitzen umschmelzen können.\n\nNur Waffen aus hochwertigem Material können für uns nützlich sein, {name}. Ihr werdet die der Naga im Echsenkessel stehlen müssen.", sourceObjective = "Besorgt die Waffen des Echsenkessels von den Naga im Echsenkessel und kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9766] = { id = 9766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen des Echsenkessels" }
quests[9767] = { id = 9767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind kennen", description = "Um einen Feind zu besiegen braucht man weit mehr als eine Überzahl an Männern oder Kraft. Oft hängt der Sieg davon ab, ob man die Schwächen des Feindes oder seine typischen Vorgehensweisen kennt.\n\nWir wissen zwar viel über die Naga, aber ihre Magie bleibt uns immer noch fremd.\n\nIch habe vor, mich mit der Hydromantie der Naga des Echsenkessels auseinanderzusetzen. Bringt mir eines ihrer Zauberbücher, damit ich mehr darüber erfahren kann.", sourceObjective = "Besorgt ein Zauberbuch des Echsenkessels von den Naga im Echsenkessel und bringt es zu Ashyen in der Zuflucht des Cenarius in den Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9768] = { id = 9768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberbücher des Echsenkessels" }
quests[9769] = { id = 9769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mode kann man nicht erklären", description = "<Magasha kichert still in sich hinein.>\n\nIch wette, wenn sie wüssten, dass sie Insektenteile anhaben, wäre der Trend schnell vorbei.\n\nZuerst haben wir angefangen, die Insekten in der Umgebung zu töten, weil sie bei den Bauarbeiten im Weg waren. Eines Tages kam ein geschäftstüchtiger Händler hierher, blieb über Nacht und plötzlich fing er an alle Insektenflügel, die er bekommen konnte, aufzukaufen!\n\nSagte, er mache Kleidung daraus. Ich bleib lieber bei meiner Rüstung, danke. Aber wenn Ihr die Flügel der Glühwürmchenarten in der Umgebung sammelt, kaufe ich sie Euch gerne ab.", sourceObjective = "Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Magasha im Sumpfrattenposten.", progress = "Was ist los? Hat Euch jemand die Flügel gestutzt?\n\n<Magasha kichert über ihren Witz.>", completion = "Die sind fein, {name}. Hier ist Eure Bezahlung.\n\n\n\nNe, nicht mein Fall, aber ich hab ja auch keine Ahnung von Mode.\n\n\n\nEs ist das Geld, was zählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9770] = { id = 9770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohliche Marschenfänge", description = "Manchmal wünschte ich, Denjai hätte uns einen Schamanen mitgeschickt oder uns wenigstens ein Totem gegeben, um die Marschfangreißer fernzuhalten.\n\nEs wimmelt hier nur so von diesem Ungeziefer! Das ist doch nicht gerecht. Sollte nicht irgendwas diese widerlichen Käfer auffressen?\n\nWir haben alle schon abwechselnd Kammerjäger gespielt. Ihr seid genau zur richtigen Zeit gekommen, {name}. Glückwunsch! Und jetzt geht los und wischt ein paar Marschfänge auf!", sourceObjective = "Reavij im Sumpfrattenposten möchte, dass Ihr 10 Marschfangreißer tötet.", completion = "Schon satt?\n\n<Reavij lacht.>\n\nEs gibt einen Grund warum unsere Besucher nicht lange bleiben.\n\nWenn ich eine Wahl hätte, würde ich einen angenehmeren Ort für den Posten auswählen. Aber ich ziehe die Marschfänge immer noch Denjais Launen vor!", sourceObjectiveStatus = "unverified-source-field" }
quests[9771] = { id = 9771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Späher Jyoba", description = "Jetzt, da Ihr mit dem Gelände vertraut seid, würde ich Euch gerne bei einer anderen Sache um Hilfe bitten. Das Todesmoor, so nennen wir das Gebiet im Nordwesten, ist ein schauriger Ort. Niemand hat dort je ein Lebewesen gesehen, aber es war auch nie jemand lange dort.\n\nSpäher Jyoba hat sich freiwillig gemeldet, um das Gebiet zu untersuchen und von seinen Beobachtungen zu berichten. Er hat den Posten vor drei Tagen verlassen und ist noch nicht zurückgekehrt. Er würde nie so lange wegbleiben ohne einen Bericht zu schicken. Könntet Ihr nach ihm suchen, {name}?", sourceObjective = "Sucht Späher Jyoba im Todesmoor in den Zangarmarschen.", completion = "Diese in Mitleidenschaft gezogene Leiche passt genau zu Zurais Beschreibung. Was auch immer den Späher getötet haben mag, muss ihn überrascht haben, da er seine Waffen nicht gezogen hatte und Tintenflecken auf dem Boden zu sehen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9772] = { id = 9772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jyobas Bericht", description = "Fetzen von welkem Pilz befinden sich überall auf dem Körper von Späher Jyoba. Was auch immer ihn getötet hat muss aus demselben siechenden Pilz bestehen wie die riesigen welkenden Pilze des Todesmoors. Vielleicht hat ihn einer der siechenden Riesen überrascht, als er gerade seinen Bericht schreiben wollte.\n\nOhne den Text des Berichts ist es fast unmöglich herauszufinden, was der Späher entdeckt hat. Wenn der Bericht gefunden werden könnte, sollte er unbedingt zu Zurai gebracht werden.", sourceObjective = "Besorgt Späher Jyobas Bericht von den siechenden Riesen und kehrt dann zu Zurai im Sumpfrattenposten zurück.", progress = "Ihr seid zurück, aber Jyoba ist nicht bei Euch. Was ist mit ihm passiert?", completion = "<Zurai nimmt den Bericht von Euch und schaut ihn sich an.>\n\nViele von diesen Informationen sind uns bereits bekannt. Alles in dieser Gegend scheint ausgetrocknet oder am verwelken zu sein, aber hier steht etwas neues.\n\nEr sagt, die Fungusgiganten sind von dem Wassermangel wahnsinnig geworden. Eurer Beschreibung nach muss es einer von ihnen gewesen sein, der ihn umgebracht hat.\n\nIch werde meinen Männer anweisen, die Gegend zu meiden. Wir können uns keine weiteren Verluste erlauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9773] = { id = 9773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Pilze mehr!", description = "Pilzsuppe, Pilzeintopf, Pilzsoße!\n\nPilze, Pilze, Pilze! Was anderes bekommt man hier nicht zu essen. Wenn man sagt, dass man Hunger hat, drückt der Koch einem eine Axt in die Hand und sagt: Schlag Dir Dein Abendessen selbst!\n\nNun, ich habe Pilze satt. Ich habe Fische in den Seen hier gesehen. Klar, sie sehen aus, als würden sie sich wehren, aber sie müssen einfach besser schmecken als Pilze!\n\nWie viel würde es mich kosten Euch zu beauftragen, mir mein erstes anständiges Abendessen seit Wochen zu bringen?", sourceObjective = "Bringt 8 Aalfilets von Umbrafennaalen zu Magasha im Sumpfrattenposten.", progress = "Bitte sagt mir nicht, dass Ihr mit leeren Händen zurückgekommen seid, {name}.", completion = "Endlich, eine Abwechslung zu den Pilzen! Wenn Ihr nicht nach Fisch riechen würdet, würde ich Euch umarmen.\n\nWollen wir mal schauen, wie neidisch die anderen werden, wenn sie meinen gebratenen Fisch riechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9774] = { id = 9774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicke Hydraschuppen", description = "Es war sehr klug von Reavij Lederrüstung mitzubringen. Der Sumpf wird meine Panzerrüstung innerhalb von kurzer Zeit wertlos machen.\n\nIch habe schon so weit ich konnte nach und nach alle Schuppen ausgetauscht. Die Hydras in dem Marschen haben dicke, schützende Schuppen, die der Feuchtigkeit ihrer Heimat optimal standhalten.\n\nGeeignete Schuppen zu finden ist allerdings ziemlich langwierig. Oftmals sind sie zu kaputt, zu abgenutzt oder zu dünn um sie als Rüstung zu verwenden. Bringt mir ein paar geeignete Schuppen von den Hydras in den größeren Seen.", sourceObjective = "Bringt 12 dicke Hydraschuppen zu Zurai im Sumpfrattenposten.", progress = "Ich sehe, dass Ihr grinst. Ja, meine Rüstung wird etwas merkwürdig aussehen, bis ich das ganze alte Metall ersetzt habe, aber besser so als ungeschützt.", completion = "Danke, {name}. Jedes noch so kleine bisschen hilft.\n\nEs ist immer noch viel zu tun, aber mal ehrlich, was soll ich sonst zwischen den Patrouillen machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9775] = { id = 9775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Schattenjäger Denjai", description = "Schattenjäger Denjai erwartet sicher einen Bericht über meine Fortschritte bei der Errichtung unseres Außenpostens. Ich habe eine Zusammenfassung unserer bisherigen Errungenschaften vorbereitet, aber seit wir Späher Jyobe verloren haben, kann ich keinen Boten entbehren, um den Bericht zu Denjais Posten Zabra'jin im Westen zu bringen.\n\nWenn Ihr in die Richtung geht, könntet Ihr ihm den Bericht vielleicht von mir geben? Schattenjäger Denjai kann auf den ersten Blick etwas einschüchternd wirken, aber wenn Ihr Euch an ihn gewöhnt habt, ist er kein übler Kerl.", sourceObjective = "Bringt Zurais Bericht zu Schattenjäger Denjai in Zabra'jin in den Zangarmarschen.", progress = "Ihr seht nicht aus wie einer meiner Männer. Was wollt Ihr, {race}?", completion = "Warum habt Ihr nicht gleich gesagt, dass Ihr einen Bericht von Zurai habt? Ich warte schon auf Nachricht von ihm.\n\nIch habe ihn nach Osten geschickt, damit er dort einen Posten baut, nicht um auf den Händen zu sitzen. Wollen wir mal sehen, was er zu sagen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9776] = { id = 9776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oreborzuflucht", description = "Wie Ihr sicher wisst, sind viele Einwohner von Telredor Flüchtlinge aus dem Krieg, der die Draenei dezimiert hat. Es ist mein Ziel, Telredor als sicheren Hafen für all unsere Verbündeten in diesem Kampf zu gewinnen. Es gibt einige, die sich uns gerne anschließen möchten, aber spüren, dass sie noch nicht bereit sind.\n\nWir schulden ihnen jede Hilfe, die wir ihnen bieten können, {name}. Eine Gruppe von Zerschlagenen unter der Führung von Ikuti hat in den Ruinen eines alten Tempels nordwestlich vom Schlangensee Zuflucht gefunden. Sucht sie und reicht ihnen Eure Hand in Freundschaft.", sourceObjective = "Sprecht mit Ikuti in der Oreborzuflucht in den Zangarmarschen.", completion = "Wenn Anachoret Ahuurn Euch als Freund betrachtet, kann ich Euch vielleicht vertrauen. Bitte vergebt mir meinen Argwohn, {race}, doch oft rettet nur dieser mein Volk vor dem Tod. Seid in unserer Zuflucht willkommen. Vielleicht wird so unser gegenseitiges Vertrauen wachsen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9777] = { id = 9777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fulgorsporen", description = "Es gibt nur wenig Brennbares in diesem Sumpf, {race}, daher müssen wir auf andere Mittel zugreifen, um Telredor zu erleuchten. Viele Tiere und Pflanzen in den Marschen strahlen ein schwaches Leuchten aus.\n\nEs ist schwierig und grausam die leuchtenden Tiere einzusperren, deshalb haben wir uns einen Pilz als Lichtquelle gesucht.\n\nWir bauen die Fulgorpilze hier an, aber ab und zu benötigen wir auch neue Pflanzen. Die kleinen grünen Pilze wachsen an den größeren in der Nähe von Telredor.", sourceObjective = "Bringt 6 Fulgorsporen zu Ruam in Telredor.", progress = "So wie es aussieht brauchen wir sehr bald neue Sporen.", completion = "Diese Sporen sind sehr gut und sollten uns für einen Weile reichen. Vielen Dank für Eure Hilfe bei der Aufstockung unserer Vorräte, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9778] = { id = 9778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Hamuht", description = "Sprecht auf jeden Fall noch mit Aufseher Hamuht, bevor Ihr die Zuflucht des Cenarius verlasst. Er ist für die Sicherheit der Expedition verantwortlich.\n\nEr würde mir nie verzeihen, wenn ich einen erfahrenen Abenteurer wie Euch nicht zu ihm schicken würde.", sourceObjective = "Meldet Euch bei Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "Ysiel hat Euch geschickt? Natürlich habe ich für jemanden wie Euch Verwendung! Wir können immer ein paar Muskeln brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9779] = { id = 9779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abfangen der Nachricht", description = "Schön, Euch wiederzusehen, {name}. Ich hätte da eine heikle Aufgabe, die es zu lösen gilt.\n\nUnsere Agenten, die die Sonnenfalken ausspionieren, haben berichtet, dass Soldaten der Sonnenfalken ein ungewöhnliches Dokument untersucht haben.\n\nUnglücklicherweise konnten wir keine Kopie dieses Schreibens für uns selbst beschaffen. Ihr müsst für mich vor Ort gehen und das Dokument an Euch bringen. Ich bin mir sicher, dass Euch ein Sonnenfalke die von uns gesuchten Informationen geben wird, wenn Ihr genug Druck anwendet. Ich überlasse den Einsatz von Gewalt voll und ganz Eurem Ermessen.", sourceObjective = "Tötet die Elfen der Sonnenfalken, bis Ihr das Schreiben der Sonnenfalken findet, und bringt es zu Verteidiger Boros bei der Blutwacht.", progress = "Schon zurück? Konntet Ihr das Schreiben finden?", completion = "<Verteidiger Boros betrachtet das Dokument.>\n\nDas ist Thalassisch. Glücklicherweise kenne ich eine Person, die es übersetzen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[9780] = { id = 9780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalfilets von Umbrafenn", description = "Schön, ein neues Gesicht hier zu sehen. Als Haalrun und ich nach Telredor kamen, waren wir die ersten von außerhalb, aber das scheint schon eine Ewigkeit her zu sein.\n\nTrotzdem heißen wir Neuankömmlinge immer willkommen und versuchen dafür zu sorgen, dass alle genug zu essen haben. Wir werden die Freundlichkeit der Anachoreten von Telredor niemals vergelten können, aber wir können ihrem Beispiel folgen und ebenso freundlich zu anderen sein.\n\nWenn Ihr helfen möchtet, dann fangt ein paar der Fische, die sich in den Seen in der Gegend tummeln. Sie heißen Umbrafennaale und sind Hauptbestandteil unserer Nahrung.", sourceObjective = "Bringt 8 Aalfilets zu Noraani in Telredor.", progress = "Habt Ihr schon Fische für unsere Vorräte besorgt?", completion = "Danke für Eure Hilfe, {name}. Euer Großmut wird nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9781] = { id = 9781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Mäuler zu stopfen", description = "Auf meiner letzten Jagd habe ich gesehen, dass eine Gruppe von Trollen im Begriff ist, einen neuen Außenposten zu bauen. Ohne Zweifel haben sie auch angefangen, hier zu jagen.\n\nWenn sie einen dauerhaften Standort hier errichten, wird es einen erbitterten Kampf um Nahrung geben. Wir können sie nicht direkt angreifen, ohne sie zu provozieren. Aber wir können unsere natürlichen Wettbewerber im Nahrungskampf reduzieren.\n\nJede Morasthydra, die Ihr erlegt, bedeutet drei Mäuler weniger, die gestopft werden müssen!", sourceObjective = "Tötet 10 Morasthydras und kehrt zu Haalrun in Telredor zurück.", completion = "Gut gemacht. Das sollte den Bedarf an Nahrung in der Gegend für die nahe Zukunft etwas mindern, auch wenn wir immer noch nach neuen Nahrungsquellen suchen sollten. Fisch und Pilze reichen aus, aber etwas Abwechslung sollte nicht unterschätzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9782] = { id = 9782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Todesmoor", description = "Ich lebe nun seit einiger Zeit bei den Anachoreten von Telredor, {name}, und inzwischen kenne ich die Marschen ganz gut. In letzter Zeit habe ich eine erschreckende Veränderung des Landes im Nordosten bemerkt.\n\nFast alles Leben dort hat begonnen zu welken und zu sterben, und das scheinbar ohne Grund. Ich habe ein paar Vermutungen, was dort vorgehen könnte, aber sie sind nur sehr vage. Wenn Ihr mir eine Bodenprobe dieser Gegend bringen könntet, dann könnte ich diesem Rätsel vielleicht auf den Grund kommen.", sourceObjective = "Bringt eine Erdprobe vom Todesmoor zu Verteidiger Idaar in Telredor.", progress = "Konntet Ihr eine Probe der Erde des Todesmoors bekommen?", completion = "Hmm... der Boden ist nicht ausgelaugt, das kann also nicht der Grund für das Problem sein, wie ich zuerst vermutet habe. Wo liegt die Verbindung? Warum stirbt alles so plötzlich?", sourceObjectiveStatus = "unverified-source-field" }
quests[9783] = { id = 9783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unnatürliche Dürre", description = "Die Erdprobe, die Ihr mir gebracht habt, ist fast ausgetrocknet, {name}. Wenn schon der Boden seine Feuchtigkeit verliert, müssen die Lebewesen im Todesmoor furchtbar leiden.\n\nIch habe gesehen, was passiert, wenn die Fungusgiganten der Gegend anfangen zu welken und zu sterben. Der Schmerz macht sie wahnsinnig und bringt sie dazu, alles in ihrer Nähe anzugreifen.\n\nDiese Lebewesen haben nicht die leiseste Ahnung, was mit ihnen geschieht. Sie zu retten liegt außerhalb unserer Macht. Das Einzige, was wir tun können, ist ihr Leiden zu beenden.", sourceObjective = "Verteidiger Idaar möchte, dass Ihr 12 siechende Riesen tötet.", completion = "Danke für Eure Hilfe bei dieser schweren Aufgabe, {name}. Unsere Arbeit im Todesmoor ist noch nicht beendet, aber nun können wir uns darauf konzentrieren, das Gleichgewicht in der Gegend wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9784] = { id = 9784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzenteile identifizieren", progress = "Ich könnte noch mehr Pflanzenteile brauchen. Jetzt, da die Seen ihr Wasser verlieren, befürchte ich, dass die fremden Arten zunehmen werden. Ich brauche aber mehr Beweise, um meine Theorie zu untermauern.", completion = "Ausgezeichnet. Wenn Ihr noch mehr Pflanzenteile findet, bringt sie zu mir.\n\n<Diese Quest kann wiederholt werden, bis Ihr einen wohlwollenden Ruf erlangt habt.>" }
quests[9785] = { id = 9785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen der Uralten", description = "Ihr habt Euch das Vertrauen der Expedition des Cenarius verdient, {name}. Es ist an der Zeit, dass Ihr Euch mit den Urtumen unterhaltet, die sich unserer Sache angeschlossen haben, Ashyen und Keleth, und um ihren Segen bittet.\n\nDas Zeichen eines Urtums zu tragen bedeutet große Macht. Je höher Euer Ansehen bei uns steigt, umso wertvoller wird dieser Gefallen werden.\n\nGeht, {name}, und bittet die Urtume um ihren Segen.", sourceObjective = "Windruferin Schwarzhuf möchte, dass Ihr mit den Urtumen Ashyen und Keleth in der Zuflucht des Cenarius sprecht und um ihren Segen bittet.", completion = "Ihr seid zurück. Habt Ihr den Segen der Uralten erhalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9786] = { id = 9786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Boha'mu", description = "Bevor mein Volk von den Orcs dezimiert wurde, diente Telredor als Zuflucht für die Anachoreten und Spiritualisten der Draenei. Ein kleiner Orden von Anachoreten und Verteidigern pflegte ein paar Schreine in dieser Region.\n\nWährend des Krieges verloren wir den Kontakt zu den Anachoreten, die für diese Schreine zuständig waren, besonders zu denen im Tempel von Boha'mu im Südwesten. Ich habe gehört, dass ein Stamm von Verirrten sich in dieser Gegend niedergelassen hat und vielleicht sogar in den Ruinen lebt. Geht zu den Ruinen von Boha'mu und berichtet mir, was Ihr dort findet.", sourceObjective = "Anachoret Ahuurn in Telredor möchte, dass Ihr die Ruinen von Boha'mu erforscht.", completion = "Die Verirrten des Wildfennstamms haben sich also in den Ruinen eingenistet? Das ist verblüffend. Sie müssen sich an Ihr Erbe erinnern und die Wichtigkeit dieses Ortes erkennen können. Wir müssen mehr darüber erfahren, {name}. Vielleicht ist in diesem Tempel der Schlüssel zur Erlösung der Verirrten und zur Wiedervereinigung der verschiedenen Arten der Draenei versteckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9787] = { id = 9787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzen des Wildfennstamms", description = "Aus Eurem Bericht über die Ruinen von Boha'mu hörte ich heraus, dass dieser Stamm der Verirrten zur Verehrung von Tiergeistern zurückgekehrt ist. Bevor wir auf sie zugehen können, müssen wir mehr über ihren Glauben in Erfahrung bringen.\n\nKehrt zurück nach Wildfenn und sammelt heimlich ein paar ihrer Götzen, damit ich sie untersuchen kann. Versucht jedoch, sie nicht wütend zu machen, sonst haben wir vielleicht keine Chance mehr, Kontakt mit ihnen aufzunehmen.", sourceObjective = "Sammelt 6 Wildfenngötzen und kehrt dann zu Anachoret Ahuurn in Telredor zurück.", progress = "Habt Ihr die Götzen?", completion = "Diese sollten mehr als ausreichen, {name}. Sie scheinen auf Vögel fixiert zu sein, was merkwürdig ist, da es in den Zangarmarschen keine einheimischen Vogelarten gibt. Was könnte das wohl bedeuten?\n\nSind sie vielleicht auf die Arakkoa getroffen? Für ein schamanistisches Volk mögen sie vielleicht wie der Inbegriff eines mächtigen Vogelgeists wirken.", sourceObjectiveStatus = "unverified-source-field" }
quests[9788] = { id = 9788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuchter, düsterer Ort", description = "Bald nachdem ich dem Umbrafennstamm entkommen war, habe ich mich in einer Höhle südlich des Dorfs verkrochen. Ich hatte ja keine Ahnung, dass die Tiere der Marschen und die Sporenmänner sich um die Höhle stritten!\n\nIch musste sehr plötzlich von dort fliehen und eine Kiste mit meinem weltlichen Besitz zurücklassen.\n\nEs grenzte schon an Ironie, dass ich mit meinem ganzen Hab und Gut aus Umbrafenn entkommen konnte, nur um es so bald darauf wieder zu verlieren. Wenn Ihr mir meine Sachen wiederbringen könntet, würde ich Euch etwas aus meinem persönlichen Besitz schenken. Seid Ihr einverstanden, {name}?", sourceObjective = "Sucht nach Ikeyens Habseligkeiten in einer Höhle südlich von Umbrafenn. Bringt sie zurück zu Ikeyen in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Habt Ihr meine Habseligkeiten gefunden, {name}? Die Höhle ist nicht weit von Umbrafenn entfernt, nahe an der Grenze zu Nagrand.", completion = "Meine Sachen! Sie sind alle da!\n\nIch danke Euch, {name}. Wie versprochen dürft Ihr Euch etwas von den Dingen aussuchen. Ich habe nicht viel anzubieten, aber mein Volk hat schon immer das Wenige, was wir hatten, geteilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9789] = { id = 9789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Grollhufjagd", description = "Ihr möchtet Euch einen Platz in der Safari verdienen? Dann beweist Euch erst einmal.\n\nMir ist es völlig schnuppe, was Ihr schon alles für Kreaturen erlegt habt, bevor Ihr nicht jagt, was wir jagen, seid Ihr in meinen Augen <kein Jäger/keine Jägerin>. Die Grollhufe wären ein guter Anfang, sofern Ihr <Manns genug/mutig genug> seid.\n\nIch bin mir sicher, dass ich sie in der direkten Umgebung der Safari und in der Nähe im Süden gesehen habe.", sourceObjective = "Erlegt 12 Grollhufe und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück, um Euch zu beweisen.", completion = "Ein akzeptabler Start. Doch das war erst der Anfang.\n\nDie harmloseren Grollhufe beweisen noch gar nichts. Versuchen wir es doch mal mit einer größeren Herausforderung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9790] = { id = 9790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtdurchlässige Flügel", description = "An so einem abgeschiedenen Ort zu leben hat uns gelehrt, einen Nutzen aus allen verfügbaren Dingen zu ziehen. Dabei muss man natürlich lernen zu vergessen, woher einige der Materialien stammen.\n\nIch habe herausgefunden, dass die Flügel der Umbraglimmstecher, die hier in der Gegend leben, sehr gut als Regenschutz dienen. Sie sind stabil, dünn und biegsam.\n\n<Haalrun kichert.>\n\nIch sehe Euren Gesichtsausruck. Wie ich sagte, man muss sich erst an die Idee gewöhnen. Wenn Ihr in der Gegend herumstreicht, könnt Ihr mir dann vielleicht ein paar solcher Flügel mitbringen?", sourceObjective = "Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Haalrun in Telredor.", progress = "Habt Ihr schon ein paar lichtdurchlässige Flügel sammeln können?", completion = "Habt Dank, {name}.\n\n\n\nZumindest müsst Ihr sie nicht säubern. Das ist der schlimmste Teil der Arbeit, aber wenn ich damit fertig bin, werdet Ihr niemals erkennen, dass sie mal zu einem riesigen Insekt gehört haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9791] = { id = 9791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohliche Marschenfänge", description = "Während der Kriege der Orcs gegen mein Volk haben die Nahrungssammler Telredor aus Angst, angegriffen oder gefangen zu werden, kaum verlassen. Nun gehen sie häufiger hinaus, aber die Marschen sind nicht weniger gefährlich.\n\nEs scheint, als wären die Marschenfänge in letzter Zeit aggressiver geworden. Ich weiß nicht, ob das an der erhöhten Konkurrenz für ihre gewöhnliche Nahrung liegt, aber sie greifen regelmäßig unsere Nahrungssucher an. Vielleicht würden sie uns in Ruhe lassen, wenn wir ihren Bestand um Telredor herum etwas dezimieren könnten.", sourceObjective = "Tötet 10 Marschenfangreißer und kehrt dann zu Noraani in Telredor zurück.", completion = "Danke für Eure Hilfe bei der Auslöschung einiger Marschenfangreißer, {name}. Wenn sie über Intelligenz verfügen würden, würden sie vielleicht erkennen, dass es am besten ist, zu leben und leben zu lassen.\n\n\n\nGroße, überwucherte Käfer mit Intelligenz. Ich frage mich, wie das wohl wäre...", sourceObjectiveStatus = "unverified-source-field" }
quests[9792] = { id = 9792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft für Telaar", description = "Ihr habt Euch in unseren Geschäften als vertrauenswürdig erwiesen, {name}, und das in Zeiten, in denen das Vertrauen meines Volkes nur schwer zu gewinnen ist.\n\nEine große Gruppe meiner Brüder und Schwestern hat sich in der alten Draeneistadt Telaar in Nagrand im Süden niedergelassen. Um nach Telaar zu gelangen, müsst Ihr der Straße Richtung Süden nach Nagrand folgen und dann nach Südosten gehen, bis Ihr an die Klippen östlich des Oshu'guns gelangt.\n\nJeder, der uns so sehr geholfen hat wie Ihr, ist dort willkommen.\n\nSucht Aufseher Moi'bff Jill und sagt ihm, dass Ihr mein Vertrauen erlangt habt.", sourceObjective = "Sprecht mit Aufseher Moi'bff in Telaar in Nagrand.", completion = "Ikuti ist wie ein Bruder für mich. Seine Freunde sind auch meine Freunde. Ihr seid hier willkommen, {name}, und Ihr habt unseren Dank für die Hilfe, die Ihr meinem Volk geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9793] = { id = 9793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Tuurem", description = "Prophet Velens Suche nach Verbündeten hat die Draenei in der Scherbenwelt ermutigt, selbst eine Suche zu beginnen. Der Krieg meines Volks mit der Legion hat uns vielleicht aus unseren Städten und Tempeln vertrieben, aber er konnte nicht alle Spuren unserer Zivilisation verwischen.\n\nTuurem, mein früheres Zuhause in den Wäldern von Terokkar, war eine der Städte, die von den Orcs überrannt wurden. Ich habe schon viel zu lange nichts mehr von dort gehört. Bringt diesen Brief zu Andarl in der Festung in Terokkar und schaut, was Ihr herausfinden könnt.", sourceObjective = "Bringt Verteidiger Idaars Brief zu Andarl in der Festung in den Wäldern von Terokkar.", progress = "Wie kann ich Euch helfen?", completion = "Hmm... Ich kann mich erinnern, dass unsere Späher von den Ruinen einer Draeneisiedlung in den nördlichen Ausläufern des Waldes berichtet haben. Ich weiß jedoch selbst nicht viel über die Ruinen, aber Ihr könnt gerne mit unseren Spähern sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9794] = { id = 9794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit für Neugier", description = "{name}, ich muss Euch um einen Gefallen bitten. Normalerweise würde ich das ja nicht tun, aber ich habe beide Hände bereits mehr als voll.\n\nIch habe einen Verbündeten namens Kialon in Sylvanaar im Schergrat im Norden. Er erwartet, dass ich mich in naher Zukunft bei ihm melde, obwohl ich fürchte, dass ihm nicht gefallen wird, was ich zu sagen habe.\n\nWenn Ihr ihm meine Antwort bringen könntet, wäre ich Euch sehr dankbar. Ich muss jedoch darauf bestehen, und das ist sehr wichtig, dass Ihr den Brief nicht lest. Er ist nur für Kialons Augen bestimmt.", sourceObjective = "Bringt Timothys Brief zu Kialon in Sylvanaar im Schergrat.", progress = "<Kialon schaut Euch misstrauisch an.>\n\nIch kenne Euch nicht, {race}. Was wollt Ihr von mir?", completion = "Ihr bringt mir also Timothys Antwort?\n\n<Kialon hält einen Moment inne, um den Brief zu lesen, und fängt an zu lachen.>\n\nEr hat alles unter Kontrolle, sagt er, braucht keine Hilfe. Ich hätte es wissen müssen!\n\nManche Leute ändern sich nie. Schaut, er hat sich sogar die Zeit genommen, meine Rechtschreibfehler zu korrigieren.\n\n<Kialon seufzt halbherzig.>\n\nIch hätte ihm den Brief nicht schicken sollen. Ich habe es vergessen. Der Spezialist hat die Situation immer unter Kontrolle. Immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9795] = { id = 9795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ogerbedrohung", description = "Als ob die Naga und ihre Verbündeten nicht schon genug wären, scheinen nun auch die Oger sich weiter in den Marschen auszubreiten. Sie haben schon weite Teile des Nordwestens erobert, und der Puffer zwischen uns und ihnen wird immer kleiner.\n\nFür jeden, den wir umbringen, sind gleich mehrere neue zur Stelle. Ich weiß nicht, wie lange wir Zabra'jin halten können, wenn sie sich entschließen uns anzugreifen. Geht nach Norden in die Berge zum orcischen Stützpunkt in der Donnerfeste und berichtet Nekthar von unserer Bedrängnis. Jede Hilfe, die er uns zur Verfügung stellen kann, ist äußerst willkommen.", sourceObjective = "Reist zur Donnerfeste im Schergrat und sprecht mit Nekthar.", completion = "Denjai braucht Hilfe? Ich würde ihm gerne ein paar Leute schicken, aber wir können uns selbst kaum halten. Wir haben hier oben unsere eigenen Probleme mit den Ogern.\n\nSobald ich kann, werde ich ihm alle Informationen, die wir über diesen Ogerstamm und seine Taktiken haben, zukommen lassen. Wenn er lang genug durchhält, können wir die widerlichen Kreaturen vielleicht von zwei Seiten aus angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9796] = { id = 9796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht aus den Zangarmarschen", description = "Schattenjäger Denjai ist nicht der Einzige, der auf einen Bericht von mir wartet. Mokasa in der Steinbrecherfeste in Terokkar brennt darauf, von unseren Fortschritten zu hören, besonders seit die meisten ihrer Boten hier auf ihren Reisen vorbeikommen.\n\nSie hat mich gebeten, ihr Bescheid zu geben, sobald der Sumpfrattenposten fertig ist. Wenn Ihr nichts dagegen habt, wäre ich Euch sehr dankbar, wenn Ihr ihr die Nachricht überbringen könntet. Wir haben zwar so weit schon alles aufgebaut, aber es gibt noch viel zu tun.\n\nUm zur Steinbrecherfeste zu gelangen, müsst Ihr der Straße nach Süden in Richtung Zangarmarschen folgen und Euch durch die Wälder von Terokkar an Tuurem vorbei begeben.", sourceObjective = "Sprecht mit Mokasa in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Es wurde auch langsam Zeit, dass der Außenposten fertig wird. Wir haben schon viel zu viele Boten an die Vorhut der Allianz verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9797] = { id = 9797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Garadar", description = "<Immer noch nach Atem ringend bedeutet der Bote Euch, Euch hinzusetzen.>\n\nSie werden vielleicht nicht überleben, {race}! Geht so schnell Euch Eure Beine tragen können nach Garadar.\n\n<Als Reaktion auf Euren fragenden Gesichtsausdruck führt der Bote näher aus.>\n\nDas Zuhause der Mag'har liegt im Süden, in Nagrand. Folgt dem südlichen Weg aus dem Sumpf, nehmt die erste Abzweigung nach Osten und sucht nach einer größeren Siedlung am Seeufer.\n\nFindet dort unseren Kommandanten, Hauptmann Kroghan, und helft ihm, wie Ihr nur könnt. Garadar darf nicht fallen!", sourceObjective = "Sprecht mit Hauptmann Kroghan in Garadar in Nagrand.", completion = "<Auch wenn er sich Mühe gibt, es zu verheimlichen, macht sich Erleichterung auf Kroghans Gesicht breit.>\n\nEs wurde auch langsam Zeit, dass Ihr kommt! Sicher, Ihr seid keine Armee, {race}, aber hier ist ein jeder willkommen, der Kraft genug besitzt, eine Waffe zu führen oder einen Zauber zu wirken. Die Einwohner Garadars sind ein Teil der Horde und stolz, ihr Blut für deren Verteidigung vergießen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9798] = { id = 9798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelfenpläne", description = "Diese Pläne sehen wichtig aus. Ihr solltet sie Verteidiger Aldar bei der Absturzstelle zeigen.", sourceObjective = "Bringt die Blutelfenpläne zu Verteidiger Aldar bei der Absturzstelle im Am'mental.", progress = "Was habt Ihr denn da?", completion = "Hier, lasst mich einen Blick auf diese Pläne werfen.\n\nDie Blutelfen sind uns hierher gefolgt? Sie sind durch und durch bösartig und sollten ganz und gar ausgelöscht werden!\n\n<Der Verteidiger braucht einen Moment, um sich wieder zu fassen.>\n\nEntschuldigung, ich hätte mich beherrschen sollen. Wir stehen für die Entdeckung dieser Informationen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9799] = { id = 9799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanische Hilfsarbeit", description = "Die Am'menfelder im Westen sind das wichtigste Vermehrungsgebiet der einheimischen Peitscherpopulation. Botanikerin Taerix befürchtet, dass sich die Peitscher auf Grund des verseuchten Grundwasserspiegels nicht mehr fortpflanzen können, nachdem wir den See gereinigt haben.\n\nGeht zu den Am'menfeldern und pflückt dort ein paar der verderbten Blumen für mich, damit ich sie untersuchen und sehen kann, was es zu tun gilt. Ihr solltet sie an ihren ungewöhnlichen roten Blüten erkennen.", sourceObjective = "Sammelt 3 verderbte Blumen und kehrt zu Lehrling Vishael bei der Absturzstelle im Am'mental zurück.", progress = "Hallo, {class}. Habt Ihr die Blumen?", completion = "Das sieht mir nach ein paar guten Exemplaren aus. Danke für Eure kleine Hilfsarbeit. Sobald ich Zeit zum Untersuchen der Blumen habe, sollte ich bestimmen können, was es zur Wiederherstellung der Felder bedarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[9800] = { id = 9800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltene Bohne", description = "Ihr seid zu schlecht ausgerüstet um den rastlosen Elementaren Nagrands gegenüber zu treten. Bevor Ihr dem Irdenen Ring helfen könnt, müsst Ihr erst Euch selbst helfen.\n\nIm Westen findet Ihr Kothaufen von den Wildtieren Nagrands. Ihr müsst den Dung nach den verdauten Überresten der Caracolibohne durchsuchen. Aus dieser Bohne kann ich eine Tablette herstellen, die Euch im Kampf gegen die ruhelosen Naturgewalten helfen wird.\n\nKehrt zu mir zurück, wenn Ihr mindestens zwei Fäuste voller Caracolibohnen gesammelt habt... Ogerfäuste!", sourceObjective = "Bringt 8 verdaute Caracolibohnen zu Elementarist Lo'ap am Thron der Elemente.", progress = "<Elementarist Lo'ap ballt seine Hände zu Fäusten und schüttelt den Kopf.>\n\nOgerfäuste...", completion = "Bitte wascht Euch nicht in den heiligen Wassern des Throns.\n\n<Elementarist Lo'ap reicht Euch eine fertige Caracolitablette.>\n\nLegt sie unter Eure Zunge und lasst sie sich auflösen. Einmal aufgelöst werdet Ihr Wasser wie Luft atmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9801] = { id = 9801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reagenzien sammeln", description = "Ich habe das Gefühl, dass diese Verirrten nicht so gut auf <einen/eine> Draenei zu sprechen sein werden, aber vielleicht auf einen Arakkoa. Ich kann einen Zaubertrank herstellen, der Euch für kurze Zeit in einen Arakkoa verwandeln kann. Dazu benötige ich ein paar Reagenzien, die man nur sehr schlecht lagern kann, da man sie sofort nach dem Sammeln weiterverarbeiten muss.\n\nIhr werdet mir ein paar Sporensegleraugen und einige Fennschreitertentakel bringen müssen. Beide Arten leben in der Wildnis um Telredor herum.", sourceObjective = "Anachoret Ahuurn möchte, dass Ihr ihm 4 Sporensegleraugen und 4 Fennschreitertentakel bringt.", progress = "Habt Ihr die Reagenzien schon?", completion = "Diese Reagenzien eignen sich sehr gut. Bitte gebt mir einen Moment Zeit, um den Trank zu mischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9802] = { id = 9802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzen der Zangarmarschen", description = "Die Seen der Zangarmarschen werden langsam entwässert. Wir wissen nicht warum, aber viele Pflanzenarten drohen auszusterben.\n\nAls Katalogisiererin der Expedition ist es meine Aufgabe, diese Pflanzen zu identifizieren und zu verstehen, was mit ihnen geschieht.\n\nWenn Ihr helfen wollt, bringt mir unbekannte Pflanzenteile. Wenn Ihr kräuterkundig seid, könnt Ihr sie direkt vom Boden pflücken, aber auch die einheimischen Wesen des Sumpfs tragen Pflanzenteile bei sich.", sourceObjective = "Bringt 10 unbekannte Pflanzenteile zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Habt Ihr ein paar Pflanzenteile gefunden, {name}?", completion = "Das Abnehmen der natürlichen Arten ist ein Grund zur Sorge. Die Zunahme der eingewanderten Arten könnte mit der neuerlichen Störung des Ökosystems zusammenhängen. Ich habe jedoch noch zu wenig Anhaltspunkte, um Genaueres zu sagen.\n\n<Lauranna macht ein paar Notizen in ein Buch, als sie die Pflanzenteile untersucht.>\n\nNehmt ein paar davon, {name}. Sie könnten vielleicht nützlich für Euch sein.\n\nBringt mir alle weiteren Pflanzenteile, die Ihr finden könnt. Ich werde sie in meiner Statistik auflisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9803] = { id = 9803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft für den Wildfennstamm", description = "Es ist an der Zeit, dem Wildfennstamm die Hand zu reichen und sie zu lehren, dass das Licht sie nicht aufgegeben hat. Nehmt den Trank, den ich vorbereitet habe, und tragt ihn zu den Ruinen von Boha'mu.\n\nSobald Ihr bei den Ruinen angekommen seid, trinkt den Trank um Euch in einen der Vogelgeister zu verwandeln. Sprecht mit dem Ältesten Kuruti und lasst ihn wissen, dass die Draenei bereit sind, sein Volk als verloren geglaubte Brüder und Schwestern zu empfangen.", sourceObjective = "Trinkt Ahuurns Elixier in den Ruinen von Boha'mu. Sprecht mit dem Ältesten Kuruti in der Form eines Arakkoas.", progress = "Habt Ihr schon mit dem Ältesten von Wildfenn gesprochen?", completion = "Sie haben abgelehnt? Natürlich steht es ihnen frei, selbst zu wählen, aber ihre Entscheidung überrascht mich. Ich habe gedacht, dass alle Draenei, also auch die Zerschlagenen und Verirrten, sich daran erinnern würden, dass wir alle ein Volk sind.\n\nIch schätze er hat Recht damit, dass es töricht war zu versuchen, sie hereinzulegen, aber trotzdem, konnte er denn nicht sehen, dass wir in freundlicher Absicht gehandelt haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[9804] = { id = 9804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgebrachte Geister des Himmelsweisensees", description = "Die Unruhen in den Gezeiten der Gewässer von Nagrand hat die Wassergeister des Himmelsweisensees sehr aufgebracht. Sie haben im Gegenzug damit begonnen, Verwüstungen entlang der Wasserwege anzurichten.\n\nWatoosun des Wassers ist uns in einer Vision erschienen und hat uns erlaubt, das Problem zu lösen, solange wir auch die Ursache dafür beheben...\n\nWir werden uns um die Ursache kümmern, doch zuerst müssen wir die direkten Bedrohungen für den Thron beseitigen. Zerstört die aufgebrachten Seegeister und kehrt dann zu mir zurück.", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 8 Seegeister tötet.", completion = "<Elementarist Lo'ap kniet im Wasser und betet.>\n\nDer Irdene Ring ist nicht stolz auf das, was geschehen ist. Wir tun das, was wir müssen, um das Land zu heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9805] = { id = 9805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen des Incineratus", description = "Die erbärmlichen Verirrten, einst verbannt in die Sümpfe der Zangarmarschen, versuchen nun, ihren Dreck auch in andere Teile der Welt zu tragen.\n\nIch habe mich an die weisen Furien gewandt und ihren Segen erhalten. Um die Ursache zu beseitigen, müssen wir die Elemente auf sie hetzen!\n\nIch gebe Euch beseeltes Feuer, entzündet an der feurigen Essenz von Incineratus selbst. Reist nach Schilftanz, südöstlich von hier, und entzündet die Hütten mit dem Feuer! Lasst sie die Wut der Elemente spüren!", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr die große Hütte, die westliche Hütte, die südliche Hütte und die östliche Hütte in Schilftanz zerstört.\n\nBringt das beseelte Feuer zurück zu Elementarist Lo'ap, wenn Ihr fertig seid.", completion = "Eure Bemühungen haben die Ausbreitung der Verschmutzung eingedämmt, aber nun sind neue Probleme aufgetaucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9806] = { id = 9806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruchtbare Sporen", description = "Wenn sie zwischen den Langstielpilzen hindurchwandern, sammeln sich allerlei fruchtbare Sporen an den Gliedmaßen der Sporensegler und Marschenläufer.\n\nWie Ihr sehen könnt, ist unser Volk sehr klein, also haben wir nur wenige Möglichkeiten, diese Sporen zu sammeln. Haltet nach Sporenseglern und Marschenläufern Ausschau und sammelt die fruchtbaren Sporen. Ganz Sporeggar stünde tief in Eurer Schuld.", sourceObjective = "Sammelt 6 fruchtbare Sporen von den Sporenseglern und den Marschenläufern und kehrt danach zu Gshaff in Sporeggar zurück.", progress = "Ihr seid zurück, {name}. Habt Ihr die fruchtbaren Sporen bekommen?", completion = "Diese Sporen sind perfekt, {name}! Die Langstielpilze sind für den Wiederaufbau unseres Dorfs unerlässlich. Und seit den Angriffen der Sumpflords, die wir erdulden mussten, sind unsere Vorräte knapp!", sourceObjectiveStatus = "unverified-source-field" }
quests[9807] = { id = 9807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr fruchtbare Sporen", progress = "Wir können immer noch mehr fruchtbare Sporen gebrauchen, {race}. Langstielpilze sind unglaublich nützlich. Wir können sehr viel mit ihnen anstellen, wenn wir sie anbauen.", completion = "Eure Hilfe wird sehr geschätzt, {name}. Ihr werdet uns doch weiterhin helfen, oder?" }
quests[9808] = { id = 9808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühkappenpilze", description = "Ich habe gesehen, dass Ihr glänzende runde Metallstücke benutzt, um sie gegen Dinge einzutauschen, die Ihr haben möchtet. Wir benutzen glänzende runde Pilze als Zahlungsmittel.\n\nDie Glühkappenpilze wachsen überall in den Marschen, man muss nur wissen, wie man sie richtig sammelt ohne sie zu zerstören. Ich werde Euch beibringen, wie man das tut, wenn Ihr mir versprecht, ein paar für unsere Vorräte zu sammeln. Einverstanden, {name}?", sourceObjective = "Bringt 10 Glühkappen zu Msshi'fn in Sporeggar in den Zangarmarschen.", progress = "Habt Ihr ein paar Glühkappen gefunden, {name}? Sie wachsen fast überall in den Marschen.\n\nIhr könnt sie schon von weitem leuchten sehen, wenn Ihr genau hinschaut.", completion = "Die können wir prima bei den anderen Sporlingen gegen Essen und Vorräte eintauschen. Sporeggar dankt Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9809] = { id = 9809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Glühkappen", progress = "Wenn Ihr noch mehr Glühkappen habt, nehme ich sie Euch gerne ab. Unser Dorf kann sie immer gut gebrauchen.", completion = "Habt Dank, {name}. Als Ältester von Sporeggar ist es meine Aufgabe dafür zu sorgen, dass mein Volk genügend Vorräte hat. Ihr erleichtert mir diese Aufgabe ungemein." }
quests[9810] = { id = 9810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschmutzte Geist", description = "Watoosun konnte zwar den Seuchengestank loswerden, aber gleichzeitig erschuf er eine irrsinnige Geisteressenz. Eine Geisteressenz, die aus der übelsten Verderbnis entstanden ist, die es je unter Elementaren gegeben hat!\n\nIhr könnt diesen verschmutzten Sumpfgeist südwestlich von hier, tief im Sonnenwindsee, finden.\n\nSucht und vernichtet Watoosuns verschmutzte Essenz sowie jeglichen verseuchten Nachfahren, den sie erschaffen haben möge.", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr Watoosuns verschmutzte Essenz und 8 Seewoger tötet.", completion = "Die Elemente haben Euren Sieg besungen, als Ihr die verschmutzte Essenz getötet habt. Der Irdene Ring dankt Euch und möchte, dass Ihr Euch eine Belohnung aussucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9811] = { id = 9811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund der Sin'dorei", description = "Dies ist der Beginn eines neuen Zeitalters in der Geschichte der Blutelfen {name}. Ihr habt geholfen, den Bund zwischen unserem und Eurem Volk zu festigen, {race}.\n\nBringt den Kopf des Verräters nach Silbermond zum Lordregenten Lor'themar Theron. Er wird begierig sein, die Neuigkeit zu erfahren.", sourceObjective = "Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond.", progress = "Ihr wünscht eine Audienz bei mir, {class}? Ich kann mich nicht an eine Verabredung erinnern.", completion = "Ihr habt Dar'Khan also getötet, {race}? Beeindruckend. Ich habe das Gefühl, dass unsere und Eure Leute bald gute Freunde sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9812] = { id = 9812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesandter zur Horde", description = "Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertigwerden?\n\nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.\n\nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, {name}. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.", sourceObjective = "Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[9813] = { id = 9813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begegnung mit den Orcs", description = "Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Zähnen und Klauen darum gekämpft, dass Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.\n\nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zu Saurfang in Orgrimmar. Als Anführer der Orcs muss auch seine Meinung zu der Bitte der Sin'dorei gehört werden.\n\nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.", sourceObjective = "Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zu Hochfürst Saurfang nach Orgrimmar, der Hauptstadt von Durotar, bringt.", progress = "Ja, {class}?", completion = "<Saurfang beginnt, den Brief zu lesen.>\n\nDie Blutelfen kümmern sich also endlich um das kleine Problem. Es ist nicht weiter überraschend, dass Ihr und ein ganzes Regiment der Verlassenen dafür gebraucht wurdet.\n\n<Saurfang bricht in Gelächter aus.>\n\nIch nehme an, wir können das hier nicht aufhalten. Schließlich brauchen wir sie genauso sehr wie sie uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[9814] = { id = 9814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berstkappenpilze, Mann!", description = "Mögt Ihr Pilze, Mann? Es gibt einen ganz mächtigen hier in den Zangarmarschen, wächst gleich in der Nähe von Zabra'jin.\n\nIhr müsst aber vorsichtig sein, Mann. Man nennt sie aus gutem Grund Berstkappenpilze. Wenn man ohne entsprechende Vorsichtsmaßnahmen zu nahe an sie herangeht, geht ihnen der Hut hoch! Puff! Und dann steht man in einer Wolke von giftigen Sporen.\n\nIch habe sie benutzt, um die Zukunft vorauszusagen, aber jetzt sind sie fast alle.", sourceObjective = "Bringt Hexendoktor Tor'gash 6 Berstkappen.", progress = "Habt Ihr die Pilze, Mann?", completion = "Die sind klasse, Mann!\n\nIch sag' Euch was. Weil Ihr so nett wart und mir mit den Pilzen geholfen habt, dürft Ihr beim Spaß dabei sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9815] = { id = 9815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammtauchen", description = "Die am schwersten betroffenen Wasserelementare befinden sich im Halaanibecken, südwestlich von hier unterhalb der verlassenen Stadt Halaa. Während einige der verzweifelten Elementare ohne Folgen für die Umwelt zerstört werden können, müssen die Überreste der Schlammkreaturen nach ihrer Zerstörung entfernt werden.\n\nDie Schlammkreaturen hinterlassen nämlich verseuchte Leichenteile, die der Umwelt schaden können, wenn man sie liegen lässt.\n\nVernichtet diese Schlammkreaturen und bringt mir ihre schlammbesudelten Kerne.", sourceObjective = "Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 5 schlammbesudelte Kerne besorgt.", progress = "Lasst keinen verseuchten Schlamm zurück!", completion = "Der Irdene Ring dankt Euch, {name}. Auch die Elemente sind Euch dankbar. Eure wiederholten Bemühungen, unsere Welt zu reinigen, werden sehr geschätzt und sicher nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9816] = { id = 9816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr so was schon mal gesehen?", description = "In diesen Marschen fehlt was, Mann! Keine Murlocs hier.\n\nKeine Sorge, Mann, ich habe eine Lösung für dieses Problem. Seht Ihr Gargel und Gurgel da drüben? Ich habe vor, den Verirrten ein paar Murlocs zu schenken!\n\nBringt diesen Käfig nach Dolchfenn und lasst sie bei der Ansammlung von Hütten im Nordosten frei. Nun gut, ich möchte Euch nicht Gargel und Gurgel auf den Hals jagen, aber ich gebe Euch einen Käfig mit jungen bunten Murlocs. Setzt den Käfig einfach auf den flachen Stein, den Ihr dort finden werdet, und öffnet die Tür!", sourceObjective = "Bringt den Murlockäfig nach Dolchfenn und stellt ihn auf den flachen Stein in der Nähe des Dorfs.", completion = "Ausgezeichnete Arbeit, Mann! Ich hoffe, sie hatten Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9817] = { id = 9817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführerin der Blutschuppen", description = "Hiermit setzt die Expedition des Cenarius ein Kopfgeld auf Rajis Fyashe, Anführerin der Blutschuppennaga, aus. Die Nagazauberin wurde zuletzt am Schlangensee gesehen, im Nordwesten der Zangarmarschen.\n\nDie Blutschuppen sind als extrem gefährlich einzustufen, und ihre Anführerin sollte mit äußerster Vorsicht behandelt werden.\n\nDas Kopfgeld kann bei Aufseher Hamuht in der Zuflucht des Cenarius eingefordert werden.", sourceObjective = "Tötet Rajis Fyashe am Schlangensee und kehrt dann zu Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten.", completion = "Ich wette, die Blutschuppen überlegen es sich nun zweimal, bevor sie unsere Späher nochmals angreifen. Nehmt dies als Belohnung, {name}. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9818] = { id = 9818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Untergrund", description = "Etwas schändet den Untergrund. Es schlägt den Boden, als wollte es ihn bestrafen.\n\n*Rums*\n\n<Untrag schlägt sich mit der Faust auf die Brust.>\n\nSo klingt das hunderttausendmal. Endlos. Die Erde taumelt. Sie ruft nach uns.\n\nGordawg spricht mit mir. Gordawg weiß, dass etwas die Elementare hervortreibt. Etwas unter der Erde.\n\nGeht jetzt und sprecht mit Gordawg. Nein, hört ihm zu, sprecht nicht. Hört Gordawg an...", sourceObjective = "Kommuniziert mit Gordawg.", completion = "<Gordawg scheint Euch zuzunicken.>\n\nSetzt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9819] = { id = 9819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gequälte Erde", description = "Bestraft den Thronräuber. Ihr werdet ihn finden. Folgt Pfad aus Erde. Zuerst bringt gequälte Erdgeister zur Ruhe. Müssen wieder schlafen.\n\n<Gordawg schlägt mit seiner Faust auf den Boden und schleudert faulig riechende Erde nach oben.>\n\nMüssen schlafen!\n\n<Gordawg zeigt nach Südosten.>\n\nSucht Geister in Nähe von Bergen. Nähe von Hügeln. Nähe von Erde.\n\nBringt zur Ruhe.\n\nTelaaribecken... Südosten.", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 10 gequälte Erdgeister tötet.", progress = "Schlafen sie?", completion = "<Gordawg nickt zufrieden.>\n\nGut. Geister schlafen jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9820] = { id = 9820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Boss Grog'ak", description = "Gesucht - Tot oder lebendig: Boss Grog'ak, Vorarbeiter der Ango'rosh Pilzsammeloperation.\n\nDiese grobschlächtigen, axtschwingenden Dummköpfe sind für das Fällen von Pilzen nördlich des Dorfs verantwortlich. Wenn er nicht aufgehalten wird, werden er und seine Leute einen Pfad bis zu den Mauern von Zabra'jin schlagen!\n\nWer Boss Grog'aks Kopf zu Schattenjäger Denjai bringt, soll reich belohnt werden.", sourceObjective = "Bringt den Kopf von Boss Grog'ak zu Schattenjäger Denjai in Zabra'jin.", progress = "Was habt Ihr da, {name}?", completion = "Gut gemacht, {name}. Die Anwesenheit dieser Oger so nah an unserem Außenposten hat mich ein wenig beunruhigt. Es scheint, als kämen sie seit einiger Zeit die Berge im Norden herunter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9821] = { id = 9821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammnis schmecken", description = "<Gordawg nimmt einen Stein und fängt an darauf herumzukauen.>\n\nGordawg schmeckt. Gordawg weiß wo diese Erde war.\n\n<Gordawg hebt eines seiner massiven Beine und stampft auf den Boden.>\n\nSchaut. Schaut Nagrand an.\n\n<Gordawg zeigt auf seinen Fußabdruck. Im Abdruck seht Ihr eine perfekte geologische Karte von Nagrand, auf der alle Stellen markiert sind, an denen die Elementare, die Ihr für Gordawg zerstören sollt, sich aufhalten.>\n\nZERSTÖRT SIE! Bringt Gordawg die Stücke zum Essen.\n\nNehmt die Karte.", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr ihm 10 Kerne eines wütenden Zermalmers bringt.", progress = "Gordawg isst den Stein. Gordawg findet den Thronräuber. Bringt Stein!", completion = "<Gordawg spuckt den gekauten Stein aus, woraufhin ein Steinschauer auf Euch herabrieselt.>\n\nGift. Diese Felsen sind nicht Nagrand. Diese Felsen sind vergiftet. Ihr zerstört Giftfels. Ihr findet Thronräuber.", sourceObjectiveStatus = "unverified-source-field" }
quests[9822] = { id = 9822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohender Angriff", description = "Die Position der Pilzsammeloperation der Oger kann kein Zufall sein. Ich werde den Verdacht einfach nicht los, dass sie einen Angriff auf Zabra'jin planen.\n\nIch muss das genau wissen, {name}. Die Oger haben einen weiteren Außenposten im Nordwesten beim Grund der Ango'rosh. Wenn sie tatsächlich vorhaben uns anzugreifen, dann werden wir dort sicher Beweise für ihre Pläne finden. Geht dorthin, {name}, und durchsucht das Lager. Bringt mir alles, was auch nur im Geringsten verdächtig sein könnte!", sourceObjective = "Bringt die Angriffspläne der Ango'rosh zu Schattenjäger Denjai in Zabra'jin.", progress = "Habt Ihr einen Beweis für die Pläne der Oger gefunden?", completion = "<Schattenjäger Denjai untersucht die Pläne.>\n\nIch wusste es! Der Gestank eines Ogers hat immer etwas Bedrohliches an sich. Jetzt, da wir einen Beweis für ihren Plan haben, müssen wir ihnen zuvorkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9823] = { id = 9823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie oder wir", description = "Um die Bedrohung, die von den Ango'rosh ausgeht, zu beenden, müssen wir ihren Oberanführer Schmetterfaust töten. Aber wir werden sogar noch viel mehr tun. Wir werden mit dem Oberanführer und seinem Gefolge ein Zeichen setzen.\n\nGeht zur Festung der Ango'rosh und kümmert Euch um unsere Feinde. Die Feste befindet sich in einer Höhle auf einer kleinen Insel nordwestlich von Zabra'jin. Dort werdet Ihr eine Brücke, die aus einem umgefallenen Pilz besteht, finden.\n\nZeigt kein Erbarmen, {name}. Sie würden sicher keinen von uns verschonen.", sourceObjective = "Tötet Oberanführer Schmetterfaust, 10 Raufer der Ango'rosh, 10 Seelenfresser der Ango'rosh und meldet Euch dann bei Schattenjäger Denjai in Zabra'jin zurück.", completion = "Unser Sieg über die Ango'rosh muss gefeiert werden, {name}. Ich frage mich, wie lange es wohl dauert, bis diese Grobiane einen neuen, blutrünstigen Anführer gefunden haben.\n\nGanz gleich, wir werden auf sie vorbereitet sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9824] = { id = 9824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Störungen", description = "Ich versuche, eine Aufzeichnung von Karazhans Energie zu erstellen... für ein privates Projekt natürlich. Unglücklicherweise empfange ich hier oben einfach nichts. Wenn ich in die Nähe einer unterirdischen Wasserquelle gelangen könnte, könnten meine Kristalle die Signale viel leichter empfangen.\n\nIch habe sowohl von einem unterirdischen Teich als auch von einem Brunnen in einem Keller unter uns gehört. Dieser ganze Ort ist jedoch voll von Geistern, und sich dort hinzuwagen wäre für jemanden in meinem Alter viel zu gefährlich. Was sagt Ihr? Werdet Ihr einem alten Mann helfen und das Aufzeichnen für mich übernehmen?", sourceObjective = "Benutzt den violetten Aufzeichnungskristall in der Nähe von unterirdischen Wasserquellen im Keller des Meisters und kehrt zu Erzmagier Alturus außerhalb von Karazhan zurück.", completion = "Diese Aufzeichnungen verheißen nichts Gutes, {name}. Karazhan sollte alle möglichen arkane Ströme ausstrahlen... stattdessen herrscht dort nun ein riesiges Energievakuum. Keine Signale. Nichts. Außer einem sehr schwachen dämonischen Echo.\n\nDas sind schlechte Nachrichten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9825] = { id = 9825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastlose Aktivität", description = "Wie Ihr sicher bemerkt habt, wimmelt es außerhalb von Karazhan nur so von Geistwesen. Der Grund ihrer Existenz ist unbekannt, und Unbekanntes mag ich gar nicht leiden!\n\nBringt mir ihre geisterhafte Essenz, damit ich ihre Beschaffenheit untersuchen kann. Karazhan hat viele Geheimnisse, {name}. Und ich werde sie alle lüften.", sourceObjective = "Bringt 10 geisterhafte Essenzen zu Erzmagier Alturus außerhalb von Karazhan.", completion = "Faszinierend. Ich werde die Essenzen untersuchen, {name}. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9826] = { id = 9826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalarankontaktpersonen", description = "Diese Zeichen bedeuten nichts Gutes für uns, {name}. Ich hatte es noch nie so mit Geheimhaltung, deshalb erzähle ich Euch ein wenig über meine Organisation, das Violette Auge.\n\nWir sind Agenten der Kirin Tor, dem Magierrat von Dalaran. Wir wurden beauftragt, Karazhan und Medivh im Auge zu behalten, für den Fall, dass die Dinge aus dem Ruder laufen.\n\nWas sie auch taten... sehr bald nachdem Medivh verschwunden war.\n\nIn diesem Bericht stehen meine genauen Ergebnisse. Bringt ihn zu Erzmagier Cedric, er ist auch vom Violetten Auge. Ihr findet ihn am Rande des Dalarankraters.", sourceObjective = "Bringt Alturus' Bericht zu Erzmagier Cedric am Rande des Dalarankraters.", progress = "Ihr wisst vom Violetten Auge? Ihr kommt mir nicht bekannt vor.", completion = "Alturus hat Euch diese Information anvertraut? Der alte Narr.\n\nIch schätze, der Schaden ist schon angerichtet, dann können wir Euch genauso gut für uns nutzen. Ich nehme an, Ihr werdet kooperieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[9827] = { id = 9827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siechendes Basidium", description = "Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.\n\nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt, etwas mehr darüber erzählen.", sourceObjective = "Bringt das siechende Basidium zu Ruam in Telredor in den Zangarmarschen.", progress = "Was habt Ihr da, {name}?", completion = "Das sieht aus wie das Basidium eines Sumpflords, aber ich habe noch nie zuvor eines in einem solchen Zustand gesehen. Ich habe gehört, dass die Riesen im Todesmoor angefangen haben dahin zu siechen, aber es ist schon viel weiter fortgeschritten, als ich befürchtet habe.\n\nDas Todesmoor war einst ein See wie die anderen in den Marschen, und er diente als Nährgrund für die Riesen. Jetzt, da sich das Wasser zurückzieht, scheint es, als könnten sich die Riesen nicht länger vermehren. Wenn das so weitergeht, sterben die Riesen noch aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9828] = { id = 9828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siechendes Basidium", description = "Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.\n\nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt etwas mehr darüber erzählen.", sourceObjective = "Bringt das siechende Basidium zu Reavij im Sumpfrattenposten in den Zangarmarschen.", progress = "Was habt Ihr da, {name}?", completion = "Das sieht aus wie das Basidium eines Sumpflords, aber ich habe noch nie zuvor eines in einem solchen Zustand gesehen. Ich habe gehört, dass die Riesen im Todesmoor angefangen haben dahin zu siechen, aber es ist schon viel weiter fortgeschritten, als ich befürchtet habe.\n\nDas Todesmoor war einst ein See wie kein anderer in den Marschen, und er diente als Nährgrund für die Riesen. Jetzt, da sich das Wasser zurückzieht, scheint es, als könnten sich die Riesen nicht länger vermehren. Wenn das so weitergeht, sterben die Riesen noch aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9829] = { id = 9829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar", description = "Alturus' Bericht ist beunruhigend. Wir dachten, es sei ein schlechtes Zeichen, als Karazhan sich von der Umwelt abgeschottet hat. Wir hatten dort Agenten, von denen wir nie wieder gehört haben. Und nun diese... dämonische Strömung. Wir müssen das untersuchen.\n\nDie Einzigen, die Karazhan wieder öffnen könnten, hielt man für tot: Khadgar und Medivh.\n\nWährend wir hoffen, das Letzterer tatsächlich tot ist, haben wir kürzlich in Erfahrung gebracht, dass sein Lehrling, Khadgar, gesund und munter an einem Ort namens Shattrath lebt. Findet ihn und gebt ihm Alturus' Bericht.", sourceObjective = "Bringt Alturus' Bericht zu Khadgar in Shattrath in den Wäldern von Terokkar.", completion = "Das Violette Auge? Was Ihr nicht sagt.\n\nZeigt mir den Bericht, von dem Ihr sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9830] = { id = 9830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutergift", description = "Wenn ich mich mit den Draenei unterhalte, habe ich immer den Eindruck, dass sie das Gefühl haben, aus ihrer natürlichen Umgebung herausgerissen zu sein. Viele scheinen meine Brüder und Schwestern, die Zerschlagenen, zu bedauern, weil sie glauben, dass wir etwas verloren haben.\n\nWir Zerschlagenen haben vielleicht unsere Verbindung zum Licht verloren, aber unsere Erfahrung hat uns enger an das Land gebunden.\n\nMein Volk erkennt Möglichkeiten, die den Draenei verschlossen bleiben. Nehmt zum Beispiel das Gift der Sumpflichtbluter, die im Süden und Westen leben. Es ist vielseitig einsetzbar, ob für die Jagd oder zur Heilung.", sourceObjective = "Bringt 6 Einheiten Sumpflichtblutergift zu Puluu in der Oreborzuflucht.", progress = "Ich hoffe, ich kann die Vorzüge des Fennblutergifts Anachoret Ahuurn und den anderen in Telredor zeigen. Aber dafür werde ich meine Vorräte verdoppeln müssen.", completion = "Vielen Dank für das Gift, {name}. Jetzt kann ich es den anderen vorführen ohne meine eigenen Vorräte anfassen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9831] = { id = 9831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Karazhan", description = "Die Neuigkeiten in diesem Bericht beunruhigen mich sehr, {name}. Es wird jedoch schwierig, sich Zugang zu Karazhan zu beschaffen.\n\nAls klar wurde, dass ich hier gestrandet bin, habe ich den Schlüssel in drei Teile zerbrochen.\n\nIch habe die Schlüsselfragmente in verzauberte Behälter gelegt, und diese dann an damals sicheren Plätzen versteckt.\n\nWegen der dunklen Veränderungen, die die Scherbenwelt durchmachen musste, sind sie heute allerdings alles andere als sicher. Das erste Fragment ist in einem Teil von Auchindoun versteckt, der nun vom Schattenrat beherrscht wird. Bringt mir dieses Fragment zurück.", sourceObjective = "Khadgar möchte, dass Ihr das Schattenlabyrinth von Auchindoun betretet und das erste Schlüsselfragment aus einem versteckten arkanen Behälter besorgt.", completion = "Das habt Ihr gut gemacht, {name}. Ich war mir nicht sicher, ob Ihr Erfolg haben würdet.\n\nDie Behälter sind mit einem mächtigen Zauber belegt, der sie vor unwürdigen Augen beschützt. Ich bin froh, dass sie Euch nicht täuschen konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9832] = { id = 9832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zweite und das dritte Fragment", description = "Ich habe das zweite Fragment am Boden des Schlangensees versteckt, noch lange bevor er so hieß. Der gigantische Ablauf, der dort installiert wurde, nachdem die Naga den Ort in Beschlag genommen hatten, hat den Behälter wahrscheinlich in die Tiefen des Echsenkessels gesogen.\n\nDas dritte Fragment wird eine besonders große Herausforderung werden, da ich es in der Festung der Stürme gelassen habe, als die Naaru dort noch herrschten. Kael'thas regiert dort jetzt, und das Zimmer, in dem sich das Fragment befindet, ist jetzt ein Gefängnis.\n\nBringt mir diese beiden Fragmente, {name}. Von Eurem Erfolg hängt viel ab.", sourceObjective = "Besorgt das zweite Schlüsselfragment aus einem arkanen Behälter im Echsenkessel und das dritte Schlüsselfragment aus einem arkanen Behälter in der Festung der Stürme. Kehrt dann zu Khadgar in Shattrath zurück.", progress = "Wie kommt Ihr mit der Suche nach den Schlüsselfragmenten voran, {name}?", completion = "Ihr habt die Fragmente. Ich bin sehr beeindruckt, {name}. Ihr habt bewiesen, dass Ihr es wert seid, den Schlüssel zu Karazhan zu besitzen.\n\nBleibt nur noch ein kleines Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[9833] = { id = 9833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachrichtenwege", description = "Einer der Gründe, warum uns Ikuti in die Zangarmarschen geführt hat, ist der Versuch, die Kommunikation zwischen den Draenei und Telaar, der Heimatstadt der Kurenai in Nagrand, zu verbessern. Damit die Boten schnell zwischen Telaar und Telredor hin- und herreisen können, müssen die Straßen sicher gemacht werden.\n\nAuf unserem Weg hierher wurden wir oft von Marschenfangschlitzern angegriffen. Wir konnten sie zwar abwehren, aber für einen einzelnen Boten wären sie eine besondere Bedrohung. Ihre Reihen etwas zu lichten würde viel zur Sicherheit unserer Boten beitragen.", sourceObjective = "Puluu in der Oreborzuflucht möchte, dass Ihr 12 Marschenfangschlitzer tötet.", completion = "Das sind wundervolle Nachrichten. Der Weg ist zwar immer noch nicht sicher, aber unsere Boten sind schlau und erfinderisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9834] = { id = 9834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Rüstung", description = "Maktu kann einen Draenei über Meilen hinweg an seiner schimmernden Rüstung erkennen, sogar in diesem düsteren Sumpf!\n\nMaktu will sie auslachen, aber dann erinnert er sich, dass sie nett zu den Kurenai waren, und will ihnen beibringen, wie Kurenai Rüstung herstellen.\n\nDie dunklen, schuppigen Bälge der Fennklauen ergeben die beste Rüstung, die Maktu je getragen hat. Wenn {name} Maktu ein paar dieser Bälge von den Fennklauenhauern tief im Schlangensee bringen kann, teilt er gerne seine Rüstung mit {name}.", sourceObjective = "Bringt 8 Fennklauenbälge zu Maktu in der Oreborzuflucht.", progress = "Hat {name} die Bälge für Maktu?", completion = "Das sind gute Bälge, findet Maktu. Sie werden sehr gute Rüstung geben.\n\nWer weiß? Vielleicht sind es genug, damit Maktu ein paar Rüstungen für die Draenei machen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9835] = { id = 9835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordringen der Ango'rosh", description = "Die kleine Gruppe von Zerschlagenen, die Ihr dort seht, sind Gesandte einer Siedlung in Nagrand. Die Kurenai, wie wir uns selbst nennen, sind Zerschlagene, die sich gerne mit den Draenei wiedervereinen möchten.\n\nMeine Gruppe ist hierhergekommen, um die Bande zwischen den Kurenai und den Draenei in Telredor zu stärken.\n\nWenn es nach den Ogern der Ango'rosh geht, wird dieser Tempel nicht mehr lange stehen. Sie haben die hohen Pilze des Prügelsumpfs vollständig gerodet und kommen immer näher an unsere Zuflucht heran. Wenn Ihr <ein Freund/eine Freundin> unseres Volkes sein möchtet, dann helft uns, diesen Feind zu besiegen.", sourceObjective = "Tötet 10 Oger der Ango'rosh und 5 Schamanen der Ango'rosh und kehrt dann zu Ikuti in der Oreborzuflucht zurück.", completion = "Für den Moment ist die Bedrohung durch die Ango'rosh gebannt, aber ich bin mir sicher, dass sie nicht so leicht aufgeben werden. Ich habe vieles von meinem früheren Leben als Draenei vergessen, aber die Hartnäckigkeit der Oger hat sich in mein Gedächtnis eingebrannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9836] = { id = 9836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung des Meisters", description = "Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.\n\nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.\n\nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.", sourceObjective = "Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.", progress = "Wer seid Ihr und was wollt Ihr?", completion = "Ich erkenne diesen Schlüssel. Das ist Khadgars Schlüssel... ich habe ihn ihm natürlich noch nicht gegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9837] = { id = 9837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Khadgar", description = "Ich scheine mich an zukünftige Ereignisse, die mit Euch und diesem Schlüssel zu tun haben, zu erinnern.\n\n<Medivh schaut Euch an, als hätte er einen Geist gesehen.>\n\nEuch stehen harte Zeiten bevor, {name}. Wollen wir hoffen, dass Euch Eure Stärke nicht im Stich lassen wird.\n\nDen Schlüssel werde ich Khadgar geben, wenn er zu mir geschickt wird. Ich könnte mir keinen besseren Lehrling vorstellen.\n\nMeiner Meinung nach solltet Ihr einen eigenen Schlüssel bekommen.\n\n<Medivh fasst in seine Robe und reicht Euch seinen eigenen Schlüssel.>\n\nNun zieht weiter. Und viel Glück, {class}.", sourceObjective = "Kehrt zu Khadgar in Shattrath zurück und zeigt ihm den Schlüssel des Meisters.", completion = "Sein eigener Schlüssel? Das ist unglaublich!\n\nIch spüre keine Störungen in unserer Zeitlinie, also nehme ich an, dass dies von vorneherein so bestimmt war. Jetzt gibt es kein Zurück mehr, {name}. Der Schlüssel gehört Euch und nur Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9838] = { id = 9838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Violette Auge", description = "Ihr wurdet mit einer großen Verantwortung betraut, {name}. Wenn man den Zeichen, die das Violette Auge beobachtet hat, trauen kann, müsst Ihr ihnen helfen.\n\nTrotz all meiner Unstimmigkeiten mit Cedric halte ich die Arbeit von Männern wie Alturus immer noch für sehr wichtig. Achtet jedoch darauf, dass sie Euch nicht ausnutzen. Denkt immer daran, dass der Schlüssel an Euch gebunden ist, nicht an sie. Aber wenn die Bedrohung in Karazhan wirklich echt ist, dann sind sie am besten dafür geeignet, Euch darauf vorzubereiten. Kehrt zurück zu Alturus und helft ihm, wo immer Ihr könnt.", sourceObjective = "Sprecht mit Erzmagier Alturus außerhalb von Karazhan.", completion = "Ich schicke Euch, um einen Bericht abzuliefern, und Ihr kommt mit einem Schlüssel zurück? Es muss mehr an Euch sein, als man mit dem bloßen Auge erkennen kann, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9839] = { id = 9839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberanführer Schmetterfaust", description = "Das Herzstück jedes Ogerstamms ist sein Anführer. Ohne Anführer werden die Ango'rosh sich zurückziehen und unter sich auskämpfen, wer der nächste Anführer wird.\n\nObwohl wir die Oger überall verstreut in dieser Gegend gesichtet haben, ist die Festung der Ango'rosh im Nordwesten ihre eigentliche Machtbasis. Sie liegt in einer Höhle auf einer kleinen Insel, die nur durch einen umgestürzten Pilz mit den Marschen verbunden ist.\n\nGeht dort hin und besiegt Oberanführer Schmetterfaust. Das sollte uns eine wohlverdiente Ruhepause geben.", sourceObjective = "Ikuti möchte, dass Ihr Oberanführer Schmetterfaust und 10 Raufer der Ango'rosh tötet. Kehrt zur Oreborzuflucht zurück, wenn Ihr die Aufgabe erfüllt habt.", completion = "Endlich! Vielen Dank für die Hilfe bei der Sicherung unserer Stellung hier in der Oreborzuflucht. Ich werde den Kurenai in Telaar in Nagrand von Euren Taten berichten. Es werden sich noch viele Gelegenheiten bieten, in denen unsere Völker zusammenarbeiten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9840] = { id = 9840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung der Situation", description = "Jetzt, da wir - oder besser Ihr - einen Weg zurück in Medivhs' Turm gefunden haben, müssen wir als Erstes herausfinden, wie die Situation im Inneren aussieht.\n\nEine unserer Agentinnen hat es geschafft, sich in Karazhan einzuschleusen und hielt ihre Beobachtungen in verschlüsselten Aufzeichnungen fest. Unglücklicherweise wurden wir über ihren Tod informiert, kurz bevor Karazhan geschlossen wurde. Koren, der Schmied von Karazhan, wird von uns bezahlt. Auch wenn er kein Mitglied des Violetten Auges ist, wird er uns sicher helfen können, Keannas Aufzeichnungen zu finden. Sucht ihn innerhalb von Karazhan.", sourceObjective = "Findet Koren in Karazhan.", completion = "<Koren sieht Euch unsicher an.>\n\nIch weiß nichts von diesem Violetten Auge, von dem Ihr da redet. Ich bin ein Schmied, sonst nichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[9841] = { id = 9841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tückische Mücken", description = "Ich kann mit diesem infernalen Gesumme nicht arbeiten! Könnt Ihr es hören?\n\nIch bekomme es nicht mehr aus meinem Kopf! Ich weiß genau, wer dieses Geräusch verursacht, Sumpflichtbluter! Das Geräusch kommt immer vom Süden und vom Westen des Dorfs her.\n\nSie sind zu groß, um sie mit einer Fliegenklappe zu erschlagen, sie unter dem Fuß zu zerquetschen oder fortzuwedeln. Der einzige Weg dieses fürchterliche Dröhnen zu beenden ist sie zu töten. Mir ist ganz egal, wie Ihr es tut, {name}, aber bringt sie zum Schweigen!", sourceObjective = "Tötet 8 Sumpflichtbluter und kehrt dann zu Gambarinka in Zabra'jin zurück.", completion = "Dachte ich es mir, Ich kann den Unterschied schon deutlich hören. Dank Euch werde ich endlich wieder arbeiten können. Falls Ihr jemals Handwerkswaren benötigen solltet, denkt an den alten Gambarinka!", sourceObjectiveStatus = "unverified-source-field" }
quests[9842] = { id = 9842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schärfsten Klingen", description = "Das feuchte Klima der Marschen hat meine metallenen Werkzeuge stark in Mitleidenschaft gezogen. Das macht die Holzarbeiten schwerer als sonst, weshalb ich nun ganz auf Metallklingen verzichte.\n\nEs hat sich herausgestellt, dass die Marschenfangschlitzer im Süden und im Westen über Klingen verfügen, die schärfer sind als jede Metallklinge, die ich je besessen habe. Sie rosten auch nicht und nutzen sich nicht ab. Es ist nur ein wenig schwer, sie an einem Griff zu befestigen, aber ich glaube, ich habe dieses Problem bereits gelöst. Ich wäre Euch für jede Klinge, die Ihr mitbringen könnt, sehr dankbar.", sourceObjective = "Bringt 10 Marschenfangschlitzerklingen zu Gambarinka in Zabra'jin.", progress = "Habt Ihr ein paar Marschenfangklingen auftreiben können?", completion = "Die sollten mir für eine Weile genügen! Ich glaube, ein paar andere sind schon darauf aufmerksam geworden. Ich hatte schon ein paar Angebote, mir die Klingen abzukaufen. Sie nebenbei zu verkaufen könnte vielleicht ein einträglicheres Geschäft als meine herkömmlichen Waren bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9843] = { id = 9843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keannas Aufzeichnungen", description = "Wen sucht Ihr noch gleich? Keanna?\n\nIch habe einst jemanden mit diesem Namen getroffen. Sie wohnte oben in den Gästezimmern. Das hätte ich nicht verraten dürfen, oder?\n\nSagtet Ihr, Ihr gehört zum Violetten Auge? Nein, davon habe ich noch nie gehört.\n\nIch muss jetzt zurück an die Arbeit, wenn es Euch nichts ausmacht.\n\n<Koren scheint Euch schon vergessen zu haben.>", sourceObjective = "Durchsucht die Gästezimmer in Karazhan nach Keannas Aufzeichnungen und bringt sie zu Erzmagier Alturus außerhalb von Karazhan.", progress = "Keannas Aufzeichnungen... habt Ihr sie gefunden?", completion = "Ihr habt die Aufzeichnungen gefunden. Ich hoffe, dass die Information, die wir brauchen, auch hier drin stehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9844] = { id = 9844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dämonische Präsenz", description = "Keannas letzte Einträge bestätigen unseren Verdacht, dass sich eine dämonische Präsenz in Karazhan befindet.\n\nSie hat die Ankunft eines Agenten der Brennenden Legion entdeckt, der sich in der Nähe der Turmspitze aufhalten soll.\n\nIhr Eintrag endet hier.\n\nKarazhan ist ein sehr wichtiger Ort, {class}. Es ist ein Portal in den Nether, ein Leuchtfeuer, das in andere Welten scheint. Wenn es in falsche Hände gerät, sind die Folgen unvorstellbar. Das Eindringen der Dämonen muss unbedingt aufgehalten werden. Und außer Euch, {name}, hat niemand einen Schlüssel.", sourceObjective = "Erzmagier Alturus möchte, dass Ihr die dämonische Präsenz an der Turmspitze von Karazhan zerstört.", completion = "Ihr habt es geschafft! Ja, die Aufzeichnungen normalisieren sich wieder!\n\nDas müssen wir Cedric berichten. Er wird von unseren Errungenschaften sehr beeindruckt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9845] = { id = 9845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglerunglück", description = "Welch Erleichterung, dass ich endlich an einem Ort mit Wasser angekommen bin! Ich hatte schon Angst, dass es keine anständigen Fischgründe hier in der Scherbenwelt gibt.\n\nJetzt bin ich doch froh, dass ich meine Angelausrüstung mitgenommen habe. Und das Fischen läuft so weit auch ganz gut, wenn da nicht diese nichtsnutzigen Fennklauenhauer im Schlangensee wären.\n\nSie verscheuchen mir nicht nur die Fische, sondern sind auch noch frech genug, mir die Köder direkt vom Haken zu stehlen! Ich verbringe mehr Zeit damit, neue Köder anzubringen, als tatsächlich etwas zu fangen!", sourceObjective = "Tötet 10 Fennklauenhauer und kehrt dann zu Zurjaya in Zabra'jin zurück.", completion = "Ich kann es gar nicht erwarten endlich wieder angeln zu gehen. Jetzt werde ich endlich mit echten Fischen in meinem Eimer ins Dorf zurückkehren können, und Gambarinka wird sich nicht mehr über mich lustig machen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[9846] = { id = 9846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Wildfenn", description = "Der mächtigste Stamm der Verirrten in den Marschen, der Wildfennstamm, soll eine mächtige Medizin besitzen. Vielleicht ist an solchen Gerüchten nichts Wahres dran, aber ich muss allem nachgehen, was mir dabei helfen kann, die Geister dieser Welt zu lenken.\n\nFindet die Mystiker, Jäger und Druiden von Wildfenn, {name}, und nehmt Euch ihre Totems. Alles, was ich wissen muss, werde ich aus den Schnitzereien erfahren können.", sourceObjective = "Bringt 10 Schutztotems von Wildfenn zu Seherin Janidi in Zabra'jin.", progress = "Habt Ihr die Totems schon gesammelt?", completion = "Hmm... Es scheint, als wäre die eine Hälfte mit Bildern von Schlangengeistern, die andere mit Bildern von Vogelgeistern verziert. Kein Dunkelspeertroll mit Selbstachtung würde jemals Vögel verehren. Ihre Geister sind schwach, launisch und besser bei den Schamanen der Amani aufgehoben.\n\nAber die Schlange, {name}, die Schlange hat beträchtliche Kräfte und ist daher der Geist, dem ich meine Studien widmen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9847] = { id = 9847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbündeter Geist?", description = "Wir müssen herausfinden, welche Kräfte dieser Schlangengeist von Wildfenn besitzt und ob wir sie für unsere Zwecke einsetzen können. Stellt Euch nur vor, was ich alles tun könnte, wenn ich über einen Geist der Scherbenwelt befehligen könnte!\n\nNehmt dieses Totem und begebt Euch an den Fuß der Treppe zu den Ruinen von Boha'mu. Verankert das Totem dort in der Erde, den Rest wird es selbst erledigen. Der Geist dürfte nicht wissen, wer das Totem benutzt hat, bis er sich manifestiert hat.", sourceObjective = "Bringt das Wildfenntotem an den Fuß der Treppe in den Ruinen von Boha'mu und verankert es im Boden. Berichtet Seherin Janidi in Zabra'jin von Euren Beobachtungen.", progress = "Konntet Ihr den Geist von Wildfenn rufen?", completion = "<Ihr berichtet Seherin Janidi, was passiert ist, als Ihr das Totem benutzt habt.>\n\nDer Geist hat euch angegriffen? Er muss diesen Verirrten wohl mehr zugetan sein, als ich dachte. Es gibt keine Möglichkeit, ihn mir gefügig zu machen, ohne immensen Aufwand zu betreiben. Ich muss mich wohl nach einer anderen Quelle der Macht in dieser elenden Welt umsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9848] = { id = 9848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Dolchfennstamms", description = "Käfer, Käfer, Käfer! Die Marschen sind voll davon, und meine Gefährten hier scheinen ganz besessen von ihnen zu sein.\n\nNun, ich habe genug von Käfern! Etwas viel Aufregenderes hat mein Interesse geweckt. Im Westen gibt es ein Dorf der Verirrten, das Dolchfenn genannt wird.\n\nDer gesamte Stamm besteht aus hochbegabten Auftragsmördern. Ich habe gesehen, wie sie ein bestimmtes hochwirksames Gift mischen und verwenden. Ich würde liebend gerne mehr darüber erfahren, aber dazu bräuchte ich eine Abschrift des Rezepts und eine Phiole mit einer Probe des Gifts.", sourceObjective = "Bringt das Gifthandbuch von Dolchfenn und eine Giftphiole von Dolchfenn zu Timothy Daniels in der Oreborzuflucht.", progress = "War Eure Suche in Dolchfenn nach den Informationen, die ich zur Lösung des Gifträtsels benötige, erfolgreich?", completion = "<Timothy blättert das Handbuch durch.>\n\nSie benutzen Zottelkappe als Grundlage für das Gift? Nein, das kann nicht richtig sein. Zottelkappe ist nicht giftig.\n\nZottelkappe in ein Gift zu mischen ist so sinnvoll, wie einem Schurken zwei Streitkolben in die Hand zu drücken. Sicher, man kann das zwar tun, aber das entspricht nicht dem Wesen Eurer Berufung! Ich kann das einfach nicht verstehen...\n\n<Timothy räuspert sich.>\n\nNun ja, danke dass Ihr mir das hier besorgt habt. Ich werde das Gift ausprobieren, sobald die Zeit es mir erlaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9849] = { id = 9849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maskerade durchschauen", description = "<Gordawg bricht einen ebenholzfarbenen Fels von seinem Rücken ab.>\n\nIch gewähre Euch ein Stück Wut der Erde. Nehmt Gordawgs Fels und werft ihn auf den Giftfels. Zerschlagt ihre Hüllen um die Wahrheit zu erfahren. Vernichtet die Diener des Thronräubers und kehrt mit dem Namen zu Gordawg zurück.\n\nIhr findet die zerschlagenen Elemente am Ende der Welt. Südwesten.", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 30 Diener von Gurok tötet.", completion = "GUROK! Gurok hat die Elemente verraten!", sourceObjectiveStatus = "unverified-source-field" }
quests[9850] = { id = 9850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Grollhufjagd", description = "Ihr habt mir gezeigt, dass Ihr in der Lage seid, die harmlosen Exemplare der Grollhufe zu erlegen. Doch viel gefährlicher sind die Bullen.\n\nErledigt zwölf von denen. Dann könnt Ihr Euch vor mir mit Eurem Jagdgeschick brüsten.\n\nIhr findet sie überall im Westen und Süden der mittleren Regionen Nagrands.", sourceObjective = "Tötet 12 Grollhufbullen und sprecht anschließend mit Hemet Nesingwary bei Nesingwarys Safari in Nagrand, um Euer Jagdgeschick zu beweisen.", completion = "Beeindruckend, sehr beeindruckend.\n\nIhr habt Potenzial, Jungspund. Ich werde Euch die Möglichkeit geben, richtig viel Spaß zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9851] = { id = 9851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Grollhufjagd", description = "Das Grollhufweibchen Banthar ist der meistgefürchtete und am schwersten zu fassende Grollhuf der gesamten Scherbenwelt. Sie ist außerdem das Exemplar mit dem längsten Fell ihrer Gattung.\n\nMan sagt, sie treibt sich auf den Geisterfeldern in der Nähe des Oshu'gun herum.\n\nBringt mir ihr Horn, um mir endgültig Euer Können in den Jagdkünsten zu beweisen.", sourceObjective = "Erlangt das Horn von Banthar und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück.", progress = "Ein warmes Feuer und eine Frau an Eurer Seite könnt Ihr daheim finden. Hier jagen wir ernsthaft oder sterben bei dem Versuch.", completion = "Ihr habt es tatsächlich geschafft! Ihr habt Banthar erlegt! Ich habe niemals an Euch gezweifelt, {name}.\n\nHier, ich denke, das habt Ihr Euch redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9852] = { id = 9852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ultimative Beute", description = "Die Königin aller Tiere in Nagrand ist Zahna. Sie ist ein riesiger Elekk von der Sorte, wie Ihr sie woanders nie zu sehen bekommen werdet!\n\nIhr tut gut daran, Euch bei dem Namen zu erschrecken. Bach'lor, Aaskralle und Banthar sind nichts im Vergleich zu ihr. Man sagt, dass sie sich auf einer riesigen Klippe weit im Südwesten in der Nähe des Oshu'gun aufhält. Bringt mir ihr Herz, wenn Ihr Euch traut.\n\nWollt Ihr mir einen Brief für Eure Familie dalassen, falls Ihr, was sehr wahrscheinlich ist, nicht zurückkommt?", sourceObjective = "Bringt das Herz von Zahna zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand.", progress = "Es ist keine Schande zuzugeben, dass Ihr nicht den Mumm habt, eines der mächtigsten Tiere die dieses Land zu bieten hat, zu erlegen, {name}.", completion = "{name}! Ihr bringt das Herz dieses alten Zwergs zum Springen.\n\nIhr habt Euch nun bewiesen und seid in die Eliteränge aufgestiegen! Andere sind voller Angst geflüchtet, sind gestorben oder wurden unter den Füßen des Tieres zerquetscht. Ihr habt Euren Verstand, Eure List und Eure Entschlossenheit genutzt, um zu beweisen, dass Ihr die Jagd beherrscht.\n\nNehmt dies und seid gewiss, dass Ihr jederzeit zur Jagd an meiner Seite willkommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9853] = { id = 9853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurok der Thronräuber", description = "Gurok muss gerufen werden. Ihr ruft Gurok und Ihr vernichtet.\n\nIhr müsst zum Totschlägerhügel im Nordwesten gehen und suchen, wo Oger Gurok verehren. Ihr setzt Ogerschädel von Totschläger auf Guroks irdenes Brandmal. Nur dann kommt Gurok. Sieben Schädel.\n\nWenn Ihr lebt, dann bringt Guroks irdenen Kopf zu Gordawg. Gordawg zerschmettert Kopf.\n\n<Gordawg beißt die Zähne so fest zusammen, dass der Boden unter Euren Füßen bebt.>", sourceObjective = "Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr Gurok den Thronräuber zerstört und Guroks irdenen Kopf besorgt.", progress = "Gordawg isst Gurokpulver.", completion = "<Gordawg beißt fest in Guroks irdenen Kopf und bringt die Steinformation fast zum Bröckeln.>\n\nGuroks Herrschaft ist zu Ende. Die Erdelementare sind frei. Schlafen alle. Gewinner bekommt Preis!", sourceObjectiveStatus = "unverified-source-field" }
quests[9854] = { id = 9854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Windrocjagd", description = "Lebt Ihr genauso für die Jagd wie ich, {class}? Sucht Ihr die Ruhe, die Euch überkommt, wenn Ihr Euch an Eure Beute heranpirscht? Wisst Ihr, was es bedeutet, die letzten Herzschläge der erlegten Beute zu ehren? Ich werde Euch helfen, dies zu erreichen.\n\nNagrand ist ein blühendes Land, voller Leben inmitten dieser zerschlagenen Welt. Erlegt ein paar Windrocs und dann unterhalten wir uns weiter.\n\nIhr könnt sie an vielen Orten um unser Lager herum finden.", sourceObjective = "Tötet 12 Windrocs und kehrt dann zu Fitz bei Nesingwarys Safari in Nagrand zurück.", completion = "Jeder Tag ist ein Geschenk. Macht das Beste daraus. Denn schon morgen werden wir uns schneller fortbewegen als heute. Wir werden unsere Arme weiter ausbreiten und uns anstrengen, um das zu erzielen, von dem wir heute Nacht noch träumen, auch wenn wir es vielleicht nie erreichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9855] = { id = 9855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Windrocjagd", description = "Ihr müsst immer im Training bleiben, wenn Ihr eines Tages die mächtigste Beute überhaupt erlegen möchtet! Jetzt seid Ihr noch nicht dafür bereit, aber ich werde Euch auf den richtigen Weg bringen.\n\nEs gibt noch eine tödlichere Art von Windrocs. Messt Euch an den gefräßigen Windrocs! Ihr findet sie im Herzen von Nagrand, im Süden und im Südwesten.", sourceObjective = "Tötet 12 gefräßige Windrocs und kehrt dann zu Fitz bei Nesingwarys Safari in Nagrand zurück.", completion = "Ihr habt Eure Fähigkeiten erneut unter Beweis gestellt, {class}. Jetzt müsst Ihr Euch mit der wildesten Sorte von Windrocs messen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9856] = { id = 9856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Windrocjagd", description = "Ihr seid bereit, {class}. Bereit Euch der Mutter aller Windrocs zu stellen, Aaskralle! Nachdem Ihr so viele ihrer Kinder getötet habt, gebietet die Ehre, dass ihr eine Chance auf Rache gewährt wird. Ihr findet sie bei den großen Windrocs weit im Westen.\n\nWenn Ihr überleben solltet, bringt mir ihr Auge.", sourceObjective = "Bringt das Auge von Aaskralle zu Fitz bei Nesingwarys Safari in Nagrand.", progress = "Habt Ihr Euch Aaskralle schon gestellt?", completion = "Ihr Auge sieht aus, als wäre es noch am Leben. Denkt Ihr, sie kann immer noch in Eure Seele schauen?\n\n{name}, Ihr könnt Euch zu den Elitesafarijägern zählen. Und Ihr seid auf dem besten Weg, die entscheidende Beute dieses Landes zu jagen, Zahna!\n\nIhr habt Euch das hier verdient. Möge es Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9857] = { id = 9857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Talbukjagd", description = "Ich habe heute keine Lust zu jagen. Könnt Ihr das für mich übernehmen?\n\nIch habe Hemet gesagt, dass ich mich um ein paar von den Talbuks kümmern würde, die hier überall herumlaufen. Die Böcke sind besonders gut zu jagen. Ihr könnt sie in kleinen Gruppen unter den Bäumen in der Nähe finden.\n\nDenkt Ihr, Ihr könntet das für mich tun?", sourceObjective = "Tötet 12 Talbukhirsche und kehrt dann zu Harold Fährten bei Nesingwarys Safari in Nagrand zurück.", progress = "Ich bleibe hier einfach noch ein bisschen liegen. Es geht mir sicher bald besser.", completion = "Das ist schon eine tolle Geschichte...<hust>...wie Ihr all die Hirsche erlegt habt, {class}. Aber das könnt Ihr sicher noch besser. Ich habe da etwas anderes für Euch im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9858] = { id = 9858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Talbukjagd", description = "Diese verdammte Schramme macht mir echt zu schaffen. Also, habt Ihr Lust, nochmals...<hust>...für mich einzuspringen?\n\nDieses Mal werdet Ihr ein paar Dornzehrer erlegen. Sie sind härter und gerissener als die Hirsche, also seid auf der Hut. Sucht sie...<hust>..unter den Bäumen in den mittleren Gebieten Nagrands im Süden und Westen.\n\nAuf, geht los und...<hust>.. zeigt Hemet aus welchem Holz Ihr geschnitzt seid. Mir wird es schon gut gehen.", sourceObjective = "Erlegt 12 Talbukdornzehrer und kehrt dann zu Harold Fährten bei Nesingwarys Safari in Nagrand zurück.", completion = "<hust>, <hust>... {name}! Ihr habt es geschafft. Jetzt gibt es... ...nur noch eine Sache......zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9859] = { id = 9859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Talbukjagd", description = "<Schlimmer Husten.>\n\nMacht Euch keine Sorgen um...<hust>... mich. Mir geht es gut. Es ist nur ein...<hust>... Kratzer.\n\nDennoch müsst Ihr...<hust>... nochmal für mich...<hust>... einspringen.\n\nIhr müsst den großen Bach'lor, König der Hirsche...<hust>... finden.\n\nBringt mir einen seiner Hufe...<hust>, <hust>... als Beweis.\n\nEr führt seine Herde...<hust>... weit im Westen von Nagrand.", sourceObjective = "Besorgt den Huf von Bach'lor und bringt ihn zu Harold Fährten bei Nesingwarys Safari in Nagrand.", progress = "<Harold schaut geschwächt zu Euch hoch und ringt sich ein Lächeln ab.>\n\nHabt Ihr...<hust>... den Huf?", completion = "Wow! Ihr habt es geschafft! Das ist tatsächlich Bach'lors Huf!\n\nÄhm, wie es aussieht fühle ich mich schon viel besser. Hier, lasst mich Euch etwas zur Feier Eures Jägerkönnens schenken!", sourceObjectiveStatus = "unverified-source-field" }
quests[9860] = { id = 9860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Anweisungen", description = "Kehrt sofort zu Cedric zurück, {name}. Die Unterstützung, die Ihr dem Violetten Auge geleistet habt, wird nicht unbelohnt bleiben.\n\nHaltet von uns und unserer Organisation was Ihr wollt, {class}, aber in der Gunst der Erzmagier von Dalaran zu stehen ist nichts, was Ihr je bereuen werdet.", sourceObjective = "Sprecht mit Erzmagier Cedric am Rande des Dalarankraters.", completion = "Alturus hat mir erzählt, was passiert ist, {name}. Wir sind jedoch noch nicht am Ende angelangt. Solange Karazhan für die Außenwelt verschlossen ist, ist es nur eine Frage der Zeit, bis die Legion ihre Angriffe erneuert, während wir nur tatenlos zusehen können.\n\nEs sei denn natürlich, Ihr nehmt die Verantwortung, die Euch das Schicksal auferlegt hat, an.\n\n\n\nWas sagt Ihr, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9861] = { id = 9861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der heulende Wind", description = "Die formlose Elementarluftgestalt spricht in einer Sprache zu Euch, die Ihr nicht versteht. Ihr glaubt, dass es die Sprache der Elemente ist, Kalimag. Vielleicht kann Euch jemand beim Thron der Elemente mit dieser ungewöhnlichen Entdeckung weiterhelfen.", sourceObjective = "Sucht beim Thron der Elemente nach jemandem, der Kalimag sprechen kann, und zeigt der Person den heulenden Wind.", progress = "Gebt es her, schnell!", completion = "Es ist ein Notruf, {race}. Eine Macht versucht die Elemente zu untergraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9862] = { id = 9862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösewichte der Finsterblut", description = "Der Finsterblutstamm fängt die Luftgeister ein und quält sie! Die Finsterblut gehören zu meinem Volk. Sie sind ein Stamm von Zerschlagenen, der dem bösen Musel'ek, dem Sumpflord des Echsenkessels, dient.\n\nDer Luftgeist sagt, dass die Verderber der Finsterblut andere Luftgeister fangen und sie benutzen, um Chaos in den Reihen der Elemente zu säen. Wie es aussieht haben die Finsterblut vor Kurzem ein Orcdorf im Südwesten namens Sonnenwind geplündert und benutzen nun mächtige Elementarmagie, um den See aufzuwühlen. Sucht die Verderber und vernichtet sie!", sourceObjective = "Elementarist Morgh beim Thron der Elemente in Nagrand möchte, dass Ihr 5 Verderber der Finsterblut tötet.", completion = "Ihr habt gesehen, wie sie die Elemente kontrollieren? Der Wind beugt sich ihrem Willen?\n\n<Morgh versinkt für einen Moment in Gedanken.>\n\nDas ist sehr beunruhigend, {name}. Ich muss mich mit den anderen beraten.\n\nVielen Dank für Eure Mühen, {name}. Vielleicht solltet Ihr in Euer Dorf zurückkehren und Euch umhören, ob es weitere Informationen über die Finsterblut und ihre schändlichen Ziele gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9863] = { id = 9863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abscheulicher Götzendienst", description = "Ohne Führung sind wir von allen Seiten angreifbar! Die niederträchtigen Finsterblut hätten keinen besseren Zeitpunkt auswählen können, um uns anzugreifen.\n\nIn den letzten Tagen mussten wir nicht weniger als fünf Angriffe von den Zerschlagenen ertragen! Sie haben sich sogar unserer Siedlung in dieser Gegend, Sonnenwind, bemächtigt.\n\nWir müssen zurückschlagen und ihnen zeigen, das wir ganz und gar nicht machtlos sind. Erschlagt die widerlichen Götzendiener und bringt mir ihre abscheulichen Götzen! Möge der Blitz sie treffen!", sourceObjective = "Scharfseher Kurkush in Garadar in Nagrand möchte, dass Ihr ihm 10 Finsterblutgötzen bringt.", progress = "Tut es für uns, weil wir es nicht für uns selbst tun können.", completion = "Ihr habt den Söhnen des Blitzschlags neue Hoffnung gegeben, {name}. Wenn unser Anführer uns schon nicht beschützt, vielleicht können es andere tun - so wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[9864] = { id = 9864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschollene Kampftrupp", description = "Nach dem letzten Angriff der Finsterblut hat eine Gruppe von Jünglingen sich aufgemacht, um uns zu rächen. Wir haben versucht sie aufzuhalten, aber ihre Wut hat sie blind werden lassen. Es ist nun eine Woche vergangen seit wir sie das letzte Mal gesehen haben.\n\nBitte, {race}, Ihr müsst sie finden! Sie sind doch gerade erst erwachsen geworden. Wie können sie erwarten, diese Wilden besiegen zu können?\n\nSie haben die Straße nach Westen aus der Stadt genommen. Folgt dieser Straße und haltet nach Lebenszeichen unserer Jünglinge Ausschau.\n\nUnd {name}, haltet Euch von Halaa fern, wenn Euch Euer Leben lieb ist. Dort ist Kriegsgebiet.", sourceObjective = "Sucht den verschollenen Kriegstrupp von Garadar.", completion = "Ich habe Geschichten über unser Volk gehört. Sie sagen, dass wir einst Krieger waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[9865] = { id = 9865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chroniken eines Kriegers", description = "Ich kenne Euch nicht, Fremder, aber ich muss Euch um Hilfe bitten. Ich schäme mich dafür, aber ich bin nur ein einziger Orc.\n\nIn mir kochen Emotionen hoch, die ich vorher nie gekannt habe. Ich.. Ich will Rache. Blut für Blut. Kennt Euer Volk dieses Gefühl? Ich möchte meine Axt nehmen und meine Feinde in Stücke schlagen. Meine Waffe schwingen, bis meine Arme nicht mehr können und erschlaffen.\n\nDer Sonnenwindposten ist gleich südlich von dieser Prozession hier. Dort werdet Ihr unsere Feinde finden. Tötet sie... Tötet sie alle...", sourceObjective = "Tötet 20 Strauchdiebe der Finsterblut und 10 Räuber der Finsterblut.", completion = "<Saurfang dreht sich zu Euch um.>\n\nRieche ich da etwa Blut? Ich bedauere es sehr, dass ich Euch nicht helfen konnte. Wie stolz Ihr auf Euch sein müsst. Meine Brust hebt sich allein von dem Wissen, was Ihr getan habt.\n\nGibt es noch mehr wie Euch? Gibt es noch mehr Helden dort, wo Ihr herkommt?", sourceObjectiveStatus = "unverified-source-field" }
quests[9866] = { id = 9866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter...", description = "Würdet Ihr mir eine letzte Ehre erweisen, {name}? Ich möchte nicht nach Garadar zurück. Ich glaube, dass mein Schicksal woanders liegt, dass ich einst höheren Zielen folgen werde.\n\nBitte geht zu Scharfseher Corhuk und sagt ihm, dass ich nicht zurückkehren werde. Dass ich nicht zurückkehren kann. Ich muss weiterziehen... Er wird es verstehen.", sourceObjective = "Bringt die Nachricht zu Scharfseher Corhuk in Garadar.", completion = "<Scharfseher Corhuk starrt gedankenverloren auf den Boden. Er nickt zustimmend.>\n\n<Scharfseher Corhuk wischt sich eine Träne aus dem Gesicht.>\n\nDer Sohn ist der Vater... Mögen die Geister gnädig zu denen sein, die ihm im Weg stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9867] = { id = 9867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Finsterblut...", description = "Wir haben in den letzten Wochen viele Freunde verloren.\n\nSchon seit Jahrzehnten kämpfen wir gegen die Oger aus Nagrand, aber nun ist eine neue Bedrohung aufgetaucht. Der Finsterblutstamm der Zerschlagenen hat unser Fischerdorf im Südwesten, den Sonnenwindposten, angegriffen und alle Orcs, die dort lebten, getötet oder vertrieben.\n\nDie anderen sind der Meinung, dass man sie einfach wahllos töten sollte. Ich bin jedoch davon überzeugt, dass man ihren Anführer töten muss. Ich weiß zwar nicht, wer ihr Anführer ist, aber ich schätze, Ihr werdet es merken, wenn Ihr ihn seht.", sourceObjective = "Bringt Ortor von Finsterbluts Kopf zu Scharfseher Margadesh in Garadar.", progress = "Bringt mir den Kopf ihres Anführers, {name}.", completion = "Das ist also das Gesicht unseres Feindes? Ich werde den Kopf aufspießen lassen und außerhalb von Garadar aufstellen. Sollten sie je wagen, uns nochmals anzugreifen, werden sie den Folgen ihres Handelns in die Augen sehen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9868] = { id = 9868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Totem von Kar'dash", description = "Habt Dank, Fremder. Wenn Ihr nicht gewesen wärt, hätten sie mich sicherlich getötet.\n\nIch wurde vor drei Nächten von diesen Finsterblut bei einem Nachtangriff auf Garadar entführt. Was ich seitdem herausgefunden habe, wird wahrscheinlich die ganze Scherbenwelt in ihren Grundfesten erschüttern: diese Finsterlinge versuchen, das Totem von Kar'dash wiederzuerlangen! Wir können nicht zulassen, dass das Totem in die Hände der Finsterblut fällt!\n\nIhr müsst mir helfen zu fliehen. Und Fremder, falls ich es nicht bis Garadar schaffe, müsst Ihr Garrosh erzählen, was hier passiert ist...", sourceObjective = "Begleitet den festgehaltenen Mag'har aus dem Sonnenwindposten hinaus. Sprecht mit Garrosh in Garadar, wenn Ihr erfolgreich wart.", completion = "Was macht das schon? Die Großmutter liegt im Sterben. Das Leben ist nicht lebenswert...", sourceObjectiveStatus = "unverified-source-field" }
quests[9869] = { id = 9869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thron der Elemente", description = "Grüße, {race}. Ich bin Ioki, Elementarist des Irdenen Rings. Ich bin nach Telaar gekommen, um die Kurenai über den Status der Elemente zu informieren.\n\nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Telaar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.", sourceObjective = "Elementarist Ioki möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.", completion = "Ah, danke für diese Nachricht. Hättet ihr vielleicht etwas dagegen, dem Irdenen Ring zu helfen? Die Elemente sind sehr aufgewühlt, wir können alle Hilfe, die wir bekommen können, brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9870] = { id = 9870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thron der Elemente", description = "Grüße, {race}. Ich bin Yal'hah, Elementarist des Irdenen Rings. Ich bin nach Garadar gekommen, um die Mag'har über den Status der Elemente zu informieren.\n\nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Garadar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.", sourceObjective = "Elementarist Yal'hah möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.", completion = "Ah, danke für diese Nachricht. Hättet ihr vielleicht etwas dagegen, dem Irdenen Ring zu helfen? Die Elemente sind sehr aufgewühlt, wir können alle Hilfe, die wir bekommen können, brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9871] = { id = 9871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge der Finsterblut", description = "Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Telaar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Arechron in Telaar.", sourceObjective = "Bringt die Invasionspläne der Finsterblut zu Arechron nach Telaar in Nagrand.", progress = "Was gibt's?", completion = "<Arechron schlägt mit der einen Hand in die andere.>\n\nOrtor... Dieser verräterische Dreckskerl!", sourceObjectiveStatus = "unverified-source-field" }
quests[9872] = { id = 9872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge der Finsterblut", description = "Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Garadar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Garrosh in Garadar.", sourceObjective = "Bringt die Invasionspläne der Finsterblut zu Garrosh.", progress = "Was gibt es?", completion = "<Garrosh zerknüllt die Karte und wirft sie ins Feuer.>\n\nWas soll ich damit? Sie greifen uns schon seit Wochen an. Das ist nichts neues.\n\nVersteht Ihr nicht? Wir sind geliefert... Großmutter Geyah liegt im Sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9873] = { id = 9873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein alter Freund Ortor...", description = "Diese Angriffpläne wurden von jemandem geschrieben, den ich einst kannte. Ortor von Finsterblut, ein adliger Zerschlagener, bewandert in der Beherrschung der Elemente, der nun den dummen, stinkenden Lakai für Sumpffürst Musel'ek spielt.\n\nDie Pläne besagen, dass sie ein Orcdorf nordwestlich von hier, das als Sonnenwindposten bekannt ist, eingenommen haben.\n\nReist zum Sonnenwindposten und erlöst die Welt von Ortor von Finsterblut. Es geschieht zum Wohl aller...", sourceObjective = "Arechron in Telaar in Nagrand möchte, dass Ihr Ortor von Finsterblut tötet.", completion = "Tausend tote Orcs sagt Ihr? Was könnte wohl der Auslöser für solch ein unverfrorenes Vordringen in Orcgebiet sein? Es ist gut, dass er tot ist, aber da steckt mehr dahinter, als ein Tentakel fühlen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9874] = { id = 9874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung eindämmen", description = "Ich habe gerade von einer Katastrophe mit epischen Ausmaßen erfahren, {name}. Die niederträchtigen Finsterblut haben das Orcdorf Sonnenwind nordwestlich von hier eingenommen und seine Einwohner getötet. Was das Ganze noch verschlimmert ist, dass sie begonnen haben, die Leichen in den Sonnenwindsee zu werfen. Wenn die Leichen dort verrotten, wird unsere Hauptwasserquelle in dieser Gegend verseucht werden.\n\nEs ist eine grauenvolle Aufgabe, die ich Euch übertrage, aber sie muss erledigt werden. Nehmt diese verzauberte Fackel und kehrt zum Sonnenwindposten zurück. Verbrennt alle verrottenden Orcleichen...", sourceObjective = "Otonbu der Weise in Telaar in Nagrand möchte, dass Ihr die Fackel des flüssigen Feuers benutzt, um 10 Leichen von Bewohnern von Sonnenwind zu zerstören. Bringt die Fackel des flüssigen Feuers zurück, wenn Ihr fertig seid.", progress = "Die Orcs werden nicht verstehen, warum wir das tun, aber es muss getan werden. Für das Wohl der Orcs sowie der Zerschlagenen.", completion = "<Otonbu seufzt.>\n\nDas macht uns jegliche Hoffnung auf Frieden mit den Orcs für weitere zehn Jahre zunichte. Zumindest werden wir diese zehn Jahre noch erleben, was wir vielleicht nicht hätten, wenn die Leichen im See verrottet wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[9875] = { id = 9875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht katalogisierte Gattung", description = "Lauranna muss diese besondere Pflanze übersehen haben. Ihr seid Euch sicher, dass Ihr eine Gattung gefunden habt, die noch nicht in Laurannas Buch katalogisiert ist. Ihr solltet sie ihr am besten zeigen, um zu sehen, was sie davon hält.", sourceObjective = "Bringt die nicht katalogisierte Gattung zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet?", completion = "Eine neue Gattung! Seid Ihr sicher?\n\n<Lauranna blättert die Notizen und Diagramme durch.>\n\nToll gemacht, {name}. Wir werden sie unserer Liste hinzufügen. Was haltet Ihr von \"Violettblättriges Hehlerusium\"? Ich finde, das ist ein klangvoller Name.", sourceObjectiveStatus = "unverified-source-field" }
quests[9876] = { id = 9876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlgeschlagene Operation", description = "Ich habe eine kleine Gruppe von Druiden losgeschickt, um den Ablauf, den Ihr im Schlangensee gefunden habt, zu untersuchen. Eigentlich hätten sie kurz darauf zurückkommen müssen. Nun ja, sie sind nicht zurückgekehrt.\n\nIhr zählt zu unseren stärksten Verbündeten. Bitte sucht sie und findet heraus, was ihnen zugestoßen ist.", sourceObjective = "Ysiel Windsänger möchte, dass Ihr am Eingang des Echsenkessels in den Zangarmarschen nach Lebenszeichen der Druiden der Expedition des Cenarius Ausschau haltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9877] = { id = 9877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Regenerationsgebräu", description = "Der Kampf gegen die Geißel verläuft nicht ohne Opfer. Viele fallen jeden Tag, doch einige erwartet ein noch schlimmeres Schicksal.\n\nOft nimmt sie Gefangene. Der Tod wäre dem, was sie in der Todesfestung erwartet, vorzuziehen. Sie werden verhört und gefoltert, während sie unter dem Einfluss eines schrecklichen, willensbrechenden Giftes stehen.\n\nApotheker Renzithen in Tristessa hat ein Gegenmittel entwickelt; geht zu ihm und holt das Regenerationsgebräu.", sourceObjective = "Sprecht mit Apotheker Renzithen in Tristessa.", completion = "Janeda schickt Euch, um die Gefangenen der Todesfestung zu retten? Sie muss eine hohe Meinung von Euch haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9878] = { id = 9878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lösung des Problems", description = "Das Auftauchen der Finsterblut in Nagrand hatte einen sehr negativen Einfluss auf unsere Umwelt. Die Elemente sind aufgebracht, was wiederum die Wildtiere stört. Und noch viel schlimmer: die Zerstörung des Sonnenwindpostens hat die Feindschaft der Orcs gegen mein Volk neu entflammt.\n\nDie Kurenai sind zwar ein ganz anderer Stamm als die Finsterblut, aber für einen Orc ist ein Zerschlagener ein Zerschlagener.\n\nWir müssen versuchen, dieses Dilemma zu lösen. Reist nach Nordwesten zum Sonnenwindposten und erledigt das Finsterblutproblem.", sourceObjective = "Poli'lukluk der Weisere in Telaar in Nagrand möchte, dass Ihr 10 Strauchdiebe der Finsterblut und 5 Räuber der Finsterblut tötet.", completion = "Ich glaube kaum, dass die Orcs verstehen oder zu schätzen wissen, was Ihr da getan habt, aber Eure Tat war gut für Nagrand. Vielen Dank, Problemlöser...", sourceObjectiveStatus = "unverified-source-field" }
quests[9879] = { id = 9879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Totem von Kar'dash", description = "Ich wäre schon tot, wenn Ihr nicht vorbeigekommen wärt, Fremder. Sie haben schon so viele Kurenai auf der Suche nach einem verschollenen Relikt getötet.\n\nSie suchen das Totem von Kar'dash. Ich kann nicht verstehen, warum sie glauben, dass wir etwas über dieses Totem wüssten. Ist ein Totem nicht eine typisch orcische Gerätschaft?\n\nArechron muss davon erfahren. Vielleicht weiß er, warum die Finsterblut Kurenai verschleppen und foltern, um Informationen über ein orcisches Relikt zu erfahren.\n\nLasst uns gehen bevor noch mehr kommen.", sourceObjective = "Begleitet den gefangenen Kurenai aus dem Sonnenwindposten. Sprecht mit Arechron in Telaar, wenn Ihr erfolgreich wart.", completion = "Ja, ich weiß von dem Totem... aber es gehört noch viel mehr zu dieser Geschichte. Ich darf Euch jedoch nichts darüber erzählen. Nur Auserwählte haben Zugang zu solchem Wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9880] = { id = 9880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin Cap" }
quests[9881] = { id = 9881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap" }
quests[9882] = { id = 9882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Dieben stehlen", description = "Nexusprinz Haramad hat uns verboten, mit der Arbeit im Oshu'gun loszulegen, weil er einen bestimmten mächtigen Naaru nicht verärgern will. Das hält natürlich unsere ganze Operation auf.\n\nIch glaube aber, dass ich ein Hintertürchen gefunden habe.\n\nSeht Ihr, wir sind nicht die einzigen Astralen, die von diesem riesigen Diamanten angelockt werden. Ein Dieb namens Gava'xi hat eine Gruppe von Schurken in den Oshu'gun geführt, und sie haben begonnen, große Teile aus dem Kristall herauszuschlagen.\n\nEure Aufgabe, {race}, ist es, dorthin zu gehen und unser rechtmäßiges Eigentum zurückzufordern.", sourceObjective = "Besorgt 10 Kristallfragmente von Oshu'gun und bringt sie zu Gezhe beim Aerissteg in Nagrand.", progress = "Habt Ihr die Kristallfragmente bekommen, {name}?", completion = "Ich bin beeindruckt. Die meisten sind in ausgezeichnetem Zustand.\n\nIch werde bei unserem Volk ein gutes Wort für Euch einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9883] = { id = 9883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Kristallfragmente", progress = "Ihr habt noch mehr Kristallfragmente? Nehmt aber bitte keine, die noch mit dem Berg verbunden sind. Wir wollen keinen Ärger mit den Naaru.", completion = "Bringt mir ruhig weiter Kristalle, {name}. Wir können nicht zulassen, dass diese Diebe unser Eigentum stehlen.\n\nAuch wenn es eigentlich noch gar nicht unseres ist. Theoretisch natürlich." }
